window.BLOG_DATA = {"generated":"2026-11-06T15:42:37.513Z","defaultNote":"about","about":"about","tree":[{"name":"Java","path":"Java","children":[{"name":"Collections","path":"Java/Collections","children":[{"note":"Java/Collections/Collections_Framework_Cheatsheet_EN"},{"note":"Java/Collections/Collections_Framework_Cheatsheet_PL"}]},{"name":"Concurrency","path":"Java/Concurrency","children":[{"note":"Java/Concurrency/Multithreading_Executors_Deadlocks_EN"},{"note":"Java/Concurrency/Multithreading_Executors_Deadlocks_PL"}]},{"name":"Fundamentals","path":"Java/Fundamentals","children":[{"note":"Java/Fundamentals/value and reference"}]},{"name":"heap","path":"Java/heap","children":[{"note":"Java/heap/Heap problems during float division"}]},{"name":"JVM_Internals","path":"Java/JVM_Internals","children":[{"note":"Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN"},{"note":"Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL"},{"note":"Java/JVM_Internals/JVM_Architecture_And_Classloaders_EN"},{"note":"Java/JVM_Internals/JVM_Architecture_And_Classloaders_PL"},{"note":"Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN"},{"note":"Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL"}]},{"name":"Language_Fundamentals","path":"Java/Language_Fundamentals","children":[{"note":"Java/Language_Fundamentals/Exception_Handling_And_IO_EN"},{"note":"Java/Language_Fundamentals/Exception_Handling_And_IO_PL"},{"note":"Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN"},{"note":"Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL"},{"note":"Java/Language_Fundamentals/OOP_Concepts_EN"},{"note":"Java/Language_Fundamentals/OOP_Concepts_PL"},{"note":"Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_EN"},{"note":"Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_PL"}]},{"note":"Java/garbage collection"},{"note":"Java/heap"},{"note":"Java/Record keyword"},{"note":"Java/Spring Data JPA - tips"},{"note":"Java/Spring Security"}]},{"name":"Microservices","path":"Microservices","children":[{"note":"Microservices/Spring Boot - Autentykacja z JWT_PL"},{"note":"Microservices/Spring Boot - Authentication with JWT_ENG"}]},{"name":"System design","path":"System design","children":[{"note":"System design/Common problems - ENG"},{"note":"System design/Common problems - PL"}]}],"order":["Java/Collections/Collections_Framework_Cheatsheet_EN","Java/Collections/Collections_Framework_Cheatsheet_PL","Java/Concurrency/Multithreading_Executors_Deadlocks_EN","Java/Concurrency/Multithreading_Executors_Deadlocks_PL","Java/Fundamentals/value and reference","Java/heap/Heap problems during float division","Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN","Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL","Java/JVM_Internals/JVM_Architecture_And_Classloaders_EN","Java/JVM_Internals/JVM_Architecture_And_Classloaders_PL","Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN","Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL","Java/Language_Fundamentals/Exception_Handling_And_IO_EN","Java/Language_Fundamentals/Exception_Handling_And_IO_PL","Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN","Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL","Java/Language_Fundamentals/OOP_Concepts_EN","Java/Language_Fundamentals/OOP_Concepts_PL","Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_EN","Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_PL","Java/garbage collection","Java/heap","Java/Record keyword","Java/Spring Data JPA - tips","Java/Spring Security","Microservices/Spring Boot - Autentykacja z JWT_PL","Microservices/Spring Boot - Authentication with JWT_ENG","System design/Common problems - ENG","System design/Common problems - PL"],"notes":{"Java/Collections/Collections_Framework_Cheatsheet_EN":{"title":"Collections Framework — cheatsheet","category":"Java/Collections","date":"2026-11-04","tags":["java","collections","hashmap","arraylist","treeset","concurrency","interview"],"minutes":9,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li><code>Iterable</code> → <code>Collection</code> → <code>List</code> / <code>Set</code> / <code>Queue</code>. <strong><code>Map</code> deliberately does NOT extend <code>Collection</code>.</strong></li><li><code>HashMap</code>: hash → bucket → list; since Java 8, at <strong>8 entries</strong> in a bucket the list becomes a <strong>red-black tree</strong> (O(n) → O(log n)).</li><li>Defaults: <strong><code>initialCapacity</code> = 16</strong>, <strong><code>loadFactor</code> = 0.75</strong> → 12 elements before a resize.</li><li><code>ArrayList</code> beats <code>LinkedList</code> <strong>in most real cases</strong> — <code>System.arraycopy()</code> outruns allocating <code>Node</code> objects.</li><li><strong>A <code>HashMap</code> key must be immutable.</strong> Changing a field that feeds <code>hashCode()</code> loses the entry.</li><li>A <strong>fail-fast</strong> iterator throws <code>ConcurrentModificationException</code>; a <strong>fail-safe</strong> one iterates over a copy.</li></ul></blockquote>\n<h2>The type hierarchy</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Interface</th><th>What it is</th></tr></thead><tbody><tr><td><code>Iterable</code></td><td>anything you can walk with a for-each loop</td></tr><tr><td><code>Collection</code></td><td>extends <code>Iterable</code>; adds <code>add</code>, <code>remove</code>, <code>contains</code>, <code>size</code></td></tr><tr><td><code>List</code></td><td>an <strong>ordered</strong> collection, accessible by index</td></tr><tr><td><code>Set</code></td><td>an <strong>unordered</strong> collection of <strong>distinct</strong> elements (the mathematical notion)</td></tr><tr><td><code>Queue</code></td><td>a collection with insert/remove/examine methods — a buffer before processing</td></tr><tr><td><code>Map</code></td><td><strong>does not extend <code>Collection</code></strong> — key→value pairs, unique keys, at most one value per key</td></tr></tbody></table></div>\n<blockquote><p><strong>Why isn't <code>Map</code> a <code>Collection</code>?</strong> A deliberate design choice — collections and mappings cannot sensibly be gathered under one abstraction.</p></blockquote>\n<h2><code>ArrayList</code> versus <code>LinkedList</code></h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>ArrayList</code></th><th><code>LinkedList</code></th></tr></thead><tbody><tr><td>Structure</td><td>an auto-resizing array</td><td>a <strong>doubly-linked</strong> list of <code>Node</code> objects</td></tr><tr><td>Index access</td><td><strong>O(1)</strong></td><td>O(n)</td></tr><tr><td>Insert in the middle</td><td>O(n) — shift the rest</td><td>O(1) <em>once you are there</em></td></tr><tr><td>Memory overhead</td><td>small</td><td><strong>large</strong> — every element is a separate <code>Node</code> with two references</td></tr></tbody></table></div>\n<p><strong>The conclusion interviewers are after:</strong> <code>ArrayList</code> wins <strong>almost always</strong>. Its element shifting is O(n), but it is implemented as a <strong>very fast <code>System.arraycopy()</code></strong>. <code>LinkedList</code> offers O(1) insertion but pays for it with a <code>Node</code> allocation and several reference updates — often slower in practice.</p>\n<h2>The <code>Set</code> family</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>HashSet</code></th><th><code>LinkedHashSet</code></th><th><code>TreeSet</code></th></tr></thead><tbody><tr><td>Backed by</td><td><code>HashMap</code></td><td><code>LinkedHashMap</code></td><td><code>TreeMap</code> (red-black tree)</td></tr><tr><td>Order</td><td><strong>none</strong> — iteration is &quot;shuffled&quot;</td><td><strong>insertion order</strong></td><td><strong>sorted</strong> by <code>Comparator</code> / natural order</td></tr><tr><td>Complexity</td><td>O(1)</td><td>O(1) + list overhead</td><td>O(log n)</td></tr><tr><td>Extra</td><td></td><td></td><td>implements <code>NavigableSet</code> — <code>first()</code>, <code>ceiling()</code>, <code>headSet()</code></td></tr></tbody></table></div>\n<h2>The <code>Map</code> family</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Order</th><th>Thread-safe</th><th>Complexity</th><th>Notes</th></tr></thead><tbody><tr><td><code>HashMap</code></td><td>none</td><td>❌</td><td>O(1)</td><td>the default choice</td></tr><tr><td><code>LinkedHashMap</code></td><td><strong>insertion</strong> (or access)</td><td>❌</td><td>O(1) + overhead</td><td>the basis for an LRU cache</td></tr><tr><td><code>TreeMap</code></td><td><strong>sorted</strong></td><td>❌</td><td>O(log n)</td><td>red-black tree</td></tr><tr><td><code>ConcurrentHashMap</code></td><td>none</td><td>✅</td><td>O(1)</td><td>full concurrency of retrievals — <code>get</code> <strong>does not lock</strong></td></tr><tr><td><code>Hashtable</code></td><td>none</td><td>✅</td><td>O(1)</td><td><strong>obsolete</strong> — every method is <code>synchronized</code>, blocking even independent reads</td></tr></tbody></table></div>\n<h2>How <code>HashMap</code> works inside</h2>\n<p>This is the <strong>most-asked</strong> collections question. The full answer:</p>\n<ol><li><strong>An array whose size is a power of two.</strong> Not an accident — it turns a modulo into bit masking.</li><li><strong>Insertion:</strong> the key's <code>hashCode()</code> is computed (an <code>int</code>). A number of its <strong>lower bits</strong> becomes the array index. That cell is the <strong>bucket</strong>.</li><li><strong>Array index access is O(1)</strong> — the whole point of a hash map.</li><li><strong>Collision:</strong> <code>hashCode</code> is not unique, and even different hash codes can land on the same index. Two keys end up in one bucket.</li><li><strong>Collision resolution:</strong> the bucket holds a <strong>linked list</strong> of entries. Since <strong>Java 8</strong>, when a bucket exceeds the threshold (<strong>8</strong>), the list turns into a <strong>red-black tree</strong> — lookup drops from <strong>O(n) to O(log n)</strong>.</li><li><strong>Telling keys apart:</strong> keys with the same <code>hashCode</code> but not equal coexist in the bucket. <code>HashMap</code> distinguishes them with <strong><code>equals()</code></strong>.</li><li><strong>Retrieval:</strong> compute <code>hashCode</code> → find the bucket → traverse the list/tree → call <code>equals()</code> → return the match.</li><li><strong>Resizing:</strong> when the array fills, it <strong>doubles</strong>. That triggers <strong>rehashing</strong> — rebuilding the internal structures, an expensive operation.</li></ol>\n<p><strong>Complexity:</strong> O(1) for <code>put</code> and <code>get</code>. Worst case — everything in one bucket — degrades to <strong>O(log n)</strong> (after treeification). The cure: a good hash function with a <strong>uniform distribution</strong>.</p>\n<h3><code>initialCapacity</code> and <code>loadFactor</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Parameter</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>initialCapacity</code></td><td><strong>16</strong></td><td>the internal array size, <strong>rounded up to a power of two</strong> (ask for 10, you get 16)</td></tr><tr><td><code>loadFactor</code></td><td><strong>0.75</strong></td><td>the <strong>maximum</strong> ratio of elements to buckets; exceeding it triggers a resize</td></tr></tbody></table></div>\n<p>Example: a <code>HashMap</code> with 16 buckets holding 12 elements has a load factor of 12/16 = 0.75 → <strong>the next insert resizes it</strong>.</p>\n<blockquote><p>Picking a sensible <code>initialCapacity</code> is not trivial. Guava offers <code>Maps.newHashMapWithExpectedSize()</code> and <code>Sets.newHashSetWithExpectedSize()</code>, which do the arithmetic for you. The same applies to <code>HashSet</code> — internally it is a <code>HashMap</code>.</p></blockquote>\n<h2><code>HashMap</code> and concurrency</h2>\n<p><strong>Why it is not safe:</strong> no synchronisation. Concurrent modification can produce inconsistent data, corrupted entries, and in older versions even an <strong>infinite loop</strong> during rehashing.</p>\n<pre><code class=\"language-java\">// 1. A wrapper — synchronises EVERY access, so it scales poorly\nMap&lt;String, Integer&gt; map = Collections.synchronizedMap(new HashMap&lt;&gt;());\n\n// 2. ConcurrentHashMap — the right choice under real concurrency\nMap&lt;String, Integer&gt; chm = new ConcurrentHashMap&lt;&gt;();</code></pre>\n<p><code>ConcurrentHashMap</code> locks <strong>only parts</strong> of the map (lock striping in Java 7; since Java 8, fine-grained synchronisation with <strong>CAS</strong> operations). It exposes atomic <code>computeIfAbsent</code>, <code>putIfAbsent</code>, <code>merge</code>.</p>\n<h2><code>null</code> in maps</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>null</code> key</th><th><code>null</code> value</th></tr></thead><tbody><tr><td><code>HashMap</code></td><td><strong>one</strong> — always lands in bucket 0, bypassing hashing</td><td>many</td></tr><tr><td><code>Hashtable</code></td><td>❌ <code>NullPointerException</code></td><td>❌ <code>NullPointerException</code></td></tr><tr><td><code>ConcurrentHashMap</code></td><td>❌</td><td>❌</td></tr></tbody></table></div>\n<h2>Useful <code>Map</code> methods</h2>\n<h3><code>putIfAbsent</code> versus <code>computeIfAbsent</code></h3>\n<pre><code class=\"language-java\">map.putIfAbsent(&quot;key&quot;, new ArrayList&lt;&gt;());          // the value is computed ALWAYS\nmap.computeIfAbsent(&quot;key&quot;, k -&gt; new ArrayList&lt;&gt;()); // the function runs ONLY if the key is absent</code></pre>\n<p>When building the value is expensive, <strong><code>computeIfAbsent</code> is clearly more efficient</strong> — <code>putIfAbsent</code> needs a precomputed value, so it builds one even when it will not be used.</p>\n<h3><code>merge</code></h3>\n<pre><code class=\"language-java\">map.merge(&quot;key&quot;, 1, Integer::sum);   // add 1 to the existing value, or insert 1</code></pre>\n<ul><li><strong>When to use:</strong> counting occurrences (word frequencies), accumulating values — one atomic operation instead of conditionals.</li><li><strong>When not to:</strong> if the remapping function returns <code>null</code>, the <strong>key is removed from the map</strong>.</li></ul>\n<h2>Enum collections</h2>\n<p><strong>Always</strong> use <code>EnumSet</code> and <code>EnumMap</code> when the keys are enums.</p>\n<ul><li><strong><code>EnumSet</code></strong> is simply a <strong>bit vector</strong> — a one at the position matching <code>ordinal()</code>. Membership check = check a bit.</li><li><strong><code>EnumMap</code></strong> is an <strong>array</strong> indexed by <code>ordinal()</code>. No hash codes, no collision resolution.</li></ul>\n<h2>Fail-fast versus fail-safe iterators</h2>\n<p><strong>Concurrent modification</strong> is not only a change from another thread — it also covers a change from the same thread via another iterator or directly on the collection.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Fail-fast</th><th>Fail-safe</th></tr></thead><tbody><tr><td>Who</td><td><code>HashMap</code>, <code>ArrayList</code>, non-synchronized collections</td><td><code>ConcurrentHashMap</code>, <code>CopyOnWriteArrayList</code></td></tr><tr><td>Behaviour</td><td>iterates the <strong>original</strong> structure and throws <code>ConcurrentModificationException</code> as soon as it detects a change</td><td>iterates over a <strong>copy</strong></td></tr><tr><td>Downside</td><td>the exception</td><td>heavy memory use + possibly <strong>stale</strong> data</td></tr></tbody></table></div>\n<p><strong>The classic trap:</strong></p>\n<pre><code class=\"language-java\">// ❌ ConcurrentModificationException\nfor (Map.Entry&lt;Integer, String&gt; entry : map.entrySet()) {\n    if (entry.getKey().equals(2)) {\n        map.remove(entry.getKey());\n    }\n}\n\n// ✅ Iterator.remove() — the only safe way to remove while iterating\nIterator&lt;Map.Entry&lt;Integer, String&gt;&gt; it = map.entrySet().iterator();\nwhile (it.hasNext()) {\n    Map.Entry&lt;Integer, String&gt; entry = it.next();\n    if (entry.getKey().equals(2)) {\n        it.remove();\n    }\n}</code></pre>\n<h2><code>Comparable</code> versus <code>Comparator</code></h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>Comparable</code></th><th><code>Comparator</code></th></tr></thead><tbody><tr><td>Where</td><td><strong>inside</strong> the sorted object's class</td><td>a <strong>separate</strong> class or lambda</td></tr><tr><td>Method</td><td><code>compareTo(T other)</code></td><td><code>compare(T a, T b)</code></td></tr><tr><td>Role</td><td>the <strong>natural order</strong></td><td>an <strong>alternative</strong> order</td></tr><tr><td>Example</td><td><code>Integer</code>, <code>Long</code>, <code>String</code> (lexicographic)</td><td>sorting descending</td></tr></tbody></table></div>\n<p><code>Comparable</code> lets you sort with <code>Collections.sort()</code> and sets the iteration order in <code>SortedSet</code> / <code>SortedMap</code>.</p>\n<p><code>Comparator</code> is a <strong>functional interface</strong>, so a lambda will do:</p>\n<pre><code class=\"language-java\">List&lt;Integer&gt; list = Arrays.asList(5, 2, 3, 4, 1);\n\nCollections.sort(list);                      // natural order → first is 1\nCollections.sort(list, (a, b) -&gt; b - a);     // descending    → first is 5</code></pre>\n<blockquote><p><strong>Caution:</strong> <code>(a, b) -&gt; b - a</code> overflows at extreme <code>int</code> values. In production: <code>Comparator.reverseOrder()</code> or <code>Comparator.comparingInt(...).reversed()</code>.</p></blockquote>\n<h2>Complexity table</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Operation</th><th><code>ArrayList</code></th><th><code>LinkedList</code></th><th><code>HashMap</code>/<code>HashSet</code></th><th><code>TreeMap</code>/<code>TreeSet</code></th></tr></thead><tbody><tr><td><code>get</code> by index</td><td><strong>O(1)</strong></td><td>O(n)</td><td>—</td><td>—</td></tr><tr><td><code>get</code> by key</td><td>—</td><td>—</td><td><strong>O(1)</strong></td><td>O(log n)</td></tr><tr><td><code>add</code> at the end</td><td>O(1)*</td><td><strong>O(1)</strong></td><td><strong>O(1)</strong></td><td>O(log n)</td></tr><tr><td><code>add</code> / <code>remove</code> in the middle</td><td>O(n)</td><td>O(1)**</td><td><strong>O(1)</strong></td><td>O(log n)</td></tr><tr><td><code>contains</code></td><td>O(n)</td><td>O(n)</td><td><strong>O(1)</strong></td><td>O(log n)</td></tr></tbody></table></div>\n<p>\\<em> amortised — the array occasionally grows \\</em>* once the node is found; reaching it is O(n)</p>\n<h2>Interview questions</h2>\n<p><strong>Q: How does <code>HashMap</code> work internally?</strong> <strong>A:</strong> An array of buckets sized to a power of two. The key's <code>hashCode()</code> picks the index, collisions are chained in the bucket, and since Java 8 the chain becomes a red-black tree at 8 entries. Keys within a bucket are told apart by <code>equals()</code>. Exceeding the <code>loadFactor</code> doubles the array and triggers rehashing.</p>\n<p><strong>Q: <code>ArrayList</code> or <code>LinkedList</code>?</strong> <strong>A:</strong> In practice almost always <code>ArrayList</code>. Its O(n) shifting is <code>System.arraycopy()</code>, a very fast memory operation, whereas <code>LinkedList</code>'s O(1) requires allocating a <code>Node</code> and updating references. <code>LinkedList</code> earns its place on very large lists with heavy insertion at varying positions.</p>\n<p><strong>Q: What happens when a <code>HashMap</code> key is mutable?</strong> <strong>A:</strong> Once a field feeding <code>hashCode()</code> changes, the entry <strong>disappears</strong> — the map computes a new hash, goes to a different bucket, and finds nothing. Keys must be immutable, or at least have <code>final</code> fields in <code>hashCode()</code>.</p>\n<pre><code class=\"language-java\">Map&lt;Employee, String&gt; map = new HashMap&lt;&gt;();\nEmployee emp = new Employee(1, &quot;John&quot;);\nmap.put(emp, &quot;Engineer&quot;);\nemp.setId(2);              // a field used by hashCode() changed\nmap.get(emp);              // null — the entry is &quot;lost&quot;</code></pre>\n<p><strong>Q: <code>ConcurrentHashMap</code> versus <code>Hashtable</code>?</strong> <strong>A:</strong> Both are thread-safe, but <code>Hashtable</code> synchronises <strong>every</strong> method, blocking even independent reads. <code>ConcurrentHashMap</code> locks only parts of the structure and allows fully concurrent <code>get</code>. <code>Hashtable</code> is considered obsolete.</p>\n<p><strong>Q: Fail-fast versus fail-safe?</strong> <strong>A:</strong> Fail-fast iterates the original structure and throws <code>ConcurrentModificationException</code> when it detects a modification. Fail-safe works on a copy — it throws nothing, but costs memory and may show stale data.</p>\n<p><strong>Q: How would you design an LRU cache in Java?</strong> <strong>A:</strong> A <code>LinkedHashMap</code> constructed with <code>accessOrder = true</code> and an overridden <code>removeEldestEntry()</code>. The linked list maintains access order, and the overridden method evicts the oldest entry once capacity is exceeded.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong>A mutable key in <code>HashMap</code>/<code>HashSet</code></strong> — the entry is lost.</li><li><strong>Overriding <code>equals()</code> without <code>hashCode()</code></strong> — an object put in a map becomes unfindable.</li><li><strong>Modifying a collection inside a for-each loop</strong> → <code>ConcurrentModificationException</code>. Use <code>Iterator.remove()</code>.</li><li><strong><code>Arrays.asList()</code> returns a fixed-size list</strong> — <code>add()</code> throws <code>UnsupportedOperationException</code>.</li><li><strong><code>merge</code> with a function returning <code>null</code></strong> removes the key.</li><li><strong><code>Collections.synchronizedMap</code> is not enough for iteration</strong> — that must be wrapped in <code>synchronized</code> yourself.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_EN\">Type system and language building blocks</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN\">Java 8 — lambdas, functional interfaces, streams</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_EN\">Multithreading — threads, executors, deadlocks</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_PL\">Collections Framework — ściągawka</a></p>"},"Java/Collections/Collections_Framework_Cheatsheet_PL":{"title":"Collections Framework — ściągawka","category":"Java/Collections","date":"2026-11-04","tags":["java","collections","hashmap","arraylist","treeset","concurrency","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li><code>Iterable</code> → <code>Collection</code> → <code>List</code> / <code>Set</code> / <code>Queue</code>. <strong><code>Map</code> celowo NIE dziedziczy po <code>Collection</code>.</strong></li><li><code>HashMap</code>: hash → kubełek → lista; od Java 8 przy <strong>8 wpisach</strong> w kubełku lista zamienia się w <strong>drzewo czerwono-czarne</strong> (O(n) → O(log n)).</li><li>Domyślnie <strong><code>initialCapacity</code> = 16</strong>, <strong><code>loadFactor</code> = 0.75</strong> → 12 elementów bez rozszerzenia.</li><li><code>ArrayList</code> wygrywa z <code>LinkedList</code> <strong>w większości realnych przypadków</strong> — <code>System.arraycopy()</code> bije alokację obiektów <code>Node</code>.</li><li><strong>Klucz w <code>HashMap</code> musi być niemutowalny.</strong> Zmiana pola wpływającego na <code>hashCode()</code> gubi wpis.</li><li>Iterator <strong>fail-fast</strong> rzuca <code>ConcurrentModificationException</code>; <strong>fail-safe</strong> iteruje po kopii.</li></ul></blockquote>\n<h2>Hierarchia typów</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Interfejs</th><th>Czym jest</th></tr></thead><tbody><tr><td><code>Iterable</code></td><td>wszystko, po czym da się przejść pętlą for-each</td></tr><tr><td><code>Collection</code></td><td>dziedziczy po <code>Iterable</code>; dodaje <code>add</code>, <code>remove</code>, <code>contains</code>, <code>size</code></td></tr><tr><td><code>List</code></td><td>kolekcja <strong>uporządkowana</strong>, dostęp po indeksie</td></tr><tr><td><code>Set</code></td><td>kolekcja <strong>nieuporządkowana</strong> o <strong>unikalnych</strong> elementach (jak zbiór matematyczny)</td></tr><tr><td><code>Queue</code></td><td>kolekcja z metodami wstawiania/pobierania/podglądu — bufor przed przetworzeniem</td></tr><tr><td><code>Map</code></td><td><strong>nie rozszerza <code>Collection</code></strong> — para klucz→wartość, klucze unikalne, max 1 wartość na klucz</td></tr></tbody></table></div>\n<blockquote><p><strong>Dlaczego <code>Map</code> nie jest <code>Collection</code>?</strong> Celowa decyzja projektowa — kolekcji i odwzorowania nie da się sensownie podciągnąć pod wspólną abstrakcję.</p></blockquote>\n<h2><code>ArrayList</code> kontra <code>LinkedList</code></h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>ArrayList</code></th><th><code>LinkedList</code></th></tr></thead><tbody><tr><td>Struktura</td><td>tablica z automatycznym rozszerzaniem</td><td>lista <strong>dwukierunkowa</strong> z obiektami <code>Node</code></td></tr><tr><td>Dostęp po indeksie</td><td><strong>O(1)</strong></td><td>O(n)</td></tr><tr><td>Wstawianie na środku</td><td>O(n) — przesunięcie reszty</td><td>O(1) <em>po znalezieniu miejsca</em></td></tr><tr><td>Narzut pamięciowy</td><td>mały</td><td><strong>duży</strong> — każdy element to osobny obiekt <code>Node</code> z dwiema referencjami</td></tr></tbody></table></div>\n<p><strong>Wniosek, którego oczekuje rekruter:</strong> <code>ArrayList</code> wygrywa <strong>prawie zawsze</strong>. Jego przesuwanie elementów to co prawda O(n), ale realizowane przez <strong>bardzo szybkie <code>System.arraycopy()</code></strong>. <code>LinkedList</code> ma O(1) wstawiania, ale płaci za to alokacją obiektu <code>Node</code> i aktualizacją kilku referencji — w praktyce często wolniej.</p>\n<h2>Rodzina <code>Set</code></h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>HashSet</code></th><th><code>LinkedHashSet</code></th><th><code>TreeSet</code></th></tr></thead><tbody><tr><td>Oparty na</td><td><code>HashMap</code></td><td><code>LinkedHashMap</code></td><td><code>TreeMap</code> (drzewo czerwono-czarne)</td></tr><tr><td>Kolejność</td><td><strong>brak</strong> — iteracja „przetasowana&quot;</td><td><strong>kolejność wstawiania</strong></td><td><strong>posortowana</strong> wg <code>Comparator</code> / naturalna</td></tr><tr><td>Złożoność</td><td>O(1)</td><td>O(1) + narzut listy</td><td>O(log n)</td></tr><tr><td>Dodatkowo</td><td></td><td></td><td>implementuje <code>NavigableSet</code> — <code>first()</code>, <code>ceiling()</code>, <code>headSet()</code></td></tr></tbody></table></div>\n<h2>Rodzina <code>Map</code></h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Kolejność</th><th>Wątkowo bezpieczna</th><th>Złożoność</th><th>Uwagi</th></tr></thead><tbody><tr><td><code>HashMap</code></td><td>brak</td><td>❌</td><td>O(1)</td><td>domyślny wybór</td></tr><tr><td><code>LinkedHashMap</code></td><td><strong>wstawiania</strong> (lub dostępu)</td><td>❌</td><td>O(1) + narzut</td><td>baza pod LRU cache</td></tr><tr><td><code>TreeMap</code></td><td><strong>posortowana</strong></td><td>❌</td><td>O(log n)</td><td>drzewo czerwono-czarne</td></tr><tr><td><code>ConcurrentHashMap</code></td><td>brak</td><td>✅</td><td>O(1)</td><td>pełna równoległość odczytów — <code>get</code> <strong>nie blokuje</strong></td></tr><tr><td><code>Hashtable</code></td><td>brak</td><td>✅</td><td>O(1)</td><td><strong>przestarzała</strong> — wszystkie metody <code>synchronized</code>, blokuje nawet niezależne odczyty</td></tr></tbody></table></div>\n<h2>Jak działa <code>HashMap</code> w środku</h2>\n<p>To <strong>najczęściej zadawane</strong> pytanie z kolekcji. Pełna odpowiedź:</p>\n<ol><li><strong>Tablica o rozmiarze potęgi dwójki.</strong> Nie przypadek — pozwala zamienić modulo na maskowanie bitów.</li><li><strong>Wstawianie:</strong> liczony jest <code>hashCode()</code> klucza (<code>int</code>). Pewna liczba <strong>młodszych bitów</strong> tej wartości staje się indeksem w tablicy. Ta komórka to <strong>kubełek</strong>.</li><li><strong>Dostęp po indeksie tablicy to O(1)</strong> — na tym polega cała idea hash mapy.</li><li><strong>Kolizja:</strong> <code>hashCode</code> nie jest unikalny, a nawet różne <code>hashCode</code> mogą trafić w ten sam indeks. Dwa klucze lądują w tym samym kubełku.</li><li><strong>Rozwiązanie kolizji:</strong> kubełek trzyma <strong>listę wiązaną</strong> wpisów. Od <strong>Java 8</strong>, gdy liczba wpisów w kubełku przekroczy próg (<strong>8</strong>), lista zamienia się w <strong>drzewo czerwono-czarne</strong> — wyszukiwanie spada z <strong>O(n) na O(log n)</strong>.</li><li><strong>Rozróżnianie kluczy:</strong> klucze o tym samym <code>hashCode</code>, ale nierówne, współistnieją w kubełku. <code>HashMap</code> rozróżnia je przez <strong><code>equals()</code></strong>.</li><li><strong>Odczyt:</strong> policz <code>hashCode</code> → znajdź kubełek → przejdź listę/drzewo → wywołaj <code>equals()</code> → zwróć dopasowanie.</li><li><strong>Rozszerzanie:</strong> gdy tablica się zapełni, rośnie <strong>dwukrotnie</strong>. Pociąga to <strong>rehashing</strong> — przebudowę struktur wewnętrznych, operację kosztowną.</li></ol>\n<p><strong>Złożoność:</strong> O(1) dla <code>put</code> i <code>get</code>. W najgorszym przypadku — wszystko w jednym kubełku — degraduje się do <strong>O(log n)</strong> (po treeifikacji). Lekarstwo: dobra funkcja hashująca z <strong>równomiernym rozkładem</strong>.</p>\n<h3><code>initialCapacity</code> i <code>loadFactor</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Parametr</th><th>Domyślnie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><code>initialCapacity</code></td><td><strong>16</strong></td><td>rozmiar tablicy wewnętrznej, <strong>zaokrąglany w górę do potęgi dwójki</strong> (podasz 10 → dostaniesz 16)</td></tr><tr><td><code>loadFactor</code></td><td><strong>0.75</strong></td><td><strong>maksymalny</strong> stosunek liczby elementów do liczby kubełków; po przekroczeniu następuje rozszerzenie</td></tr></tbody></table></div>\n<p>Przykład: <code>HashMap</code> z 16 kubełkami i 12 elementami ma load factor 12/16 = 0.75 → <strong>kolejne wstawienie wywoła rozszerzenie</strong>.</p>\n<blockquote><p>Dobranie sensownego <code>initialCapacity</code> nie jest trywialne. Guava ma <code>Maps.newHashMapWithExpectedSize()</code> i <code>Sets.newHashSetWithExpectedSize()</code>, które liczą to za Ciebie. To samo dotyczy <code>HashSet</code> — wewnętrznie jest to <code>HashMap</code>.</p></blockquote>\n<h2><code>HashMap</code> a wielowątkowość</h2>\n<p><strong>Dlaczego nie jest bezpieczna:</strong> brak synchronizacji. Równoległe modyfikacje mogą dać niespójne dane, uszkodzone wpisy, a w starszych wersjach nawet <strong>nieskończoną pętlę</strong> przy rehashingu.</p>\n<pre><code class=\"language-java\">// 1. Opakowanie — synchronizuje KAŻDY dostęp, więc skaluje się słabo\nMap&lt;String, Integer&gt; map = Collections.synchronizedMap(new HashMap&lt;&gt;());\n\n// 2. ConcurrentHashMap — właściwy wybór przy dużej współbieżności\nMap&lt;String, Integer&gt; chm = new ConcurrentHashMap&lt;&gt;();</code></pre>\n<p><code>ConcurrentHashMap</code> blokuje <strong>tylko fragmenty</strong> mapy (lock striping w Java 7; od Java 8 drobnoziarnista synchronizacja z operacjami <strong>CAS</strong>). Udostępnia atomowe <code>computeIfAbsent</code>, <code>putIfAbsent</code>, <code>merge</code>.</p>\n<h2><code>null</code> w mapach</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Klucz <code>null</code></th><th>Wartość <code>null</code></th></tr></thead><tbody><tr><td><code>HashMap</code></td><td><strong>jeden</strong> — trafia zawsze do kubełka 0, z pominięciem hashowania</td><td>wiele</td></tr><tr><td><code>Hashtable</code></td><td>❌ <code>NullPointerException</code></td><td>❌ <code>NullPointerException</code></td></tr><tr><td><code>ConcurrentHashMap</code></td><td>❌</td><td>❌</td></tr></tbody></table></div>\n<h2>Przydatne metody <code>Map</code></h2>\n<h3><code>putIfAbsent</code> kontra <code>computeIfAbsent</code></h3>\n<pre><code class=\"language-java\">map.putIfAbsent(&quot;key&quot;, new ArrayList&lt;&gt;());        // wartość liczona ZAWSZE\nmap.computeIfAbsent(&quot;key&quot;, k -&gt; new ArrayList&lt;&gt;()); // funkcja wołana TYLKO gdy brak klucza</code></pre>\n<p>Przy kosztownym tworzeniu wartości <strong><code>computeIfAbsent</code> jest wyraźnie efektywniejszy</strong> — <code>putIfAbsent</code> wymaga gotowej wartości, więc policzy ją nawet wtedy, gdy nie będzie potrzebna.</p>\n<h3><code>merge</code></h3>\n<pre><code class=\"language-java\">map.merge(&quot;key&quot;, 1, Integer::sum);   // +1 do istniejącej wartości albo wstaw 1</code></pre>\n<ul><li><strong>Kiedy używać:</strong> zliczanie wystąpień (częstotliwość słów), akumulacja wartości — jedna atomowa operacja zamiast <code>if</code>-ów.</li><li><strong>Kiedy nie:</strong> gdy funkcja remapująca zwróci <code>null</code>, <strong>klucz zostanie usunięty z mapy</strong>.</li></ul>\n<h2>Kolekcje dla enumów</h2>\n<p><strong>Zawsze</strong> używaj <code>EnumSet</code> i <code>EnumMap</code>, gdy klucze to enum.</p>\n<ul><li><strong><code>EnumSet</code></strong> to po prostu <strong>wektor bitowy</strong> — jedynka na pozycji odpowiadającej <code>ordinal()</code>. Sprawdzenie obecności = sprawdzenie bitu.</li><li><strong><code>EnumMap</code></strong> to <strong>tablica</strong> indeksowana przez <code>ordinal()</code>. Zero liczenia hashy, zero rozwiązywania kolizji.</li></ul>\n<h2>Iteratory fail-fast kontra fail-safe</h2>\n<p><strong>Modyfikacja współbieżna</strong> to nie tylko zmiana z innego wątku — to również zmiana z tego samego wątku przez inny iterator albo bezpośrednio na kolekcji.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Fail-fast</th><th>Fail-safe</th></tr></thead><tbody><tr><td>Kto</td><td><code>HashMap</code>, <code>ArrayList</code>, kolekcje niesynchronizowane</td><td><code>ConcurrentHashMap</code>, <code>CopyOnWriteArrayList</code></td></tr><tr><td>Zachowanie</td><td>iteruje po <strong>oryginalnej</strong> strukturze, rzuca <code>ConcurrentModificationException</code> natychmiast po wykryciu zmiany</td><td>iteruje po <strong>kopii</strong></td></tr><tr><td>Wada</td><td>wyjątek</td><td>duże zużycie pamięci + dane mogą być <strong>nieaktualne</strong></td></tr></tbody></table></div>\n<p><strong>Klasyczna pułapka:</strong></p>\n<pre><code class=\"language-java\">// ❌ ConcurrentModificationException\nfor (Map.Entry&lt;Integer, String&gt; entry : map.entrySet()) {\n    if (entry.getKey().equals(2)) {\n        map.remove(entry.getKey());\n    }\n}\n\n// ✅ Iterator.remove() — jedyny bezpieczny sposób usuwania w trakcie iteracji\nIterator&lt;Map.Entry&lt;Integer, String&gt;&gt; it = map.entrySet().iterator();\nwhile (it.hasNext()) {\n    Map.Entry&lt;Integer, String&gt; entry = it.next();\n    if (entry.getKey().equals(2)) {\n        it.remove();\n    }\n}</code></pre>\n<h2><code>Comparable</code> kontra <code>Comparator</code></h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>Comparable</code></th><th><code>Comparator</code></th></tr></thead><tbody><tr><td>Gdzie</td><td><strong>w klasie</strong> sortowanego obiektu</td><td><strong>osobna</strong> klasa lub lambda</td></tr><tr><td>Metoda</td><td><code>compareTo(T other)</code></td><td><code>compare(T a, T b)</code></td></tr><tr><td>Rola</td><td><strong>porządek naturalny</strong></td><td>porządek <strong>alternatywny</strong></td></tr><tr><td>Przykład</td><td><code>Integer</code>, <code>Long</code>, <code>String</code> (leksykograficznie)</td><td>sortowanie malejąco</td></tr></tbody></table></div>\n<p><code>Comparable</code> pozwala sortować przez <code>Collections.sort()</code> i wyznacza kolejność w <code>SortedSet</code> / <code>SortedMap</code>.</p>\n<p><code>Comparator</code> jest <strong>interfejsem funkcyjnym</strong>, więc można go zapisać lambdą:</p>\n<pre><code class=\"language-java\">List&lt;Integer&gt; list = Arrays.asList(5, 2, 3, 4, 1);\n\nCollections.sort(list);                      // porządek naturalny → pierwszy to 1\nCollections.sort(list, (a, b) -&gt; b - a);     // malejąco          → pierwszy to 5</code></pre>\n<blockquote><p><strong>Uwaga:</strong> <code>(a, b) -&gt; b - a</code> przepełnia się przy skrajnych <code>int</code>. Produkcyjnie: <code>Comparator.reverseOrder()</code> albo <code>Comparator.comparingInt(...).reversed()</code>.</p></blockquote>\n<h2>Złożoność — tabela</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Operacja</th><th><code>ArrayList</code></th><th><code>LinkedList</code></th><th><code>HashMap</code>/<code>HashSet</code></th><th><code>TreeMap</code>/<code>TreeSet</code></th></tr></thead><tbody><tr><td><code>get</code> po indeksie</td><td><strong>O(1)</strong></td><td>O(n)</td><td>—</td><td>—</td></tr><tr><td><code>get</code> po kluczu</td><td>—</td><td>—</td><td><strong>O(1)</strong></td><td>O(log n)</td></tr><tr><td><code>add</code> na koniec</td><td>O(1)*</td><td><strong>O(1)</strong></td><td><strong>O(1)</strong></td><td>O(log n)</td></tr><tr><td><code>add</code> / <code>remove</code> w środku</td><td>O(n)</td><td>O(1)**</td><td><strong>O(1)</strong></td><td>O(log n)</td></tr><tr><td><code>contains</code></td><td>O(n)</td><td>O(n)</td><td><strong>O(1)</strong></td><td>O(log n)</td></tr></tbody></table></div>\n<p>\\<em> zamortyzowane — czasem rozszerzenie tablicy \\</em>* po odnalezieniu węzła; samo dojście to O(n)</p>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Jak działa <code>HashMap</code> w środku?</strong> <strong>O:</strong> Tablica kubełków o rozmiarze potęgi dwójki. <code>hashCode()</code> klucza wyznacza indeks, kolizje rozwiązuje lista w kubełku, od Java 8 zamieniana na drzewo czerwono-czarne przy 8 wpisach. Klucze w kubełku rozróżnia <code>equals()</code>. Po przekroczeniu <code>loadFactor</code> tablica podwaja rozmiar i następuje rehashing.</p>\n<p><strong>P: <code>ArrayList</code> czy <code>LinkedList</code>?</strong> <strong>O:</strong> W praktyce prawie zawsze <code>ArrayList</code>. Jego O(n) przesuwanie to <code>System.arraycopy()</code>, czyli bardzo szybka operacja pamięciowa, podczas gdy O(1) <code>LinkedList</code> wymaga alokacji <code>Node</code> i aktualizacji referencji. <code>LinkedList</code> ma sens przy bardzo dużych listach z intensywnymi wstawieniami w różnych miejscach.</p>\n<p><strong>P: Co się stanie, gdy klucz w <code>HashMap</code> jest mutowalny?</strong> <strong>O:</strong> Po zmianie pola wpływającego na <code>hashCode()</code> wpis <strong>zniknie</strong> — mapa policzy nowy hash, trafi do innego kubełka i nic tam nie znajdzie. Klucze muszą być niemutowalne albo mieć <code>final</code> pola użyte w <code>hashCode()</code>.</p>\n<pre><code class=\"language-java\">Map&lt;Employee, String&gt; map = new HashMap&lt;&gt;();\nEmployee emp = new Employee(1, &quot;John&quot;);\nmap.put(emp, &quot;Engineer&quot;);\nemp.setId(2);              // zmiana pola użytego w hashCode()\nmap.get(emp);              // null — wpis jest &quot;zgubiony&quot;</code></pre>\n<p><strong>P: <code>ConcurrentHashMap</code> kontra <code>Hashtable</code>?</strong> <strong>O:</strong> Obie są bezpieczne wątkowo, ale <code>Hashtable</code> synchronizuje <strong>każdą</strong> metodę, więc blokuje nawet niezależne odczyty. <code>ConcurrentHashMap</code> blokuje tylko fragmenty struktury i pozwala na pełną równoległość <code>get</code>. <code>Hashtable</code> jest uznawana za przestarzałą.</p>\n<p><strong>P: Fail-fast kontra fail-safe?</strong> <strong>O:</strong> Fail-fast iteruje po oryginalnej strukturze i rzuca <code>ConcurrentModificationException</code>, gdy wykryje modyfikację. Fail-safe pracuje na kopii — nie rzuci wyjątku, ale kosztuje pamięć i może pokazywać nieaktualne dane.</p>\n<p><strong>P: Jak zaprojektować LRU cache w Javie?</strong> <strong>O:</strong> <code>LinkedHashMap</code> z konstruktorem <code>accessOrder = true</code> i nadpisanym <code>removeEldestEntry()</code>. Kolejność dostępu utrzymuje lista wiązana, a nadpisana metoda usuwa najstarszy wpis po przekroczeniu pojemności.</p>\n<h2>Pułapki</h2>\n<ul><li><strong>Mutowalny klucz w <code>HashMap</code>/<code>HashSet</code></strong> — wpis przepada.</li><li><strong>Nadpisanie <code>equals()</code> bez <code>hashCode()</code></strong> — obiekt wrzucony do mapy stanie się nieodnajdywalny.</li><li><strong>Modyfikacja kolekcji w pętli for-each</strong> → <code>ConcurrentModificationException</code>. Używaj <code>Iterator.remove()</code>.</li><li><strong><code>Arrays.asList()</code> zwraca listę o stałym rozmiarze</strong> — <code>add()</code> rzuci <code>UnsupportedOperationException</code>.</li><li><strong><code>merge</code> z funkcją zwracającą <code>null</code></strong> usuwa klucz.</li><li><strong><code>Collections.synchronizedMap</code> nie wystarcza przy iteracji</strong> — tę trzeba dodatkowo objąć <code>synchronized</code>.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_PL\">System typów i podstawowe konstrukcje języka</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL\">Java 8 — lambdy, interfejsy funkcyjne, strumienie</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_PL\">Wielowątkowość — wątki, executory, zakleszczenia</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_EN\">Collections Framework — cheatsheet</a></p>"},"Java/Concurrency/Multithreading_Executors_Deadlocks_EN":{"title":"Multithreading — threads, executors, deadlocks","category":"Java/Concurrency","date":"2026-11-04","tags":["java","concurrency","threads","executors","jmm","volatile","deadlock","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li><code>synchronized</code> gives <strong>atomicity + visibility</strong>. <code>volatile</code> gives <strong>visibility only</strong>.</li><li><code>volatile int count; count++</code> <strong>is still broken</strong> — you need <code>AtomicInteger</code> or <code>synchronized</code>.</li><li><code>sleep()</code> <strong>keeps the lock</strong>, <code>wait()</code> <strong>releases it</strong>. Always call <code>wait()</code> in a <code>while</code> loop, never an <code>if</code>.</li><li><code>parallelStream()</code> uses the <strong>common</strong> ForkJoin pool — one blocking I/O call stalls parallel streams across the <strong>whole</strong> application.</li><li><strong>Deadlock</strong> = threads are stuck (<code>BLOCKED</code>). <strong>Livelock</strong> = threads are running (<code>RUNNABLE</code>) but nothing progresses.</li><li><strong>Never swallow <code>InterruptedException</code>.</strong></li></ul></blockquote>\n<h2><code>synchronized</code> — access control</h2>\n<p>Guarantees that only <strong>one thread at a time</strong> executes a given piece of code.</p>\n<p><strong>Analogy:</strong> the toilet on a train. The toilet is the shared resource, the people in the corridor are the threads, <code>synchronized</code> is the lock on the door. Thread A enters and locks it. Thread B waits. A leaves and unlocks. Only now can B go in.</p>\n<pre><code class=\"language-java\">public class Counter {\n    private int count = 0;\n\n    // one thread at a time\n    public synchronized void increment() {\n        count++;\n    }\n}</code></pre>\n<p>Without <code>synchronized</code>, two threads doing <code>count++</code> at once can overwrite each other — instead of 2 you get 1. <code>count++</code> is really <strong>three</strong> operations: read, increment, write.</p>\n<h2><code>volatile</code> — visibility</h2>\n<p>Guarantees that a change to the variable is <strong>immediately visible</strong> to other threads.</p>\n<p><strong>Analogy:</strong> main memory (RAM) is the big noticeboard in the corridor; the CPU cache is each employee's private notepad at their desk.</p>\n<ul><li><strong>Without <code>volatile</code>:</strong> Employee A changes the status to &quot;DONE&quot; but writes it only in their notepad. Employee B looks at the noticeboard and still sees &quot;IN PROGRESS&quot; — working on stale data.</li><li><strong>With <code>volatile</code>:</strong> A is forbidden from using the notepad. Every change goes straight to the board.</li></ul>\n<pre><code class=\"language-java\">public class Worker extends Thread {\n    private volatile boolean running = true;   // the change is seen immediately\n\n    public void run() {\n        while (running) { /* work */ }\n    }\n\n    public void stopWork() {\n        running = false;   // writes straight to main memory\n    }\n}</code></pre>\n<h3>The key difference — an interview question</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>synchronized</code></th><th><code>volatile</code></th></tr></thead><tbody><tr><td>Atomicity</td><td>✅</td><td>❌</td></tr><tr><td>Visibility</td><td>✅</td><td>✅</td></tr><tr><td>Ordering (reordering)</td><td>✅</td><td>✅</td></tr><tr><td>Cost</td><td><strong>heavy</strong></td><td><strong>light</strong></td></tr></tbody></table></div>\n<blockquote><p><strong>Will <code>volatile</code> fix <code>i++</code>?</strong> <strong>No.</strong> <code>volatile</code> makes threads see the current state, but does not stop them modifying it at the same moment. For a counter you need <code>synchronized</code> or <code>AtomicInteger</code>.</p></blockquote>\n<h2><code>synchronized</code> versus <code>AtomicInteger</code></h2>\n<blockquote><p><code>synchronized</code> is a <strong>blocking (pessimistic)</strong> mechanism that <strong>parks threads</strong>, forcing an expensive <strong>context switch</strong>. <code>AtomicInteger</code> is <strong>non-blocking</strong> and rests on the processor's <strong>CAS</strong> (<em>Compare-And-Swap</em>) instruction — much faster, because threads are not parked but retry in a loop. <strong>The difference in scope:</strong> atomics protect a <strong>single variable</strong>; <code>synchronized</code> lets you execute a <strong>whole block</strong> over several variables atomically.</p></blockquote>\n<h3>The evolution of counters — performance</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Mechanism</th><th>How it works</th><th>When</th></tr></thead><tbody><tr><td><code>synchronized</code> / <code>ReentrantLock</code></td><td>pessimistic locking</td><td><strong>slowest</strong> under heavy contention</td></tr><tr><td><code>AtomicInteger</code> / <code>AtomicLong</code></td><td>CAS, non-blocking</td><td>fast; <strong>downside:</strong> under heavy load threads spin in a loop, burning CPU</td></tr><tr><td><strong><code>LongAdder</code></strong> (Java 8+)</td><td>an <strong>array of cells</strong> — different threads write to different cells, summed on demand</td><td><strong>the default choice with very many writers</strong></td></tr></tbody></table></div>\n<h2>The Java Memory Model and <code>happens-before</code></h2>\n<p><strong><code>happens-before</code></strong> is the guarantee that the results of operation A are visible to operation B.</p>\n<p>The core rules:</p>\n<ul><li>A write to a <code>volatile</code> variable <strong>happens-before</strong> a read of it.</li><li>Releasing a lock (<em>unlock</em>) <strong>happens-before</strong> acquiring it again (<em>lock</em>).</li><li><code>Thread.start()</code> <strong>happens-before</strong> every action in that thread.</li><li>Every action in a thread <strong>happens-before</strong> <code>join()</code> on it returns.</li></ul>\n<p>What <code>volatile</code> provides:</p>\n<ul><li>✅ <strong>visibility</strong> — bypasses the CPU cache,</li><li>✅ <strong>ordering</strong> — prevents instruction reordering by the compiler and CPU,</li><li>❌ <strong>atomicity</strong>.</li></ul>\n<p>More on the JMM and JIT optimisations → <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN\">JIT, the Java Memory Model, monitoring and observability</a>.</p>\n<h2>Coordination tools — <code>java.util.concurrent</code></h2>\n<p><code>synchronized</code> is not the whole story. These four classes show up in senior interviews:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Tool</th><th>Behaviour</th><th>Scenario</th></tr></thead><tbody><tr><td><code>CountDownLatch</code></td><td>waits until a counter hits zero; <strong>single use</strong></td><td>&quot;wait for 5 independent services (cache, DB, MQ) to start before launching the main server&quot;</td></tr><tr><td><code>CyclicBarrier</code></td><td>waits until N threads reach a rendezvous point; <strong>reusable</strong></td><td>&quot;map-reduce: 4 threads compute partial results, wait for each other, merge, and move to the next round&quot;</td></tr><tr><td><code>Semaphore</code></td><td>caps the <strong>number</strong> of threads accessing a resource</td><td>&quot;rate limiting — the external API allows 10 concurrent connections, set the semaphore to 10&quot;</td></tr><tr><td><code>Phaser</code></td><td>a more flexible barrier with a <strong>dynamic</strong> participant count</td><td>asked less often, but worth knowing as the &quot;modern barrier&quot;</td></tr></tbody></table></div>\n<h2>Fork/Join and work stealing</h2>\n<ul><li><strong>The problem with a classic pool:</strong> when one thread finishes while another still has 100 tasks, the first sits idle.</li><li><strong>The fix:</strong> in a <code>ForkJoinPool</code> <strong>every thread has its own queue</strong> (<code>Deque</code>). When it empties, it <strong>steals a task from the tail</strong> of a busy thread's queue.</li></ul>\n<p><strong>The senior question: why can <code>parallelStream()</code> be dangerous?</strong> Because by default it uses <code>ForkJoinPool.commonPool()</code>, which is <strong>shared by the whole JVM</strong>. Block its threads (on I/O, say) and you stall <strong>every</strong> parallel stream in the application.</p>\n<h2>Thread lifecycle and <code>Object</code> methods</h2>\n<h3><code>wait()</code> versus <code>sleep()</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>sleep()</code></th><th><code>wait()</code></th></tr></thead><tbody><tr><td>Class</td><td><code>Thread</code></td><td><strong><code>Object</code></strong></td></tr><tr><td>Lock</td><td><strong>keeps</strong> it</td><td><strong>releases</strong> the monitor</td></tr><tr><td>Requires</td><td>nothing</td><td>must be inside a <code>synchronized</code> block</td></tr><tr><td>Wake-up</td><td>after the timeout</td><td>via <code>notify()</code> / <code>notifyAll()</code> / timeout</td></tr></tbody></table></div>\n<h3>Why <code>wait()</code> in a <code>while</code>, not an <code>if</code>?</h3>\n<p>Because of <strong>spurious wakeups</strong> — the operating system may wake a thread for no reason. After waking you <strong>must re-check</strong> that the condition actually holds.</p>\n<pre><code class=\"language-java\">synchronized (lock) {\n    while (!condition) {   // NOT 'if'\n        lock.wait();\n    }\n    // process\n}</code></pre>\n<h3><code>join()</code> and <code>InterruptedException</code></h3>\n<p><code>Thread.join()</code> lets one thread wait for another to finish. It throws <code>InterruptedException</code>.</p>\n<blockquote><p><strong>Senior rule: never swallow <code>InterruptedException</code>.</strong> Either rethrow it, or restore the flag:</p><pre><code class=\"language-java\">catch (InterruptedException e) {\n    Thread.currentThread().interrupt();   // upper layers must know\n    throw new IllegalStateException(e);\n}</code></pre></blockquote>\n<h2>Interview questions</h2>\n<p><strong>Q: What is a livelock and how does it differ from a deadlock?</strong> <strong>A:</strong> In a <strong>deadlock</strong> threads are stuck — state <code>BLOCKED</code>. In a <strong>livelock</strong> they are active (<code>RUNNABLE</code>), continually changing state in reaction to each other while nothing progresses. <strong>Analogy:</strong> two people in a narrow corridor trying to pass — both step left, then both step right, forever. It often arises from a badly implemented deadlock-recovery mechanism.</p>\n<p><strong>Q: Can you start a thread twice?</strong> <strong>A:</strong> No. Calling <code>start()</code> on a thread that has already started, or finished, throws <code>IllegalThreadStateException</code>.</p>\n<p><strong>Q: User thread versus daemon thread?</strong> <strong>A:</strong> The JVM lives as long as <strong>at least one User thread</strong> is running. <strong>Daemon</strong> threads (the GC, for instance) are killed automatically once all User threads finish. Mark a background helper that should not block shutdown as a daemon.</p>\n<p><strong>Q: What is a ThreadLocal memory leak?</strong> <strong>A:</strong> Thread pools (in Tomcat, say) <strong>reuse</strong> threads. If you store a large object in a <code>ThreadLocal</code> and never call <code>remove()</code> at the end of the request, the object stays <strong>pinned to the thread</strong> and the GC cannot reclaim it, even though the request is over. Across thousands of requests this is a real leak. → <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a></p>\n<p><strong>Q: When <code>LongAdder</code> instead of <code>AtomicLong</code>?</strong> <strong>A:</strong> When you have <strong>very many writers</strong>. Under contention <code>AtomicLong</code> wastes CPU spinning in the CAS loop; <code>LongAdder</code> spreads writes across an array of cells and sums only on demand.</p>\n<p><strong>Q: How does <code>Runnable</code> differ from <code>Callable</code>?</strong> <strong>A:</strong> <code>Runnable.run()</code> returns nothing and cannot throw a checked exception. <code>Callable.call()</code> <strong>returns a value</strong> and <strong>may throw</strong>; submitted to an <code>ExecutorService</code> it yields a <code>Future</code> from which you collect the result or the exception wrapped in <code>ExecutionException</code>.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong><code>volatile</code> on a counter</strong> — the classic false comfort. It gives no atomicity.</li><li><strong><code>wait()</code> inside an <code>if</code></strong> instead of a <code>while</code> — a spurious wakeup lets code run with the condition unmet.</li><li><strong>Blocking I/O inside <code>parallelStream()</code></strong> — poisons the common ForkJoin pool for the whole JVM.</li><li><strong><code>ThreadLocal</code> without <code>remove()</code></strong> in a thread pool — a memory leak.</li><li><strong>A swallowed <code>InterruptedException</code></strong> — the thread cannot be stopped and application shutdown hangs.</li><li><strong>Acquiring locks in a different order</strong> in two methods — the shortest path to a deadlock. Establish a global lock ordering.</li><li><strong><code>synchronized</code> on an <code>Integer</code>/<code>String</code></strong> — those objects are cached and shared, so you are locking something entirely different from what you think.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN\">JIT, the Java Memory Model, monitoring and observability</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_EN\">Collections Framework — cheatsheet</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN\">Java 8 — lambdas, functional interfaces, streams</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_PL\">Wielowątkowość — wątki, executory, zakleszczenia</a></p>"},"Java/Concurrency/Multithreading_Executors_Deadlocks_PL":{"title":"Wielowątkowość — wątki, executory, zakleszczenia","category":"Java/Concurrency","date":"2026-11-04","tags":["java","concurrency","threads","executors","jmm","volatile","deadlock","interview"],"minutes":7,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li><code>synchronized</code> daje <strong>atomowość + widoczność</strong>. <code>volatile</code> daje <strong>tylko widoczność</strong>.</li><li><code>volatile int count; count++</code> <strong>nadal jest błędne</strong> — potrzebujesz <code>AtomicInteger</code> albo <code>synchronized</code>.</li><li><code>sleep()</code> <strong>trzyma blokadę</strong>, <code>wait()</code> <strong>ją zwalnia</strong>. <code>wait()</code> zawsze w pętli <code>while</code>, nigdy w <code>if</code>.</li><li><code>parallelStream()</code> korzysta ze <strong>wspólnej</strong> puli ForkJoin — blokada I/O w jednym miejscu zatrzyma równoległe strumienie w <strong>całej</strong> aplikacji.</li><li><strong>Deadlock</strong> = wątki stoją (<code>BLOCKED</code>). <strong>Livelock</strong> = wątki działają (<code>RUNNABLE</code>), ale nic nie postępuje.</li><li><strong>Nigdy nie połykaj <code>InterruptedException</code>.</strong></li></ul></blockquote>\n<h2><code>synchronized</code> — kontrola dostępu</h2>\n<p>Gwarantuje, że w danym momencie <strong>tylko jeden wątek</strong> wykonuje dany fragment kodu.</p>\n<p><strong>Analogia:</strong> toaleta w pociągu. Toaleta to zasób współdzielony, ludzie w korytarzu to wątki, <code>synchronized</code> to zamek w drzwiach. Wątek A wchodzi i zamyka (zakłada blokadę). Wątek B czeka. A wychodzi i otwiera (zwalnia blokadę). Dopiero teraz B może wejść.</p>\n<pre><code class=\"language-java\">public class Licznik {\n    private int count = 0;\n\n    // tylko jeden wątek naraz\n    public synchronized void inkrementuj() {\n        count++;\n    }\n}</code></pre>\n<p>Bez <code>synchronized</code> dwa wątki robiące <code>count++</code> jednocześnie mogą się nawzajem nadpisać — zamiast 2 dostaniesz 1. <code>count++</code> to w rzeczywistości <strong>trzy</strong> operacje: odczyt, inkrementacja, zapis.</p>\n<h2><code>volatile</code> — widoczność</h2>\n<p>Gwarantuje, że zmiana wartości zmiennej będzie <strong>natychmiast widoczna</strong> dla innych wątków.</p>\n<p><strong>Analogia:</strong> pamięć główna (RAM) to wielka tablica ogłoszeń na korytarzu; cache procesora to prywatny notatnik przy biurku każdego pracownika.</p>\n<ul><li><strong>Bez <code>volatile</code>:</strong> Pracownik A zmienia status na „ZAKOŃCZONY&quot;, ale zapisuje to tylko w swoim notatniku. Pracownik B patrzy na tablicę i wciąż widzi „W TRAKCIE&quot; — działa na nieaktualnych danych.</li><li><strong>Z <code>volatile</code>:</strong> A ma zakaz pisania w notatniku. Każda zmiana trafia od razu na tablicę.</li></ul>\n<pre><code class=\"language-java\">public class Pracownik extends Thread {\n    private volatile boolean running = true;   // zmiana widoczna natychmiast\n\n    public void run() {\n        while (running) { /* pracuj */ }\n    }\n\n    public void stopWork() {\n        running = false;   // zapis prosto do pamięci głównej\n    }\n}</code></pre>\n<h3>Kluczowa różnica — pytanie rekrutacyjne</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>synchronized</code></th><th><code>volatile</code></th></tr></thead><tbody><tr><td>Atomowość</td><td>✅</td><td>❌</td></tr><tr><td>Widoczność</td><td>✅</td><td>✅</td></tr><tr><td>Kolejność (reordering)</td><td>✅</td><td>✅</td></tr><tr><td>Koszt</td><td><strong>ciężki</strong></td><td><strong>lekki</strong></td></tr></tbody></table></div>\n<blockquote><p><strong>Czy <code>volatile</code> naprawi <code>i++</code>?</strong> <strong>Nie.</strong> <code>volatile</code> sprawia, że wątki widzą aktualny stan, ale nie zabrania im modyfikować go w tym samym czasie. Do licznika potrzebujesz <code>synchronized</code> albo <code>AtomicInteger</code>.</p></blockquote>\n<h2><code>synchronized</code> kontra <code>AtomicInteger</code></h2>\n<blockquote><p><code>synchronized</code> to mechanizm <strong>blokujący (pesymistyczny)</strong>, który <strong>usypia wątki</strong>, wymuszając kosztowne <strong>przełączanie kontekstu</strong> (<em>context switch</em>). <code>AtomicInteger</code> jest <strong>nieblokujący</strong> i opiera się na sprzętowej instrukcji procesora <strong>CAS</strong> (<em>Compare-And-Swap</em>) — znacznie szybszy, bo wątki nie są usypiane, tylko ponawiają próbę w pętli. <strong>Różnica w zakresie:</strong> atomiki zabezpieczają <strong>pojedynczą zmienną</strong>, <code>synchronized</code> pozwala atomowo wykonać <strong>cały blok</strong> operujący na wielu zmiennych.</p></blockquote>\n<h3>Ewolucja liczników — wydajność</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Mechanizm</th><th>Jak działa</th><th>Kiedy</th></tr></thead><tbody><tr><td><code>synchronized</code> / <code>ReentrantLock</code></td><td>blokowanie pesymistyczne</td><td><strong>najwolniejsze</strong> przy dużej konkurencji (<em>contention</em>)</td></tr><tr><td><code>AtomicInteger</code> / <code>AtomicLong</code></td><td>CAS, nieblokujące</td><td>szybkie; <strong>wada:</strong> przy dużym obciążeniu wątki kręcą się w pętli (<em>spin</em>), paląc CPU</td></tr><tr><td><strong><code>LongAdder</code></strong> (Java 8+)</td><td><strong>tablica komórek</strong> — różne wątki piszą do różnych komórek, wynik sumowany na żądanie</td><td><strong>domyślny wybór przy bardzo wielu wątkach piszących</strong></td></tr></tbody></table></div>\n<h2>Java Memory Model i <code>happens-before</code></h2>\n<p><strong><code>happens-before</code></strong> to gwarancja, że wyniki operacji A są widoczne dla operacji B.</p>\n<p>Podstawowe reguły:</p>\n<ul><li>Zapis do zmiennej <code>volatile</code> <strong>happens-before</strong> jej odczyt.</li><li>Zwolnienie blokady (<em>unlock</em>) <strong>happens-before</strong> jej ponowne zajęcie (<em>lock</em>).</li><li><code>Thread.start()</code> <strong>happens-before</strong> każda akcja w tym wątku.</li><li>Każda akcja w wątku <strong>happens-before</strong> powrót z <code>join()</code> na tym wątku.</li></ul>\n<p>Co daje <code>volatile</code>:</p>\n<ul><li>✅ <strong>widoczność</strong> — omija cache CPU,</li><li>✅ <strong>kolejność</strong> — zapobiega przestawianiu instrukcji przez kompilator i procesor,</li><li>❌ <strong>atomowość</strong>.</li></ul>\n<p>Szczegóły o JMM i optymalizacjach JIT → <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL\">JIT, Java Memory Model, monitoring i observability</a>.</p>\n<h2>Narzędzia koordynacji — <code>java.util.concurrent</code></h2>\n<p><code>synchronized</code> to nie wszystko. Te cztery klasy pojawiają się na rozmowach na seniora:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Narzędzie</th><th>Działanie</th><th>Scenariusz</th></tr></thead><tbody><tr><td><code>CountDownLatch</code></td><td>czeka, aż licznik zejdzie do zera; <strong>jednorazowy</strong></td><td>„czekamy na start 5 niezależnych serwisów (cache, DB, MQ), zanim uruchomimy główny serwer&quot;</td></tr><tr><td><code>CyclicBarrier</code></td><td>czeka, aż N wątków dotrze do punktu zbornego; <strong>wielorazowy</strong></td><td>„map-reduce: 4 wątki liczą wyniki częściowe, czekają na siebie, scalają i ruszają do kolejnej rundy&quot;</td></tr><tr><td><code>Semaphore</code></td><td>ogranicza <strong>liczbę</strong> wątków z dostępem do zasobu</td><td>„rate limiting — zewnętrzne API pozwala na 10 jednoczesnych połączeń, ustawiamy semafor na 10&quot;</td></tr><tr><td><code>Phaser</code></td><td>elastyczniejsza bariera z <strong>dynamiczną</strong> liczbą uczestników</td><td>rzadziej pytany, ale warto znać jako „nowoczesną barierę&quot;</td></tr></tbody></table></div>\n<h2>Fork/Join i <em>work stealing</em></h2>\n<ul><li><strong>Problem klasycznej puli:</strong> gdy jeden wątek skończy zadanie, a inny ma ich jeszcze 100, pierwszy bezczynnie czeka.</li><li><strong>Rozwiązanie:</strong> w <code>ForkJoinPool</code> <strong>każdy wątek ma własną kolejkę</strong> (<code>Deque</code>). Gdy ją opróżni, <strong>kradnie zadanie z końca kolejki</strong> innego, zapracowanego wątku.</li></ul>\n<p><strong>Pytanie na seniora: dlaczego <code>parallelStream()</code> bywa niebezpieczny?</strong> Bo domyślnie korzysta z <code>ForkJoinPool.commonPool()</code>, <strong>współdzielonej przez całą JVM</strong>. Jeśli zablokujesz w niej wątki (np. na I/O), zatrzymasz <strong>wszystkie</strong> równoległe strumienie w aplikacji.</p>\n<h2>Cykl życia wątku i metody <code>Object</code></h2>\n<h3><code>wait()</code> kontra <code>sleep()</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>sleep()</code></th><th><code>wait()</code></th></tr></thead><tbody><tr><td>Klasa</td><td><code>Thread</code></td><td><strong><code>Object</code></strong></td></tr><tr><td>Blokada</td><td><strong>trzyma</strong> ją</td><td><strong>zwalnia</strong> monitor</td></tr><tr><td>Wymaga</td><td>nic</td><td>musi być w bloku <code>synchronized</code></td></tr><tr><td>Wybudzenie</td><td>po czasie</td><td>przez <code>notify()</code> / <code>notifyAll()</code> / timeout</td></tr></tbody></table></div>\n<h3>Dlaczego <code>wait()</code> w pętli <code>while</code>, a nie <code>if</code>?</h3>\n<p>Przez <strong>fałszywe wybudzenia</strong> (<em>spurious wakeups</em>) — system operacyjny może wybudzić wątek bez powodu. Po obudzeniu <strong>musisz sprawdzić ponownie</strong>, czy warunek faktycznie jest spełniony.</p>\n<pre><code class=\"language-java\">synchronized (lock) {\n    while (!condition) {   // NIE 'if'\n        lock.wait();\n    }\n    // przetwarzaj\n}</code></pre>\n<h3><code>join()</code> i <code>InterruptedException</code></h3>\n<p><code>Thread.join()</code> pozwala jednemu wątkowi poczekać na zakończenie innego. Rzuca <code>InterruptedException</code>.</p>\n<blockquote><p><strong>Zasada seniora: nigdy nie połykaj <code>InterruptedException</code>.</strong> Albo rzuć go dalej, albo przywróć flagę:</p><pre><code class=\"language-java\">catch (InterruptedException e) {\n    Thread.currentThread().interrupt();   // wyższe warstwy muszą wiedzieć\n    throw new IllegalStateException(e);\n}</code></pre></blockquote>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Co to livelock i czym różni się od deadlocka?</strong> <strong>O:</strong> W <strong>deadlocku</strong> wątki stoją — stan <code>BLOCKED</code>. W <strong>livelocku</strong> są aktywne (<code>RUNNABLE</code>), ale w kółko zmieniają stan w reakcji na siebie i nic nie postępuje. <strong>Analogia:</strong> dwie osoby w wąskim korytarzu próbują się minąć — obie robią krok w lewo, potem obie w prawo, w nieskończoność. Często powstaje przy źle zaimplementowanym mechanizmie wychodzenia z deadlocka.</p>\n<p><strong>P: Czy można wystartować wątek dwa razy?</strong> <strong>O:</strong> Nie. <code>start()</code> na wątku, który już ruszył lub zakończył pracę, rzuci <code>IllegalThreadStateException</code>.</p>\n<p><strong>P: User thread kontra daemon thread?</strong> <strong>O:</strong> JVM żyje tak długo, jak długo działa <strong>przynajmniej jeden wątek typu User</strong>. Wątki <strong>Daemon</strong> (np. GC) są automatycznie zabijane, gdy wszystkie User się skończą. Wątek pomocniczy w tle, który nie powinien blokować zamknięcia aplikacji, oznacz jako daemon.</p>\n<p><strong>P: Co to ThreadLocal memory leak?</strong> <strong>O:</strong> Pule wątków (np. w Tomcacie) <strong>reużywają</strong> wątków. Jeśli zapiszesz duży obiekt w <code>ThreadLocal</code> i nie wywołasz <code>remove()</code> na końcu requestu, obiekt zostaje <strong>przypięty do wątku</strong> i GC go nie usunie, mimo że request się zakończył. Przy tysiącach requestów to realny wyciek pamięci. → <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a></p>\n<p><strong>P: Kiedy <code>LongAdder</code> zamiast <code>AtomicLong</code>?</strong> <strong>O:</strong> Gdy masz <strong>bardzo wielu piszących</strong>. <code>AtomicLong</code> przy dużej konkurencji marnuje CPU na spin w pętli CAS; <code>LongAdder</code> rozprasza zapisy po tablicy komórek i sumuje dopiero na żądanie.</p>\n<p><strong>P: Czym <code>Runnable</code> różni się od <code>Callable</code>?</strong> <strong>O:</strong> <code>Runnable.run()</code> nie zwraca wyniku i nie może rzucić checked exception. <code>Callable.call()</code> <strong>zwraca wartość</strong> i <strong>może rzucić wyjątek</strong>; przekazany do <code>ExecutorService</code> daje <code>Future</code>, z którego odbierasz wynik lub wyjątek opakowany w <code>ExecutionException</code>.</p>\n<h2>Pułapki</h2>\n<ul><li><strong><code>volatile</code> na liczniku</strong> — klasyczny fałszywy komfort. Nie daje atomowości.</li><li><strong><code>wait()</code> w <code>if</code></strong> zamiast <code>while</code> — fałszywe wybudzenie przepuści kod z niespełnionym warunkiem.</li><li><strong>Blokujące I/O w <code>parallelStream()</code></strong> — zatruwa wspólną pulę ForkJoin dla całej JVM.</li><li><strong><code>ThreadLocal</code> bez <code>remove()</code></strong> w puli wątków — wyciek pamięci.</li><li><strong>Połknięty <code>InterruptedException</code></strong> — wątek nie da się zatrzymać, a shutdown aplikacji się zawiesi.</li><li><strong>Różna kolejność zakładania blokad</strong> w dwóch metodach — najprostsza droga do deadlocka. Ustal globalny porządek blokad.</li><li><strong><code>synchronized</code> na <code>Integer</code>/<code>String</code></strong> — obiekty są cache'owane i współdzielone, więc blokujesz coś zupełnie innego, niż myślisz.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL\">JIT, Java Memory Model, monitoring i observability</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_PL\">Collections Framework — ściągawka</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL\">Java 8 — lambdy, interfejsy funkcyjne, strumienie</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_EN\">Multithreading — threads, executors, deadlocks</a></p>"},"Java/Fundamentals/value and reference":{"title":"value and reference","category":"Java/Fundamentals","date":"","tags":[],"minutes":6,"lead":"W Javie wszystkie parametry są zawsze przekazywane <strong>przez wartość</strong>. To jest fundamentalna zasada języka, która często prowadzi do nieporozumień, zwłaszcza gdy mówimy o obiektach.","html":"<p>Wyjaśnijmy to dokładnie:</p>\n<h3>1. Przekazywanie przez wartość (dla typów prymitywnych)</h3>\n<p>Gdy przekazujesz do metody zmienną typu prymitywnego (takiego jak <code>int</code>, <code>long</code>, <code>double</code>, <code>boolean</code>, <code>char</code> itp.), do metody przekazywana jest <strong>kopia wartości</strong> tej zmiennej.</p>\n<p><strong>Przykład:</strong></p>\n<p>Java</p>\n<pre><code>public class PrimitiveExample {\n    public static void modifyNumber(int num) {\n        num = num + 10; // Zmiana kopii wartości\n        System.out.println(&quot;Wewnątrz metody: num = &quot; + num);\n    }\n\n    public static void main(String[] args) {\n        int myNumber = 5;\n        System.out.println(&quot;Przed wywołaniem metody: myNumber = &quot; + myNumber); // myNumber = 5\n        modifyNumber(myNumber);\n        System.out.println(&quot;Po wywołaniu metody: myNumber = &quot; + myNumber);    // myNumber = 5 (nie zmienione!)\n    }\n}</code></pre>\n<p><strong>Wyjaśnienie:</strong></p>\n<ul><li><code>myNumber</code> ma wartość <code>5</code>.</li><li>Gdy <code>modifyNumber(myNumber)</code> jest wywoływane, tworzona jest <strong>kopia wartości</strong> <code>5</code> i przypisywana do parametru <code>num</code> wewnątrz metody.</li><li>Wewnątrz metody <code>num</code> zostaje zmienione na <code>15</code>.</li><li>Po powrocie z metody, oryginalna zmienna <code>myNumber</code> w <code>main</code> nadal ma wartość <code>5</code>, ponieważ operacja dotyczyła tylko kopii.</li></ul>\n<h3>2. Przekazywanie przez wartość (dla typów obiektowych - czyli &quot;przekazywanie kopii referencji&quot;)</h3>\n<p>To jest punkt, który często jest mylony z &quot;przekazywaniem przez referencję&quot;. W Javie, gdy przekazujesz do metody zmienną typu obiektowego (dowolny obiekt, np. <code>String</code>, <code>Integer</code>, <code>List</code>, Twoja własna klasa <code>User</code>), do metody przekazywana jest <strong>kopia referencji (adresu pamięci) do tego obiektu</strong>, a nie kopia samego obiektu.</p>\n<p><strong>Przykład 1: Modyfikacja obiektu, na który wskazuje referencja</strong></p>\n<p>Java</p>\n<pre><code>class MyObject {\n    String value;\n    public MyObject(String value) { this.value = value; }\n    public void setValue(String value) { this.value = value; }\n    public String getValue() { return value; }\n}\n\npublic class ObjectExample1 {\n    public static void modifyObject(MyObject obj) {\n        obj.setValue(&quot;Nowa wartość&quot;); // Zmiana stanu OBIEKTU, na który wskazuje referencja\n        System.out.println(&quot;Wewnątrz metody: obj.value = &quot; + obj.getValue());\n    }\n\n    public static void main(String[] args) {\n        MyObject instance = new MyObject(&quot;Stara wartość&quot;);\n        System.out.println(&quot;Przed wywołaniem metody: instance.value = &quot; + instance.getValue()); // Stara wartość\n        modifyObject(instance);\n        System.out.println(&quot;Po wywołaniu metody: instance.value = &quot; + instance.getValue());    // Nowa wartość (zmienione!)\n    }\n}</code></pre>\n<p><strong>Wyjaśnienie:</strong></p>\n<ul><li><code>instance</code> w <code>main</code> zawiera referencję (adres) do obiektu <code>MyObject</code> w pamięci.</li><li>Gdy <code>modifyObject(instance)</code> jest wywoływane, tworzona jest <strong>kopia tej referencji</strong> i przypisywana do parametru <code>obj</code> wewnątrz metody.</li><li>Teraz zarówno <code>instance</code>, jak i <code>obj</code> <strong>wskazują na TEN SAM OBIEKT</strong> w pamięci.</li><li>Kiedy <code>obj.setValue(&quot;Nowa wartość&quot;)</code> jest wywoływane, zmienia to stan <strong>oryginalnego obiektu</strong>, na który obie referencje wskazują.</li><li>Po powrocie z metody, <code>instance.value</code> w <code>main</code> odzwierciedla tę zmianę, ponieważ obie referencje prowadziły do tego samego zmodyfikowanego obiektu.</li></ul>\n<p><strong>Przykład 2: Przypisanie nowej referencji (bez wpływu na oryginalną)</strong></p>\n<p>To jest przykład, który najlepiej pokazuje, dlaczego to nadal jest &quot;przekazywanie przez wartość&quot;.</p>\n<p>Java</p>\n<pre><code>public class ObjectExample2 {\n    public static void reassignObject(MyObject obj) {\n        obj = new MyObject(&quot;Całkiem nowa wartość w metodzie&quot;); // Przypisanie NOWEJ referencji do LOKALNEGO parametru 'obj'\n        System.out.println(&quot;Wewnątrz metody: obj.value = &quot; + obj.getValue());\n    }\n\n    public static void main(String[] args) {\n        MyObject instance = new MyObject(&quot;Oryginalna wartość&quot;);\n        System.out.println(&quot;Przed wywołaniem metody: instance.value = &quot; + instance.getValue()); // Oryginalna wartość\n        reassignObject(instance);\n        System.out.println(&quot;Po wywołaniu metody: instance.value = &quot; + instance.getValue());    // Oryginalna wartość (nie zmienione!)\n    }\n}</code></pre>\n<p><strong>Wyjaśnienie:</strong></p>\n<ul><li><code>instance</code> w <code>main</code> wskazuje na obiekt A.</li><li>Gdy <code>reassignObject(instance)</code> jest wywoływane, tworzona jest <strong>kopia referencji do obiektu A</strong> i przypisywana do parametru <code>obj</code>.</li><li>Wewnątrz metody, linia <code>obj = new MyObject(&quot;...&quot;)</code> <strong>tworzy NOWY obiekt B</strong> i przypisuje jego referencję do <strong>lokalnej zmiennej <code>obj</code></strong>. Parametr <code>obj</code> teraz wskazuje na obiekt B, podczas gdy oryginalna zmienna <code>instance</code> w <code>main</code> nadal wskazuje na obiekt A.</li><li>Zmiana referencji lokalnego parametru <code>obj</code> nie ma wpływu na oryginalną referencję <code>instance</code> w metodzie <code>main</code>.</li></ul>\n<h3>Podsumowanie: Java ZAWSZE przekazuje przez wartość</h3>\n<ul><li><strong>Dla typów prymitywnych:</strong> Przekazuje kopię samej wartości.</li><li><strong>Dla typów obiektowych:</strong> Przekazuje kopię referencji (adresu w pamięci) do obiektu. Oznacza to, że jeśli zmienisz <strong>stan</strong> obiektu, na który referencja wskazuje, zmiana będzie widoczna na zewnątrz metody, ponieważ zarówno oryginalna, jak i skopiowana referencja wskazują na ten sam obiekt. Jeśli jednak spróbujesz <strong>przypisać nową referencję</strong> do parametru wewnątrz metody, oryginalna referencja pozostanie niezmieniona.</li></ul>\n<p>To rozróżnienie jest kluczowe dla zrozumienia, jak zachowują się zmienne w Javie podczas przekazywania do metod.</p>\n<p><strong>Oto najprostszy przykład,</strong> który wyraźnie pokazuje, że przypisanie nowej referencji do parametru wewnątrz metody <strong>nie zmienia oryginalnej referencji</strong> poza metodą.</p>\n<p>Skupimy się na prostym obiekcie typu <code>String</code> (który jest obiektem w Javie, choć immutable, ale to nie przeszkadza w pokazaniu zachowania referencji).</p>\n<p>Java</p>\n<pre><code>public class ReassignReferenceExample {\n\n    public static void changeReferenceInsideMethod(String text) {\n        System.out.println(&quot;Wewnątrz metody (przed zmianą): &quot; + text); // Wyświetli &quot;Oryginalny tekst&quot;\n        text = &quot;Nowy tekst w metodzie&quot;; // Tutaj przypisujemy NOWĄ referencję do parametru 'text'\n        System.out.println(&quot;Wewnątrz metody (po zmianie): &quot; + text);  // Wyświetli &quot;Nowy tekst w metodzie&quot;\n    }\n\n    public static void main(String[] args) {\n        String myString = &quot;Oryginalny tekst&quot;; // myString to referencja do obiektu &quot;Oryginalny tekst&quot;\n\n        System.out.println(&quot;Przed wywołaniem metody: &quot; + myString); // Wyświetli &quot;Oryginalny tekst&quot;\n\n        changeReferenceInsideMethod(myString); // Przekazujemy KOPIĘ referencji myString\n\n        System.out.println(&quot;Po wywołaniu metody: &quot; + myString);  // Nadal wyświetli &quot;Oryginalny tekst&quot;\n    }\n}</code></pre>\n<p><strong>Wyjaśnienie krok po kroku:</strong></p>\n<ol><li><strong><code>String myString = &quot;Oryginalny tekst&quot;;</code></strong><ul><li>W metodzie <code>main</code> tworzymy obiekt <code>String</code> o wartości <code>&quot;Oryginalny tekst&quot;</code>.</li><li>Zmienna <code>myString</code> przechowuje <strong>referencję</strong> (adres w pamięci) do tego obiektu.</li></ul></li><li><strong><code>changeReferenceInsideMethod(myString);</code></strong><ul><li>Wywołujemy metodę <code>changeReferenceInsideMethod</code>.</li><li>Java <strong>kopiuje wartość referencji</strong> z <code>myString</code> i przypisuje ją do <strong>lokalnego parametru <code>text</code></strong> w metodzie <code>changeReferenceInsideMethod</code>.</li><li>Teraz zarówno <code>myString</code> w <code>main</code>, jak i <code>text</code> w <code>changeReferenceInsideMethod</code> <strong>wskazują na TEN SAM obiekt</strong> w pamięci (<code>&quot;Oryginalny tekst&quot;</code>).</li></ul></li><li><strong><code>text = &quot;Nowy tekst w metodzie&quot;;</code> (wewnątrz <code>changeReferenceInsideMethod</code>)</strong><ul><li>Ta linia tworzy <strong>NOWY obiekt String</strong> o wartości <code>&quot;Nowy tekst w metodzie&quot;</code> w pamięci.</li><li><strong>Lokalny parametr <code>text</code></strong> zostaje <strong>przypisany na nowo</strong> i teraz wskazuje na TEN NOWY obiekt.</li><li><strong>Ważne:</strong> Oryginalna zmienna <code>myString</code> w <code>main</code> <strong>nadal wskazuje na stary obiekt</strong> (<code>&quot;Oryginalny tekst&quot;</code>). Zmiana dotknęła tylko kopię referencji, którą dostała metoda.</li></ul></li><li><strong><code>System.out.println(&quot;Po wywołaniu metody: &quot; + myString);</code> (w <code>main</code>)</strong><ul><li>Tutaj wciąż odwołujemy się do <code>myString</code>. Ponieważ jego referencja nigdy nie została zmieniona (tylko jej kopia w innej metodzie), <code>myString</code> nadal wskazuje na pierwotny obiekt.</li><li>Dlatego na ekranie zobaczymy <code>&quot;Oryginalny tekst&quot;</code>, co dowodzi, że przypisanie nowej referencji do parametru <code>text</code> wewnątrz metody nie wpłynęło na <code>myString</code> w metodzie wywołującej.</li></ul></li></ol>"},"Java/heap/Heap problems during float division":{"title":"Heap problems during float division","category":"Java/heap","date":"","tags":[],"minutes":2,"lead":"No, <strong>Infinity by itself will not directly cause a java.lang.OutOfMemoryError: Java heap space</strong>.","html":"<p>However, <strong>indirectly</strong>, it <strong>can</strong> contribute to memory issues <strong>if misused</strong>, particularly in cases like:</p>\n<hr>\n<h3><strong>❌ When</strong></h3>\n<h3><strong>Infinity</strong></h3>\n<h3><strong>can contribute</strong></h3>\n<h3><strong>to heap space issues:</strong></h3>\n<h4><strong>1.</strong></h4>\n<h4><strong>Used in a loop or data generator</strong></h4>\n<p>If Infinity causes a loop to run uncontrolled or to generate a huge data structure (e.g., creating a massive array, list, or writing to a growing file), it may fill up the heap.</p>\n<pre><code>float x = 1.0f;\nfloat y = 0.0f;\nfloat result = x / y; // Infinity\n\nList&lt;String&gt; list = new ArrayList&lt;&gt;();\nwhile (result &gt; 0) {\n    list.add(&quot;data&quot;); // grows endlessly, result stays Infinity\n}</code></pre>\n<h4><strong>2.</strong></h4>\n<h4><strong>Used as index or size</strong></h4>\n<p>Trying to use Infinity as an array size or collection initial capacity (which is cast to an int) can cause unexpected behavior:</p>\n<pre><code>int size = (int)(1.0f / 0.0f); // results in Integer.MAX_VALUE\nList&lt;Object&gt; list = new ArrayList&lt;&gt;(size); // could trigger OOM</code></pre>\n<h4><strong>3.</strong></h4>\n<h4><strong>Used in serialization, logging, or metrics</strong></h4>\n<p>If you accidentally log or store a ton of values that are Infinity (e.g., from metrics, performance logs, etc.), that data accumulation can bloat memory.</p>\n<hr>\n<h3><strong>✅ Key Points:</strong></h3>\n<ul><li>Infinity is a <strong>valid float/double value</strong> in Java and doesn’t use much memory itself.</li><li>The <strong>real problem</strong> is usually <strong>how you handle</strong> Infinity — especially if it leads to <strong>unbounded resource allocation</strong> (loops, collections, etc.).</li></ul>\n<hr>\n<p>Would you like help with diagnosing a memory issue in a specific scenario or code snippet?</p>"},"Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN":{"title":"JIT, the Java Memory Model, monitoring and observability","category":"Java/JVM_Internals","date":"2026-11-04","tags":["java","jvm","jit","jmm","observability","prometheus","grafana","micrometer","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>The JIT makes Java a <strong>hybrid</strong>: fast startup from the interpreter, C++-class throughput once hot paths are compiled.</li><li><strong>Inlining is the single most important JIT optimisation</strong> — it removes call overhead and unlocks further optimisations.</li><li><strong>Deoptimisation</strong> is Java's advantage over static compilers: the JVM can undo a speculation once the assumption stops holding.</li><li><strong>Metrics are data; observability is a property of the system.</strong> Metrics answer &quot;is it working&quot;; observability answers &quot;why isn't it&quot;.</li><li>The distinction that wins interviews: <strong>cardinality</strong>.</li></ul></blockquote>\n<hr>\n<h2>1. JIT — the just-in-time compiler</h2>\n<h3>What it is</h3>\n<p>A HotSpot JVM mechanism that converts bytecode into machine code <strong>at runtime</strong>, targeted at the actual CPU. It is why Java — despite starting interpreted — reaches throughput close to C++.</p>\n<h3>Code lifecycle</h3>\n<pre><code>1. INTERPRETATION       the JVM reads bytecode instruction by instruction\n   ├─ upside:   fast startup, no waiting for compilation\n   └─ downside: slow execution over a long run\n            │\n            ▼\n2. PROFILING            the JVM counts method invocations and loop iterations,\n                        looking for hot spots\n            │\n            ▼\n3. COMPILATION          past a threshold (on the order of 10 000 calls)\n                        the JIT compiles the method to assembly and optimises\n            │\n            ▼\n4. CODE CACHE           compiled native code goes into a dedicated memory area;\n                        subsequent calls bypass the interpreter</code></pre>\n<h3>Key optimisations</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Optimisation</th><th>What it does</th><th>Why it matters</th></tr></thead><tbody><tr><td><strong>Inlining</strong></td><td>pastes the body of a small method <code>B()</code> directly into <code>A()</code> instead of performing a jump</td><td><strong>the most important optimisation in Java</strong> — it removes call overhead and, more importantly, lets the JIT optimise the merged code as one unit</td></tr><tr><td><strong>Dead code elimination</strong></td><td>removes code that can never run (<code>if (false) {...}</code>)</td><td>the machine code carries no dead branches</td></tr><tr><td><strong>Loop unrolling</strong></td><td>unrolls loops, reducing condition checks</td><td>fewer jumps, better branch prediction</td></tr></tbody></table></div>\n<h3>Tiered compilation</h3>\n<p>A modern JVM runs <strong>two compilers at once</strong>:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Compiler</th><th>Compile speed</th><th>Code quality</th><th>Role</th></tr></thead><tbody><tr><td><strong>C1</strong> (client)</td><td>very fast</td><td>simple optimisations</td><td>quick speed-up right after startup</td></tr><tr><td><strong>C2</strong> (server)</td><td>slow</td><td>aggressive, deep optimisations</td><td>maximum throughput for genuinely hot methods</td></tr></tbody></table></div>\n<p>This is exactly what combines <strong>fast startup</strong> with <strong>peak long-run throughput</strong>.</p>\n<h3>Deoptimisation — the safety net</h3>\n<p>The JIT is <strong>speculative</strong>. It may assume <em>&quot;this method never receives <code>null</code>&quot;</em> and compile without the check.</p>\n<p>When the assumption breaks, <strong>deoptimisation</strong> happens: the JVM discards the fast native code, falls back to the interpreter, and recompiles — this time accounting for the new conditions.</p>\n<blockquote><p><strong>This is the edge over a static compiler.</strong> C++ cannot revisit a decision made at build time. The JIT optimises for the <strong>traffic the application actually sees</strong>, not for compile-time assumptions.</p></blockquote>\n<h3>Summary for a recruiter</h3>\n<blockquote><p><em>&quot;The JIT is a hybrid mechanism. The application starts interpreted so it boots fast, while the JVM profiles the code in the background looking for hot spots. Once a method crosses the invocation threshold it is compiled to native code with inlining and dead-code elimination. Tiered compilation — C1 first, then C2 — combines fast startup with maximum throughput. And because the JIT runs at runtime, it can optimise better than a static compiler, reacting to real traffic.&quot;</em></p></blockquote>\n<hr>\n<h2>2. The Java Memory Model — what it actually is</h2>\n<p><strong>The JMM is not a map of memory regions.</strong> It is the set of rules governing <strong>when a write by one thread becomes visible to another</strong>, and in what order operations may be observed.</p>\n<p>Confusing the JMM with memory areas (heap, stack, metaspace) is the most common mistake in this part of an interview. Memory areas are covered in <a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_EN\">JVM architecture, JRE and class loaders</a>; visibility and <code>happens-before</code> in <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_EN\">Multithreading — threads, executors, deadlocks</a>.</p>\n<hr>\n<h2>3. Observability — the three pillars</h2>\n<p>The modern framing is not &quot;monitoring&quot; but <strong>observability</strong>, resting on three pillars: <strong>metrics, logs, traces</strong>.</p>\n<h3>The standard stack (open source / cloud native)</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Tool</th><th>Role</th><th>Nuance worth knowing</th></tr></thead><tbody><tr><td><strong>Prometheus</strong></td><td>time-series database, metrics</td><td>operates on a <strong>PULL</strong> model — it scrapes your services every few seconds from <code>/actuator/prometheus</code></td></tr><tr><td><strong>AlertManager</strong></td><td>notifications</td><td>a Prometheus component; fires when e.g. error rate &gt; 5 %</td></tr><tr><td><strong>Grafana</strong></td><td>visualisation</td><td><em>single pane of glass</em> — one dashboard combining Prometheus metrics with logs from Loki/Elasticsearch</td></tr><tr><td><strong>Micrometer</strong></td><td>Java abstraction layer</td><td>&quot;SLF4J for metrics&quot;: you write <code>Timer.record()</code> and Micrometer translates it for Prometheus, Datadog or Dynatrace — <strong>switching monitoring systems is a configuration change, not a code change</strong></td></tr></tbody></table></div>\n<blockquote><p><strong>Trap:</strong> without <code>spring-boot-starter-actuator</code>, Micrometer <strong>exposes no endpoints</strong>. Metrics are collected and nobody can see them.</p></blockquote>\n<h3>Distributed tracing</h3>\n<p>Metrics tell you <em>it is slow</em>. Logs tell you <em>something blew up</em>. Only tracing tells you <strong>where those 5 seconds went</strong>.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Concept</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Trace ID</strong></td><td>identifier of the whole request, carried across every service</td></tr><tr><td><strong>Span ID</strong></td><td>identifier of a single operation inside one service</td></tr></tbody></table></div>\n<p>Tools: Zipkin, Jaeger, OpenTelemetry. The output is a Gantt chart for a single request — <code>Service A (10 ms) → Service B (4900 ms) → DB</code>. The culprit is immediately visible.</p>\n<h3>Enterprise-class APM</h3>\n<p>AppDynamics, Dynatrace and New Relic work through <strong>bytecode instrumentation</strong> — you attach an agent to the process (<code>-javaagent:agent.jar</code>) and it sees everything <strong>without a line of code changing</strong>.</p>\n<p>What you get: automatic topology discovery, visibility down to the individual SQL statement, ML-based anomaly detection.</p>\n<hr>\n<h2>4. Metrics versus observability — the senior-level distinction</h2>\n<p>Many candidates use the terms interchangeably. That is a mistake.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Metrics (monitoring)</th><th>Observability</th></tr></thead><tbody><tr><td><strong>Answers</strong></td><td>&quot;Is the system up?&quot;, &quot;What is happening?&quot;</td><td><strong>&quot;WHY is this happening?&quot;</strong></td></tr><tr><td><strong>Nature of data</strong></td><td>aggregated numbers</td><td>metrics + logs + traces together</td></tr><tr><td><strong>Scope</strong></td><td><em>known unknowns</em> — you monitor what you anticipated</td><td><em>unknown unknowns</em> — failures nobody planned for</td></tr><tr><td><strong>Storage cost</strong></td><td>low</td><td>higher</td></tr></tbody></table></div>\n<blockquote><p><strong>The equation for a recruiter:</strong> metrics are a <strong>subset</strong> of observability. With metrics alone you do not have observability, because you lack context.</p></blockquote>\n<h3>Cardinality — the argument that wins interviews</h3>\n<p><strong>Metrics cannot handle high cardinality.</strong> You cannot tag <code>response_time</code> with a user id — at a million users Prometheus explodes in time-series count. So metrics only ever say <em>&quot;the average is 200 ms&quot;</em>.</p>\n<p><strong>Genuine observability tools permit high cardinality</strong> — you can ask for the requests of one specific user. That lets you debug <strong>individual</strong> problems, not just systemic ones.</p>\n<h3>The narrative to tell</h3>\n<p><strong>Metrics-led:</strong> an alert wakes me at 03:00. Grafana shows <code>http_errors_total</code> jumped to 15 %. I know there is a problem; I do not know what it is. I start guessing: the database? the new deploy?</p>\n<p><strong>Observability-led:</strong> the alert arrives and I can slice the data. Filtering shows a correlation — 100 % of errors come from one endpoint and affect users with a particular product category in the basket. Traces show a <code>NullPointerException</code> in the inventory service for that category. <strong>I know why in 30 seconds, without guessing.</strong></p>\n<hr>\n<h2>5. Kibana (ELK) versus Splunk</h2>\n<p>Not the same thing, but direct competitors. For a senior, two differences matter: <strong>architecture</strong> and <strong>when the schema is applied</strong>.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Property</th><th>Kibana (ELK)</th><th>Splunk</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>a UI for Elasticsearch, nothing more</td><td>a complete end-to-end platform</td></tr><tr><td><strong>Assembly</strong></td><td>you assemble the pieces: Elasticsearch + Logstash/Beats + Kibana</td><td><em>enterprise ready out of the box</em></td></tr><tr><td><strong>Schema</strong></td><td><strong>schema on write</strong> — parse before indexing</td><td><strong>schema on read</strong> — ingest raw, apply structure at query time</td></tr><tr><td><strong>Query language</strong></td><td>KQL / Lucene — <code>status:500 AND env:prod</code></td><td>SPL — `index=main \\</td></tr><tr><td><strong>Cost model</strong></td><td>infrastructure plus engineering time</td><td>licensed per GB/day or vCPU — <strong>one of the most expensive tools on the market</strong></td></tr><tr><td><strong>Strength</strong></td><td>dashboards, cloud-native observability</td><td>ad-hoc investigation, SIEM, banking</td></tr></tbody></table></div>\n<h3>Consequences of the schema choice</h3>\n<p><strong>Schema on write (Elasticsearch):</strong> fast search, because the data is already structured. But if the log format changes in the application and the parser does not, <strong>you lose data or cannot find it</strong>. Changing a field definition requires reindexing.</p>\n<p><strong>Schema on read (Splunk):</strong> enormous flexibility — you can analyse data whose structure you did not know in advance, which is ideal for investigating unfamiliar ground. The price is CPU load, because parsing happens on <strong>every</strong> query.</p>\n<blockquote><p>SPL lets you program in the search bar — join transactions, compute time deltas, correlate in a single query. Here Splunk clearly outclasses Kibana.</p></blockquote>\n<hr>\n<h2>Interview questions</h2>\n<p><strong>Q: Is Java interpreted or compiled?</strong> <strong>A:</strong> Both. It starts interpreted for fast startup, and hot methods are JIT-compiled to native code. Tiered compilation combines the two — C1 fast, C2 aggressive.</p>\n<p><strong>Q: What is the most important JIT optimisation?</strong> <strong>A:</strong> Inlining. It removes method-call overhead, but more importantly it lets the JIT optimise the merged code as a single unit.</p>\n<p><strong>Q: What happens when a JIT speculation turns out to be wrong?</strong> <strong>A:</strong> Deoptimisation — fall back to the interpreter and recompile under the new assumptions. A static compiler cannot do this.</p>\n<p><strong>Q: How do metrics differ from observability?</strong> <strong>A:</strong> Metrics are data, observability is a property of the system. Metrics cover known unknowns and are low-cardinality; observability combines metrics, logs and traces, tolerates high cardinality, and lets you diagnose cases nobody anticipated.</p>\n<p><strong>Q: Why not tag a metric with a user id?</strong> <strong>A:</strong> Cardinality explosion. Every distinct label value is a separate time series — at a million users the metrics store stops working.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong>A microbenchmark without warm-up measures the interpreter, not the JIT.</strong> The first few thousand iterations are unrepresentative — hence JMH and its warm-up phase.</li><li><strong>The code cache is finite.</strong> Once full, the JIT stops compiling and throughput drops — silently.</li><li><strong>The JMM is not memory areas.</strong> It is the inter-thread visibility rule set.</li><li><strong>No actuator means no metrics</strong>, however correctly Micrometer is configured.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_EN\">JVM architecture, JRE and class loaders</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_EN\">Multithreading — threads, executors, deadlocks</a> · <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL\">JIT, Java Memory Model, monitoring i observability</a></p>"},"Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL":{"title":"JIT, Java Memory Model, monitoring i observability","category":"Java/JVM_Internals","date":"2026-11-04","tags":["java","jvm","jit","jmm","observability","prometheus","grafana","micrometer","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>JIT czyni Javę <strong>hybrydą</strong>: szybki start z interpretera, wydajność C++ po skompilowaniu gorących ścieżek.</li><li><strong>Inlining to najważniejsza optymalizacja JIT-a</strong> — likwiduje narzut wywołania metody i odblokowuje kolejne optymalizacje.</li><li><strong>Deoptymalizacja</strong> to przewaga Javy nad kompilatorami statycznymi: JVM może cofnąć spekulację, gdy założenie przestało być prawdziwe.</li><li><strong>Metryki to dane, observability to cecha systemu.</strong> Metryki odpowiadają „czy działa&quot;, observability — „dlaczego nie&quot;.</li><li>Rozróżnienie, które wygrywa rozmowy: <strong>kardynalność</strong>.</li></ul></blockquote>\n<hr>\n<h2>1. JIT — Just-In-Time Compiler</h2>\n<h3>Czym jest</h3>\n<p>Mechanizm HotSpot JVM, który <strong>w czasie działania</strong> zamienia bytecode na kod maszynowy dopasowany do konkretnego procesora. Dzięki niemu Java — mimo startu w trybie interpretowanym — osiąga wydajność zbliżoną do C++.</p>\n<h3>Cykl życia kodu</h3>\n<pre><code>1. INTERPRETACJA        JVM czyta bytecode instrukcja po instrukcji\n   ├─ zaleta: szybki start, bez czekania na kompilację\n   └─ wada:   wolne wykonanie przy długiej pracy\n            │\n            ▼\n2. PROFILOWANIE         JVM zlicza wywołania metod i iteracje pętli,\n                        szukając HotSpotów\n            │\n            ▼\n3. KOMPILACJA           po przekroczeniu progu (rzędu 10 000 wywołań)\n                        JIT kompiluje metodę do asemblera i optymalizuje\n            │\n            ▼\n4. CODE CACHE           skompilowany kod trafia do osobnego obszaru pamięci;\n                        kolejne wywołania omijają interpreter</code></pre>\n<h3>Kluczowe optymalizacje</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Optymalizacja</th><th>Co robi</th><th>Dlaczego to ma znaczenie</th></tr></thead><tbody><tr><td><strong>Inlining</strong></td><td>wkleja ciało małej metody <code>B()</code> bezpośrednio w ciało <code>A()</code> zamiast wykonywać skok</td><td><strong>najważniejsza optymalizacja w Javie</strong> — usuwa narzut wywołania i otwiera drogę kolejnym optymalizacjom na połączonym kodzie</td></tr><tr><td><strong>Dead code elimination</strong></td><td>usuwa kod, który nigdy się nie wykona (<code>if (false) {...}</code>)</td><td>kod maszynowy nie zawiera martwych gałęzi</td></tr><tr><td><strong>Loop unrolling</strong></td><td>rozwija pętlę, zmniejszając liczbę sprawdzeń warunku</td><td>mniej skoków, lepsza predykcja rozgałęzień</td></tr></tbody></table></div>\n<h3>Tiered compilation</h3>\n<p>Nowoczesna JVM używa <strong>dwóch kompilatorów jednocześnie</strong>:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Kompilator</th><th>Szybkość kompilacji</th><th>Jakość kodu</th><th>Rola</th></tr></thead><tbody><tr><td><strong>C1</strong> (client)</td><td>bardzo szybka</td><td>proste optymalizacje</td><td>szybkie przyspieszenie zaraz po starcie</td></tr><tr><td><strong>C2</strong> (server)</td><td>wolna</td><td>agresywne, głębokie optymalizacje</td><td>maksymalna wydajność dla „bardzo gorących&quot; metod</td></tr></tbody></table></div>\n<p>To właśnie łączy <strong>szybki start</strong> z <strong>maksymalną przepustowością</strong> w długim działaniu.</p>\n<h3>Deoptymalizacja — siatka bezpieczeństwa</h3>\n<p>JIT jest <strong>spekulatywny</strong>. Zakłada na przykład: <em>„ta metoda nigdy nie dostanie <code>null</code>&quot;</em> — i kompiluje kod bez sprawdzenia.</p>\n<p>Gdy założenie pęknie, następuje <strong>deoptymalizacja</strong>: JVM porzuca szybki kod natywny, wraca do interpretera, a potem kompiluje ponownie — tym razem uwzględniając nowe warunki.</p>\n<blockquote><p><strong>To przewaga nad kompilatorem statycznym.</strong> C++ nie potrafi cofnąć decyzji podjętej przy budowaniu. JIT optymalizuje pod <strong>faktyczny ruch w aplikacji</strong>, a nie pod założenia z czasu kompilacji.</p></blockquote>\n<h3>Podsumowanie dla rekrutera</h3>\n<blockquote><p><em>„JIT to mechanizm hybrydowy. Aplikacja startuje interpretowana, żeby szybko wstać, a JVM w tle profiluje kod, szukając HotSpotów. Po przekroczeniu progu wywołań metoda jest kompilowana do kodu natywnego z inliningiem i eliminacją martwego kodu. Tiered compilation — najpierw C1, potem C2 — łączy szybki start z maksymalną przepustowością. A ponieważ JIT działa w runtime, może optymalizować lepiej niż kompilator statyczny, bo reaguje na realny ruch.&quot;</em></p></blockquote>\n<hr>\n<h2>2. Java Memory Model — co to właściwie jest</h2>\n<p><strong>JMM to nie mapa regionów pamięci.</strong> To zbiór reguł określających, <strong>kiedy zapis wykonany przez jeden wątek staje się widoczny dla innego</strong> i w jakiej kolejności operacje mogą być postrzegane.</p>\n<p>Mylenie JMM z obszarami pamięci (heap, stack, metaspace) to najczęstszy błąd w tej części rozmowy. Obszary pamięci opisuje <a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_PL\">Architektura JVM, JRE i class loadery</a>; reguły widoczności i <code>happens-before</code> — <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_PL\">Wielowątkowość — wątki, executory, zakleszczenia</a>.</p>\n<hr>\n<h2>3. Observability — trzy filary</h2>\n<p>W nowoczesnym świecie nie mówi się już o „monitoringu&quot;, tylko o <strong>observability</strong>, która stoi na trzech filarach: <strong>metryki, logi, tracing</strong>.</p>\n<h3>Stack standardowy (open source / cloud native)</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Narzędzie</th><th>Rola</th><th>Niuans warty znania</th></tr></thead><tbody><tr><td><strong>Prometheus</strong></td><td>baza szeregów czasowych, metryki</td><td>działa w modelu <strong>PULL</strong> — sam odpytuje serwisy co kilkanaście sekund, pobierając dane z <code>/actuator/prometheus</code></td></tr><tr><td><strong>AlertManager</strong></td><td>powiadomienia</td><td>komponent Prometheusa; wysyła alert, gdy np. error rate &gt; 5 %</td></tr><tr><td><strong>Grafana</strong></td><td>wizualizacja</td><td><em>single pane of glass</em> — jeden dashboard z metrykami z Prometheusa i logami z Loki/Elasticsearcha</td></tr><tr><td><strong>Micrometer</strong></td><td>warstwa abstrakcji w Javie</td><td>„SLF4J dla metryk&quot;: piszesz <code>Timer.record()</code>, a Micrometer tłumaczy to na format Prometheusa, Datadoga czy Dynatrace'a — <strong>zmiana systemu monitoringu to zmiana konfiguracji, nie kodu</strong></td></tr></tbody></table></div>\n<blockquote><p><strong>Pułapka:</strong> bez <code>spring-boot-starter-actuator</code> Micrometer <strong>nie wystawi endpointów</strong>. Metryki są zbierane, ale nikt ich nie widzi.</p></blockquote>\n<h3>Distributed tracing</h3>\n<p>Metryki mówią, że <em>jest wolno</em>. Logi mówią, że <em>coś wybuchło</em>. Dopiero tracing mówi: <strong>gdzie dokładnie zniknęło te 5 sekund</strong>.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Pojęcie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><strong>Trace ID</strong></td><td>identyfikator całego żądania, przechodzący przez wszystkie serwisy</td></tr><tr><td><strong>Span ID</strong></td><td>identyfikator pojedynczej operacji w jednym serwisie</td></tr></tbody></table></div>\n<p>Narzędzia: Zipkin, Jaeger, OpenTelemetry. Efekt: wykres Gantta dla jednego żądania — <code>Serwis A (10 ms) → Serwis B (4900 ms) → DB</code>. Winowajca widoczny od razu.</p>\n<h3>APM klasy enterprise</h3>\n<p>AppDynamics, Dynatrace, New Relic działają na zasadzie <strong>instrumentacji bytecode'u</strong> — wpinasz agenta do procesu (<code>-javaagent:agent.jar</code>) i widzi wszystko <strong>bez zmiany linijki kodu</strong>.</p>\n<p>Co dają: automatyczne wykrywanie topologii połączeń, wgląd aż do poziomu konkretnego zapytania SQL, wykrywanie anomalii oparte na ML.</p>\n<hr>\n<h2>4. Metryki kontra observability — rozróżnienie na poziomie seniora</h2>\n<p>Wielu kandydatów używa tych słów wymiennie. To błąd.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Metryki (monitoring)</th><th>Observability</th></tr></thead><tbody><tr><td><strong>Odpowiadają na</strong></td><td>„Czy system działa?&quot;, „Co się dzieje?&quot;</td><td><strong>„DLACZEGO to się dzieje?&quot;</strong></td></tr><tr><td><strong>Natura danych</strong></td><td>zagregowane liczby</td><td>metryki + logi + ślady razem</td></tr><tr><td><strong>Zakres</strong></td><td><em>known unknowns</em> — monitorujesz to, co przewidziałeś</td><td><em>unknown unknowns</em> — problemy, których nikt nie zaplanował</td></tr><tr><td><strong>Koszt przechowywania</strong></td><td>niski</td><td>wyższy</td></tr></tbody></table></div>\n<blockquote><p><strong>Równanie dla rekrutera:</strong> metryki są <strong>podzbiorem</strong> observability. Mając same metryki, nie masz pełnej obserwowalności, bo brakuje kontekstu.</p></blockquote>\n<h3>Kardynalność — argument, który wygrywa rozmowy</h3>\n<p><strong>Metryki nie radzą sobie z wysoką kardynalnością.</strong> Nie da się otagować <code>response_time</code> identyfikatorem użytkownika — przy milionie użytkowników Prometheus eksploduje liczbą szeregów czasowych. Dlatego metryki mówią tylko ogólnie: <em>„średni czas to 200 ms&quot;</em>.</p>\n<p><strong>Narzędzia observability z prawdziwego zdarzenia dopuszczają wysoką kardynalność</strong> — możesz zapytać o żądania konkretnego użytkownika. To pozwala debugować problemy <strong>jednostkowe</strong>, a nie tylko systemowe.</p>\n<h3>Narracja na rozmowę</h3>\n<p><strong>Podejście metrykowe:</strong> alert budzi mnie o 3:00. Na Grafanie widzę, że <code>http_errors_total</code> skoczył do 15 %. Wiem, że jest problem — nie wiem jaki. Zaczynam zgadywać: baza? nowy deploy?</p>\n<p><strong>Podejście observability:</strong> dostaję alert i mogę pokroić dane. Filtruję i widzę korelację — 100 % błędów pochodzi z jednego endpointu i dotyczy użytkowników z konkretną kategorią produktu w koszyku. W śladach widzę <code>NullPointerException</code> w serwisie magazynowym dla tej kategorii. <strong>Wiem dlaczego w 30 sekund, bez zgadywania.</strong></p>\n<hr>\n<h2>5. Kibana (ELK) kontra Splunk</h2>\n<p>Nie są tożsame, ale są bezpośrednimi konkurentami. Dla seniora liczą się dwie różnice: <strong>architektura</strong> i <strong>moment nadania schematu</strong>.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Cecha</th><th>Kibana (ELK)</th><th>Splunk</th></tr></thead><tbody><tr><td><strong>Typ</strong></td><td>tylko interfejs graficzny dla Elasticsearcha</td><td>kompletna platforma end-to-end</td></tr><tr><td><strong>Składanie</strong></td><td>Ty składasz klocki: Elasticsearch + Logstash/Beats + Kibana</td><td><em>enterprise ready out of the box</em></td></tr><tr><td><strong>Schemat</strong></td><td><strong>Schema on Write</strong> — parsujesz przed zapisem</td><td><strong>Schema on Read</strong> — połykasz surowe dane, strukturę nadajesz w zapytaniu</td></tr><tr><td><strong>Język</strong></td><td>KQL / Lucene — <code>status:500 AND env:prod</code></td><td>SPL — `index=main \\</td></tr><tr><td><strong>Model kosztowy</strong></td><td>infrastruktura + praca inżynierów</td><td>licencja za GB dziennie lub vCPU — <strong>jedno z najdroższych narzędzi na rynku</strong></td></tr><tr><td><strong>Mocna strona</strong></td><td>dashboardy, observability cloud native</td><td>śledztwa ad-hoc, SIEM, bankowość</td></tr></tbody></table></div>\n<h3>Konsekwencje wyboru schematu</h3>\n<p><strong>Schema on Write (Elasticsearch):</strong> szybkie wyszukiwanie, bo dane są już poukładane. Ale jeśli format logów w aplikacji się zmieni, a parser nie — <strong>tracisz dane albo ich nie znajdziesz</strong>. Zmiana definicji pola wymaga reindeksacji.</p>\n<p><strong>Schema on Read (Splunk):</strong> ogromna elastyczność, można analizować dane o nieznanej wcześniej strukturze — idealne do śledztw w nieznanym terenie. Ceną jest obciążenie CPU, bo parsowanie dzieje się przy <strong>każdym</strong> zapytaniu.</p>\n<blockquote><p>SPL pozwala programować w pasku wyszukiwania — łączyć transakcje, liczyć delty czasu, robić korelacje w jednym zapytaniu. Tu Splunk wyraźnie wyprzedza Kibanę.</p></blockquote>\n<hr>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Czy Java jest interpretowana czy kompilowana?</strong> <strong>O:</strong> Jedno i drugie. Startuje interpretowana dla szybkiego uruchomienia, a gorące metody JIT kompiluje do kodu natywnego. Tiered compilation łączy oba tryby — C1 szybko, C2 agresywnie.</p>\n<p><strong>P: Jaka jest najważniejsza optymalizacja JIT-a?</strong> <strong>O:</strong> Inlining. Likwiduje narzut wywołania metody, ale ważniejsze jest to, że po wklejeniu ciała JIT może optymalizować połączony kod jako całość.</p>\n<p><strong>P: Co się dzieje, gdy spekulacja JIT-a okaże się błędna?</strong> <strong>O:</strong> Deoptymalizacja — powrót do interpretera i ponowna kompilacja z nowymi założeniami. Kompilator statyczny tego nie potrafi.</p>\n<p><strong>P: Czym różnią się metryki od observability?</strong> <strong>O:</strong> Metryki to dane, observability to cecha systemu. Metryki obsługują znane niewiadome i mają niską kardynalność; observability łączy metryki, logi i ślady, dopuszcza wysoką kardynalność i pozwala diagnozować przypadki, których nikt nie przewidział.</p>\n<p><strong>P: Dlaczego nie otagować metryki identyfikatorem użytkownika?</strong> <strong>O:</strong> Eksplozja kardynalności. Każda unikalna wartość etykiety to osobny szereg czasowy — przy milionie użytkowników baza metryk przestaje działać.</p>\n<h2>Pułapki</h2>\n<ul><li><strong>Mikrobenchmark bez rozgrzewki mierzy interpreter, nie JIT.</strong> Pierwsze tysiące iteracji nie są reprezentatywne — stąd JMH i jego faza warmup.</li><li><strong>Code Cache ma skończony rozmiar.</strong> Po jego zapełnieniu JIT przestaje kompilować i wydajność spada — po cichu.</li><li><strong>JMM to nie obszary pamięci.</strong> To reguły widoczności między wątkami.</li><li><strong>Brak actuatora = brak metryk</strong>, mimo poprawnie skonfigurowanego Micrometera.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_PL\">Architektura JVM, JRE i class loadery</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_PL\">Wielowątkowość — wątki, executory, zakleszczenia</a> · <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN\">JIT, the Java Memory Model, monitoring and observability</a></p>"},"Java/JVM_Internals/JVM_Architecture_And_Classloaders_EN":{"title":"JVM architecture, JRE and class loaders","category":"Java/JVM_Internals","date":"2026-11-04","tags":["java","jvm","jre","jdk","classloader","bytecode","interview"],"minutes":5,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>The JVM <strong>does not know the Java language</strong> — it knows only the <code>.class</code> file format. That is an architectural decision, not a detail.</li><li>The compiler does the heavy lifting <strong>once</strong>; the JVM receives clean, verified bytecode and starts fast.</li><li><code>JDK = JRE + developer tooling</code>, <code>JRE = JVM + standard libraries + supporting files</code>.</li><li>Bytecode is the reason Kotlin, Scala and Groovy run on the same machine.</li><li>Memory splits into <strong>shared</strong> (heap, metaspace) and <strong>per thread</strong> (stack, program counter).</li></ul></blockquote>\n<h2>Mental model</h2>\n<p>Five stages from source to execution:</p>\n<pre><code>  .java   ──[ compiler ]──►  .class (bytecode)\n                                  │\n                                  ▼\n                           [ class loader ]\n                    reads bytecode, converts it into the JVM's\n                    internal representation, loads it into the\n                    run-time data area\n                                  │\n                                  ▼\n                        [ run-time data area ]\n                    heap · stack · metaspace · PC · native stack\n                                  │\n                                  ▼\n                         [ execution engine ]\n                    reads from the run-time data area and executes</code></pre>\n<h2>Key concepts</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Concept</th><th>What it is</th><th>When it matters</th></tr></thead><tbody><tr><td><strong>JVM</strong></td><td>virtual machine executing bytecode; understands only the <code>.class</code> format</td><td>questions about portability and JVM languages</td></tr><tr><td><strong>JRE</strong></td><td>JVM + standard libraries (<code>java.util</code>, <code>java.io</code>) + configuration files</td><td>the <strong>runtime</strong> environment</td></tr><tr><td><strong>JDK</strong></td><td>JRE + compiler and tooling (<code>javac</code>, <code>jmap</code>, <code>jstat</code>)</td><td>the <strong>development</strong> environment</td></tr><tr><td><strong>Bytecode</strong></td><td>JVM instructions plus a symbol table inside a <code>.class</code> file</td><td>the unit of portability</td></tr><tr><td><strong>Class loader</strong></td><td>loads <code>.class</code> files into the run-time data area</td><td>dynamic loading, isolation, hot reload</td></tr></tbody></table></div>\n<h2>Why bytecode rather than source code</h2>\n<p>The most common question in this area. Three independent reasons:</p>\n<ol><li><strong>Parsing cost.</strong> Source code is optimised for human readability. If the JVM had to read it on every start, it would re-check syntax, resolve context and build structures every single time — startup would be dramatically slower. With bytecode that work happens <strong>once</strong>, in the compiler.</li><li><strong>Language independence.</strong> The JVM is &quot;Java&quot; by name but a <strong>generic stack machine</strong> by function. Because it understands only bytecode, any language with a compiler targeting <code>.class</code> runs on it — Kotlin, Scala, Groovy. <strong>The JVM has no idea the source was not Java.</strong></li><li><strong>Ahead-of-time optimisation.</strong> A compiler does more than translate: it strips dead code, folds constants, reorders logic. Doing that ahead of time is far cheaper than attempting it while the program is starting.</li></ol>\n<h2>Memory areas</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Area</th><th>What it holds</th><th>Scope</th></tr></thead><tbody><tr><td><strong>Heap</strong></td><td>objects and class instances</td><td><strong>shared</strong> across all threads</td></tr><tr><td><strong>Stack</strong></td><td>method frames, local variables, references</td><td><strong>per thread</strong></td></tr><tr><td><strong>Metaspace</strong></td><td>class metadata (replaced PermGen)</td><td>shared, native memory</td></tr><tr><td><strong>Program Counter</strong></td><td>address of the currently executing instruction</td><td>per thread</td></tr><tr><td><strong>Native Method Stack</strong></td><td>native (JNI) method execution</td><td>per thread</td></tr></tbody></table></div>\n<h3>Heap structure</h3>\n<pre><code>┌──────────── Young Generation ────────────┐   ┌─── Old Generation ───┐\n│    Eden       │  Survivor S0  │   S1     │   │  long-lived objects   │\n│  new objects  │  short-lived, shuffled   │   │  after many GC cycles │\n└───────────────┴───────────────────────────┘  └───────────────────────┘</code></pre>\n<h3>Heap versus stack — an analogy</h3>\n<p><strong>The heap is a shared construction site.</strong> All the finished furniture and materials (objects) sit on it. Every worker (thread) operates on the same site — if one places a chair there, another sees it immediately.</p>\n<p><strong>The stack is a personal toolbox</strong> each worker carries. Inside are the plans (local variables) and maps (references to furniture on the site). What is in one toolbox is invisible to everyone else, until it is used to manipulate material on the shared site.</p>\n<blockquote><p><strong>Where the analogy breaks:</strong> a reference in the toolbox is not a copy of the furniture. Two threads holding the same reference mutate <strong>the same</strong> object — which is where the entire need for synchronisation comes from.</p></blockquote>\n<h2>Garbage collection — outline</h2>\n<p>Full treatment: <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a>.</p>\n<p>Four phases:</p>\n<ol><li><strong>Identify live objects</strong> — those reachable from <em>GC roots</em>: thread stacks, static fields, other live objects.</li><li><strong>Mark</strong> — traverse the object graph from the roots and mark what is reachable.</li><li><strong>Sweep</strong> — reclaim memory held by unmarked (unreachable) objects.</li><li><strong>Compact</strong> — optionally relocate objects to reduce fragmentation.</li></ol>\n<p>Why it matters: it prevents memory leaks, uses a limited resource efficiently, and removes a whole class of C/C++ bugs — dangling pointers and double frees.</p>\n<h2>Diagnostics — the minimum to remember</h2>\n<pre><code class=\"language-bash\"># GC statistics every second for a process\njstat -gc &lt;pid&gt; 1000\n\n# heap summary\njcmd &lt;pid&gt; GC.heap_info\n\n# detailed heap configuration\njmap -heap &lt;pid&gt;</code></pre>\n<h2>Interview questions</h2>\n<p><strong>Q: Why doesn't the JVM execute source code directly?</strong> <strong>A:</strong> Source is optimised for humans, the JVM for machines. Parsing on every start would be expensive, and bytecode additionally buys language independence and ahead-of-time optimisation.</p>\n<p><strong>Q: What is the difference between JRE and JDK?</strong> <strong>A:</strong> The JRE runs programs (JVM + libraries + supporting files). The JDK builds them — it is the JRE plus the compiler and diagnostic tooling.</p>\n<p><strong>Q: Does the JVM know the code was written in Kotlin?</strong> <strong>A:</strong> No. It sees only standard bytecode in a <code>.class</code> file. That is precisely what makes it a polyglot platform.</p>\n<p><strong>Q: Why is the stack per thread while the heap is shared?</strong> <strong>A:</strong> A method frame describes the execution state of <strong>one</strong> thread and is meaningless outside it. An object must outlive the method call and is often shared — hence a common area, and hence the need for synchronisation.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong>&quot;Java is interpreted&quot; is a half-truth.</strong> Bytecode starts interpreted, but hot paths are compiled to native code by the JIT → <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN\">JIT, the Java Memory Model, monitoring and observability</a>.</li><li><strong>Metaspace is not the heap.</strong> It lives in native memory with its own limits — <code>OutOfMemoryError: Metaspace</code> is diagnosed differently from a heap error.</li><li><strong>Confusing the Java Memory Model with memory areas.</strong> The JMM is a set of visibility and ordering rules between threads, not a map of memory regions.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a> · <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN\">JIT, the Java Memory Model, monitoring and observability</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_EN\">Multithreading — threads, executors, deadlocks</a> · <a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_PL\">Architektura JVM, JRE i class loadery</a></p>"},"Java/JVM_Internals/JVM_Architecture_And_Classloaders_PL":{"title":"Architektura JVM, JRE i class loadery","category":"Java/JVM_Internals","date":"2026-11-04","tags":["java","jvm","jre","jdk","classloader","bytecode","interview"],"minutes":5,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>JVM <strong>nie zna języka Java</strong> — zna wyłącznie format pliku <code>.class</code>. To decyzja architektoniczna, nie szczegół.</li><li>Kompilator wykonuje ciężką pracę <strong>raz</strong>; JVM dostaje gotowy, zweryfikowany bytecode i startuje szybko.</li><li><code>JDK = JRE + narzędzia deweloperskie</code>, <code>JRE = JVM + biblioteki standardowe + pliki wsparcia</code>.</li><li>Bytecode to powód, dla którego Kotlin, Scala i Groovy działają na tej samej maszynie.</li><li>Pamięć dzieli się na <strong>współdzieloną</strong> (heap, metaspace) i <strong>per wątek</strong> (stack, program counter).</li></ul></blockquote>\n<h2>Model mentalny</h2>\n<p>Pięć etapów od kodu źródłowego do wykonania:</p>\n<pre><code>  .java   ──[ kompilator ]──►  .class (bytecode)\n                                   │\n                                   ▼\n                            [ class loader ]\n                     czyta bytecode, zamienia go na wewnętrzną\n                     reprezentację JVM i ładuje do run-time data area\n                                   │\n                                   ▼\n                         [ run-time data area ]\n                     heap · stack · metaspace · PC · native stack\n                                   │\n                                   ▼\n                          [ execution engine ]\n                      czyta dane z run-time data area i wykonuje</code></pre>\n<h2>Kluczowe pojęcia</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Pojęcie</th><th>Co to jest</th><th>Kiedy ma znaczenie</th></tr></thead><tbody><tr><td><strong>JVM</strong></td><td>maszyna wirtualna wykonująca bytecode; rozumie wyłącznie format <code>.class</code></td><td>przy pytaniach o przenośność i o języki JVM-owe</td></tr><tr><td><strong>JRE</strong></td><td>JVM + biblioteki standardowe (<code>java.util</code>, <code>java.io</code>) + pliki konfiguracyjne</td><td>środowisko <strong>uruchomieniowe</strong></td></tr><tr><td><strong>JDK</strong></td><td>JRE + kompilator i narzędzia (<code>javac</code>, <code>jmap</code>, <code>jstat</code>)</td><td>środowisko <strong>deweloperskie</strong></td></tr><tr><td><strong>Bytecode</strong></td><td>instrukcje JVM + tablica symboli w pliku <code>.class</code></td><td>jednostka przenośności</td></tr><tr><td><strong>Class loader</strong></td><td>ładuje <code>.class</code> do run-time data area</td><td>ładowanie dynamiczne, izolacja, hot reload</td></tr></tbody></table></div>\n<h2>Dlaczego bytecode, a nie kod źródłowy</h2>\n<p>To najczęstsze pytanie z tego obszaru. Trzy niezależne powody:</p>\n<ol><li><strong>Koszt parsowania.</strong> Kod źródłowy jest zoptymalizowany pod czytelność dla człowieka. Gdyby JVM miała go czytać przy każdym starcie, musiałaby za każdym razem sprawdzać składnię, rozumieć kontekst i budować strukturę — czas startu byłby dramatyczny. Przy bytecodzie ta praca jest wykonana <strong>raz</strong>, przez kompilator.</li><li><strong>Niezależność od języka.</strong> JVM jest z nazwy „javowa&quot;, a z funkcji to <strong>generyczna maszyna stosowa</strong>. Ponieważ rozumie tylko bytecode, każdy język z własnym kompilatorem do <code>.class</code> na niej działa — Kotlin, Scala, Groovy. <strong>JVM nie ma pojęcia, że źródło nie było w Javie.</strong></li><li><strong>Optymalizacja z wyprzedzeniem.</strong> Kompilator nie tylko tłumaczy — usuwa martwy kod, upraszcza stałe, reorganizuje logikę. Robienie tego <em>ahead of time</em> jest nieporównanie tańsze niż w locie, gdy program właśnie startuje.</li></ol>\n<h2>Obszary pamięci</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Obszar</th><th>Co przechowuje</th><th>Zasięg</th></tr></thead><tbody><tr><td><strong>Heap</strong> (sterta)</td><td>obiekty i instancje klas</td><td><strong>współdzielony</strong> przez wszystkie wątki</td></tr><tr><td><strong>Stack</strong> (stos)</td><td>ramki metod, zmienne lokalne, referencje</td><td><strong>per wątek</strong></td></tr><tr><td><strong>Metaspace</strong></td><td>metadane klas (zastąpił PermGen)</td><td>współdzielony, pamięć natywna</td></tr><tr><td><strong>Program Counter</strong></td><td>adres aktualnie wykonywanej instrukcji</td><td>per wątek</td></tr><tr><td><strong>Native Method Stack</strong></td><td>wykonanie metod natywnych (JNI)</td><td>per wątek</td></tr></tbody></table></div>\n<h3>Struktura sterty</h3>\n<pre><code>┌──────────── Young Generation ────────────┐   ┌─── Old Generation ───┐\n│   Eden        │   Survivor S0 │  S1      │   │  obiekty długowieczne │\n│ nowe obiekty  │  krótkożyjące, przerzucane│  │  po wielu cyklach GC  │\n└───────────────┴───────────────────────────┘  └───────────────────────┘</code></pre>\n<h3>Heap kontra stack — analogia</h3>\n<p><strong>Heap to wspólny plac budowy.</strong> Leżą na nim wszystkie gotowe meble i materiały (obiekty). Każdy robotnik (wątek) pracuje na tym samym placu — jeśli jeden postawi tam krzesło, drugi natychmiast je widzi.</p>\n<p><strong>Stack to indywidualna skrzynka narzędziowa</strong>, którą każdy robotnik nosi ze sobą. W środku są plany (zmienne lokalne) i mapki (referencje do mebli na placu). Zawartość jednej skrzynki jest niewidoczna dla pozostałych, dopóki nie zostanie użyta do manipulacji materiałem na wspólnym placu.</p>\n<blockquote><p><strong>Gdzie analogia się rozjeżdża:</strong> referencja w skrzynce nie jest kopią mebla. Dwa wątki trzymające tę samą referencję modyfikują <strong>ten sam</strong> obiekt — i stąd bierze się cała potrzeba synchronizacji.</p></blockquote>\n<h2>Garbage Collection — zarys</h2>\n<p>Pełne ujęcie: <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a>.</p>\n<p>Cztery fazy:</p>\n<ol><li><strong>Identyfikacja żywych obiektów</strong> — osiągalnych z <em>GC roots</em>: stosów wątków, pól statycznych, innych żywych obiektów.</li><li><strong>Mark</strong> — przejście grafu obiektów od korzeni i oznaczenie osiągalnych.</li><li><strong>Sweep</strong> — odzyskanie pamięci obiektów nieoznaczonych.</li><li><strong>Compact</strong> — opcjonalne przesunięcie obiektów, by zmniejszyć fragmentację.</li></ol>\n<p>Po co: zapobiega wyciekom pamięci, efektywnie gospodaruje ograniczonym zasobem i eliminuje klasę błędów znaną z C/C++ — wiszące wskaźniki i podwójne zwolnienie.</p>\n<h2>Diagnostyka — minimum do zapamiętania</h2>\n<pre><code class=\"language-bash\"># statystyki GC co sekundę dla procesu\njstat -gc &lt;pid&gt; 1000\n\n# podsumowanie sterty\njcmd &lt;pid&gt; GC.heap_info\n\n# szczegóły konfiguracji sterty\njmap -heap &lt;pid&gt;</code></pre>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Dlaczego JVM nie wykonuje kodu źródłowego bezpośrednio?</strong> <strong>O:</strong> Bo kod źródłowy jest zoptymalizowany pod człowieka, a JVM pod maszynę. Parsowanie przy każdym starcie byłoby kosztowne, a bytecode pozwala dodatkowo na niezależność językową i optymalizację ahead-of-time.</p>\n<p><strong>P: Czym różni się JRE od JDK?</strong> <strong>O:</strong> JRE uruchamia programy (JVM + biblioteki + pliki wsparcia). JDK je tworzy — to JRE plus kompilator i narzędzia diagnostyczne.</p>\n<p><strong>P: Czy JVM wie, że kod napisano w Kotlinie?</strong> <strong>O:</strong> Nie. Widzi wyłącznie standardowy bytecode w pliku <code>.class</code>. To właśnie czyni ją platformą wielojęzyczną.</p>\n<p><strong>P: Dlaczego stos jest per wątek, a sterta współdzielona?</strong> <strong>O:</strong> Ramka metody opisuje stan wykonania <strong>jednego</strong> wątku i nie ma sensu poza nim. Obiekt natomiast musi przeżyć wywołanie metody i bywa dzielony — stąd wspólna przestrzeń i konieczność synchronizacji.</p>\n<h2>Pułapki</h2>\n<ul><li><strong>„Java jest interpretowana&quot; to półprawda.</strong> Bytecode startuje interpretowany, ale gorące ścieżki kompiluje JIT do kodu maszynowego → <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL\">JIT, Java Memory Model, monitoring i observability</a>.</li><li><strong>Metaspace to nie sterta.</strong> Leży w pamięci natywnej i ma własne limity — <code>OutOfMemoryError: Metaspace</code> diagnozuje się inaczej niż błąd sterty.</li><li><strong>Mylenie Java Memory Model z obszarami pamięci.</strong> JMM to reguły widoczności i uporządkowania między wątkami, a nie mapa regionów pamięci.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a> · <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL\">JIT, Java Memory Model, monitoring i observability</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_PL\">Wielowątkowość — wątki, executory, zakleszczenia</a> · <a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_EN\">JVM architecture, JRE and class loaders</a></p>"},"Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN":{"title":"Memory management and garbage collection","category":"Java/JVM_Internals","date":"2026-11-04","tags":["java","jvm","gc","memory","heap","oom","tuning","interview"],"minutes":10,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>GC works on <strong>reachability from GC roots</strong>, not reference counting. Unreachable means garbage, no matter how many references point at it.</li><li><strong>Most objects die young</strong> — the entire generational design rests on that assumption.</li><li>Two survivor spaces exist so that memory is <strong>compacted on every minor GC</strong>, avoiding fragmentation.</li><li><strong>A memory leak in Java is not a GC bug</strong> — it is an object that is still reachable when it should not be.</li><li><code>OutOfMemoryError</code> has <strong>several distinct variants</strong>, each diagnosed differently.</li></ul></blockquote>\n<h2>Why this exists at all</h2>\n<p>In C/C++ the developer manages memory — hence dangling pointers and double frees. The JVM automates allocation and reclamation, removing a whole class of bugs. The price is <strong>pauses and CPU overhead</strong>. That is why GC tuning is real engineering work, not esoterica.</p>\n<h2>JVM process memory map</h2>\n<pre><code>Operating system memory\n  └── JVM process\n      ├── Heap            ← GC managed\n      ├── Stack           ← per thread\n      └── Native memory   ← straight from the OS\n          ├── Metaspace\n          ├── Code Cache\n          ├── Direct Buffers (NIO)\n          ├── thread native data\n          └── JNI libraries</code></pre>\n<p><strong>Practical consequence:</strong> <code>-Xmx</code> bounds <strong>only</strong> the heap. The JVM process can consume substantially more — the most common surprise when setting Kubernetes memory limits.</p>\n<h2>Heap structure and object lifecycle</h2>\n<pre><code>┌──────────────── Young Generation ────────────────┐  ┌─── Old Generation ───┐\n│    Eden     │  Survivor S0   │   Survivor S1     │  │  objects promoted    │\n│ new objects │ one in use, the other always empty │  │  past the tenuring   │\n│             │                                     │  │  threshold           │\n└─────────────┴─────────────────────────────────────┘  └──────────────────────┘</code></pre>\n<ol><li><code>new</code> allocates in <strong>Eden</strong> (bump-pointer strategy — allocation is very cheap).</li><li>Minor GC: survivors from Eden move into the empty survivor space (say S0).</li><li>Next cycle: survivors from Eden <strong>and</strong> S0 are copied into S1. Each survivor's age increments.</li><li>Past the <strong>tenuring threshold</strong>, the object is promoted to the old generation.</li></ol>\n<h3>Why two survivor spaces rather than one</h3>\n<p>This question separates people who read about it from people who understand it.</p>\n<blockquote><p>At any moment <strong>one survivor space is always empty</strong>. Every minor GC copies objects into that empty space. Copying <strong>compacts memory as a side effect</strong> — no separate defragmentation algorithm is needed.</p></blockquote>\n<p>Benefits: fast allocation (bump-pointer in Eden), cheap minor GC (most objects are already dead), zero fragmentation in the young generation.</p>\n<h2>GC roots — the foundation of the whole mechanism</h2>\n<p>GC does not count references. GC performs <strong>reachability analysis</strong>: it starts at the roots and walks the object graph.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>GC root type</th><th>Why it is a root</th></tr></thead><tbody><tr><td>Active threads</td><td>essential to program execution</td></tr><tr><td>Local variables and parameters on the stack</td><td>the method is using them right now</td></tr><tr><td>Static fields of loaded classes</td><td>they live as long as the class</td></tr><tr><td>JNI references</td><td>the JVM assumes native code is using them</td></tr></tbody></table></div>\n<p>Anything reachable from a root is <strong>live</strong>. Everything else is <strong>garbage</strong>.</p>\n<blockquote><p><strong>The consequence interviewers ask about:</strong> a thousand objects referencing each other, with no path from any root, will be collected. Reference cycles are <strong>not</strong> a problem in Java — unlike under reference counting.</p></blockquote>\n<h2>GC phases</h2>\n<ol><li><strong>Identify live objects</strong> — reachable from GC roots.</li><li><strong>Mark</strong> — walk the graph, mark what is reachable.</li><li><strong>Sweep</strong> — reclaim memory of unmarked objects.</li><li><strong>Compact</strong> — optionally relocate objects to fight fragmentation.</li></ol>\n<h2>Stop-the-world</h2>\n<p><strong>What it is:</strong> the JVM suspends <strong>all</strong> application threads to perform work that needs a stable view of memory.</p>\n<p><strong>Why it is necessary:</strong> references change while the program runs. If a thread mutated references during analysis, GC would either collect a live object or retain a dead one. STW guarantees consistency.</p>\n<p><strong>When it happens:</strong> minor GC · major/full GC · metadata cleanup and class unloading · <strong>the initial mark phase even in concurrent collectors</strong> (G1, CMS).</p>\n<p><strong>Scale of the problem:</strong> on an 8 GB heap with millions of objects, a full GC can halt the application for hundreds of milliseconds. For a service handling thousands of requests per second, a 500 ms pause is user-visible.</p>\n<p><strong>How to reduce it:</strong> modern collectors doing most work concurrently (G1, ZGC, Shenandoah) · size the heap so full GCs stay rare · cut down on temporary object churn.</p>\n<h2>Minor GC versus major GC</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Minor GC</th><th>Major / full GC</th></tr></thead><tbody><tr><td><strong>Scope</strong></td><td>young generation</td><td>old generation, often the whole heap</td></tr><tr><td><strong>Trigger</strong></td><td>Eden is full</td><td>old gen near capacity, <code>System.gc()</code>, JVM operations</td></tr><tr><td><strong>Frequency</strong></td><td>frequent</td><td>rare</td></tr><tr><td><strong>Pause</strong></td><td>short (ms)</td><td>hundreds of ms to seconds</td></tr><tr><td><strong>Cost</strong></td><td>low</td><td>high — CPU and time</td></tr></tbody></table></div>\n<blockquote><p><code>System.gc()</code> is <strong>not a command</strong>, only a hint — and in production code it is an anti-pattern.</p></blockquote>\n<h2>Memory leaks</h2>\n<p><strong>Definition:</strong> an object is no longer needed but is <strong>still reachable</strong>, so GC cannot collect it. That is a bug in the code, not in the GC.</p>\n<h3>Common causes</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Cause</th><th>Mechanism</th></tr></thead><tbody><tr><td><strong>Static fields</strong></td><td>live as long as the application — a large object in <code>static</code> never goes away</td></tr><tr><td><strong>Unclosed resources</strong></td><td>streams, sockets, database connections</td></tr><tr><td><strong>Collections never pruned</strong></td><td>a <code>List</code>/<code>Map</code> growing without bound</td></tr><tr><td><strong>Listeners and callbacks</strong></td><td>registered, never deregistered</td></tr><tr><td><strong>Inner / anonymous classes</strong></td><td>implicit reference to the outer class</td></tr><tr><td><strong><code>ThreadLocal</code></strong></td><td>a pooled thread lives long and holds the value</td></tr></tbody></table></div>\n<h3>Example — the canonical leak</h3>\n<pre><code class=\"language-java\">public class MemoryLeakExample {\n    // static field: reachable for the entire application lifetime\n    private static final List&lt;byte[]&gt; leak = new ArrayList&lt;&gt;();\n\n    public static void main(String[] args) {\n        while (true) {\n            leak.add(new byte[1024 * 1024]); // 1 MB, never removed\n        }\n    }\n}</code></pre>\n<h3>How to detect</h3>\n<ol><li><strong>Watch usage over time</strong> — JVisualVM, JConsole, Java Flight Recorder. The signal: memory grows and <strong>does not drop after GC cycles</strong>.</li><li><strong>Enable GC logs</strong> — <code>-Xlog:gc*</code>. The signal: full GCs run often and memory does not come back.</li><li><strong>Take a heap dump</strong> and analyse it.</li><li><strong>Inspect retained heap and reference chains</strong> — why is the object still alive.</li></ol>\n<h3>How to fix</h3>\n<pre><code class=\"language-java\">// close resources — try-with-resources instead of finally\ntry (FileInputStream fis = new FileInputStream(&quot;file.txt&quot;)) {\n    // use the stream\n} catch (IOException e) {\n    log.error(&quot;failed to read file&quot;, e);\n}</code></pre>\n<ul><li>Restrict static fields to things that are <strong>genuinely</strong> global.</li><li>Remove entries from collections; for caches use <code>WeakHashMap</code> or a library with eviction.</li><li>Deregister listeners.</li><li><code>WeakReference</code> / <code>SoftReference</code> where a reference <strong>should not</strong> prevent collection.</li></ul>\n<h2>Heap dump</h2>\n<p><strong>What it is:</strong> a snapshot of every object on the heap at a point in time, with references and memory consumption. <code>.hprof</code> format.</p>\n<pre><code class=\"language-bash\"># manual, live objects only\njmap -dump:live,format=b,file=heap.hprof &lt;pid&gt;</code></pre>\n<pre><code># automatic on OOM — set this BEFORE the failure happens\n-XX:+HeapDumpOnOutOfMemoryError\n-XX:HeapDumpPath=/path/to/heapdump.hprof</code></pre>\n<p><strong>What to analyse</strong> (Eclipse MAT, VisualVM, JProfiler):</p>\n<div class=\"table-wrap\"><table><thead><tr><th>View</th><th>Answers the question</th></tr></thead><tbody><tr><td><strong>Dominator tree</strong></td><td>which object holds the largest subgraph of memory</td></tr><tr><td><strong>Histogram</strong></td><td>how many instances of each type and how much they occupy</td></tr><tr><td><strong>Reference chains</strong></td><td><em>why</em> this object is still alive — the path to a GC root</td></tr></tbody></table></div>\n<p><strong>A real example:</strong> a web application throws <code>OutOfMemoryError: Java heap space</code> after a few hours. The heap dump shows a <code>HashMap</code> retaining millions of entries where business logic implies a thousand. The map was never cleared between requests.</p>\n<h2><code>OutOfMemoryError</code> variants</h2>\n<p><strong>Each variant is a different diagnosis.</strong> Reading the message to the end saves hours.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Message</th><th>What was exhausted</th><th>First step</th></tr></thead><tbody><tr><td><code>Java heap space</code></td><td>heap</td><td>heap dump; look for a leak or an undersized <code>-Xmx</code></td></tr><tr><td><code>Metaspace</code></td><td>class metadata</td><td>check dynamic class generation, proxies, redeploys</td></tr><tr><td><code>Direct buffer memory</code></td><td>off-heap NIO buffers</td><td><code>-XX:MaxDirectMemorySize</code>, audit NIO code</td></tr><tr><td><code>unable to create new native thread</code></td><td>native memory / OS limit</td><td>too many threads, misconfigured pools</td></tr><tr><td><code>GC overhead limit exceeded</code></td><td>GC runs without reclaiming</td><td>almost always a leak</td></tr></tbody></table></div>\n<p>Other frequent causes: unbounded caches, an oversized string intern pool, loading whole files or query results into memory instead of streaming.</p>\n<h2>Tuning — the flags worth remembering</h2>\n<pre><code class=\"language-bash\"># heap sizing\n-Xms2g -Xmx2g            # equal values = no expensive resizing\n\n# G1 goals\n-XX:MaxGCPauseMillis=200               # pause target\n-XX:GCTimeRatio=9                      # throughput target\n-XX:InitiatingHeapOccupancyPercent=45  # start the concurrent cycle earlier\n\n# native memory\n-XX:MaxMetaspaceSize=512m\n-XX:MaxDirectMemorySize=256m\n\n# logging\n-Xlog:gc*</code></pre>\n<h3>A method, not guesswork</h3>\n<ol><li><strong>Measure</strong> — JVisualVM / JConsole / JFR.</li><li><strong>State the application's character</strong> — low latency or maximum throughput? What allocation rate?</li><li><strong>Start with the default collector.</strong> G1 is a sound starting point for most applications.</li><li><strong>Test under production-like load.</strong></li><li><strong>Change one parameter at a time.</strong> Three changes at once means you do not know which one worked.</li></ol>\n<h2>Metaspace instead of PermGen</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>PermGen (≤ Java 7)</th><th>Metaspace (Java 8+)</th></tr></thead><tbody><tr><td>Location</td><td>part of the Java heap</td><td><strong>native memory</strong></td></tr><tr><td>Size</td><td>fixed</td><td>grows dynamically</td></tr><tr><td>Tuning</td><td>frequent and painful</td><td>rarely needed</td></tr></tbody></table></div>\n<p>Reasons for the change: scalability, simpler tuning, and more efficient allocation of metadata in native memory.</p>\n<p><strong>A nuance worth knowing:</strong> a <code>ClassLoader</code> <strong>is a Java object living on the heap</strong>, but the data it manages — class definitions — sits in Metaspace. That is why a classloader leak (typical with repeated redeploys) surfaces as <code>OutOfMemoryError: Metaspace</code>, not as a heap error.</p>\n<h2>Object pooling</h2>\n<p><strong>What it buys:</strong> reuse of expensive objects (database connections, sockets, threads) instead of constant creation and collection. Fewer allocations means less GC pressure.</p>\n<p><strong>What it risks:</strong> an oversized pool keeps objects in memory while they are idle — and becomes a leak. An undersized pool wastes the benefit, because the application allocates anyway.</p>\n<p><strong>The canonical example:</strong> connection pools — HikariCP, Apache DBCP, C3P0.</p>\n<blockquote><p>For <strong>ordinary lightweight objects, pooling is an anti-pattern today</strong> — Eden allocation is so cheap that a pool adds complexity for no gain.</p></blockquote>\n<h2><code>finalize()</code> — why not to use it</h2>\n<pre><code class=\"language-java\">protected void finalize() throws Throwable</code></pre>\n<div class=\"table-wrap\"><table><thead><tr><th>Problem</th><th>Mechanism</th></tr></thead><tbody><tr><td><strong>Delays collection</strong></td><td>an object with <code>finalize()</code> enters the finalization queue and waits for the finalizer thread — it needs <strong>at least two GC cycles</strong></td></tr><tr><td><strong>Non-deterministic</strong></td><td>there is no guarantee <em>whether</em> or <em>when</em> it runs</td></tr><tr><td><strong>OOM risk</strong></td><td>with many objects pending finalization</td></tr></tbody></table></div>\n<p><strong>Use instead:</strong> <code>try-with-resources</code> for resources, <code>java.lang.ref.Cleaner</code> for lifecycle-bound cleanup.</p>\n<h2>Interview questions</h2>\n<p><strong>Q: How does GC decide what to remove?</strong> <strong>A:</strong> Reachability analysis from GC roots — threads, local variables on the stack, static fields, JNI references. Unreachable is garbage. It is not reference counting, so cycles are not a problem.</p>\n<p><strong>Q: Why two survivor spaces?</strong> <strong>A:</strong> So one is always empty. Copying into the empty space compacts memory on every minor GC, so young-generation fragmentation never arises.</p>\n<p><strong>Q: What is a memory leak in a garbage-collected language?</strong> <strong>A:</strong> An object that remains reachable while being logically unnecessary. The GC is working correctly — the code is holding the reference.</p>\n<p><strong>Q: You get <code>OutOfMemoryError</code> in production. First step?</strong> <strong>A:</strong> Read <strong>which</strong> variant — heap, Metaspace, direct buffer or native thread. Each leads somewhere different. Then the heap dump (ideally already enabled via <code>-XX:+HeapDumpOnOutOfMemoryError</code>) and reference chains in MAT.</p>\n<p><strong>Q: Why set <code>-Xms</code> equal to <code>-Xmx</code>?</strong> <strong>A:</strong> So the JVM does not resize the heap at runtime — resizing is expensive and makes measurements unpredictable.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong><code>-Xmx</code> does not bound the process</strong>, only the heap. In a container what counts is the sum: heap + Metaspace + thread stacks + direct buffers + code cache.</li><li><strong>&quot;GC freed memory&quot; ≠ &quot;the OS got it back&quot;.</strong> The JVM may retain freed heap for itself.</li><li><strong>Concurrent collectors still pause.</strong> G1 and CMS need a stop-the-world initial mark phase.</li><li><strong><code>System.gc()</code> in production code</strong> can force a full GC and wreck latency.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_EN\">JVM architecture, JRE and class loaders</a> · <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_EN\">JIT, the Java Memory Model, monitoring and observability</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_EN\">Multithreading — threads, executors, deadlocks</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a></p>"},"Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL":{"title":"Zarządzanie pamięcią i Garbage Collection","category":"Java/JVM_Internals","date":"2026-11-04","tags":["java","jvm","gc","memory","heap","oom","tuning","interview"],"minutes":9,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>GC działa na <strong>osiągalności z GC roots</strong>, a nie na liczniku referencji. Obiekt nieosiągalny = śmieć, niezależnie od tego, ile referencji na niego wskazuje.</li><li><strong>Większość obiektów umiera młodo</strong> — na tym założeniu opiera się cały podział na generacje.</li><li>Dwie przestrzenie Survivor istnieją po to, by <strong>kompaktować pamięć przy każdym Minor GC</strong> i uniknąć fragmentacji.</li><li><strong>Wyciek pamięci w Javie to nie błąd GC</strong> — to obiekt, który wciąż jest osiągalny, choć nie powinien.</li><li><code>OutOfMemoryError</code> ma <strong>kilka różnych wariantów</strong> i każdy diagnozuje się inaczej.</li></ul></blockquote>\n<h2>Dlaczego to w ogóle istnieje</h2>\n<p>W C/C++ pamięcią zarządza programista — stąd wiszące wskaźniki i podwójne zwolnienia. JVM automatyzuje przydział i zwalnianie, eliminując całą klasę błędów. Cena: <strong>pauzy i narzut CPU</strong>. Dlatego strojenie GC jest realną pracą inżynierską, a nie ezoteryką.</p>\n<h2>Mapa pamięci procesu JVM</h2>\n<pre><code>Pamięć systemu operacyjnego\n  └── Proces JVM\n      ├── Heap            ← zarządzany przez GC\n      ├── Stack           ← per wątek\n      └── Pamięć natywna  ← bezpośrednio z OS\n          ├── Metaspace\n          ├── Code Cache\n          ├── Direct Buffers (NIO)\n          ├── dane natywne wątków\n          └── biblioteki JNI</code></pre>\n<p><strong>Praktyczny wniosek:</strong> <code>-Xmx</code> ogranicza <strong>tylko</strong> stertę. Proces JVM potrafi zużywać znacznie więcej — i to najczęstsza przyczyna zaskoczenia przy ustawianiu limitów pamięci w Kubernetesie.</p>\n<h2>Struktura sterty i cykl życia obiektu</h2>\n<pre><code>┌──────────────── Young Generation ────────────────┐  ┌─── Old Generation ───┐\n│    Eden     │  Survivor S0   │   Survivor S1     │  │  obiekty promowane   │\n│ nowe obiekty│  jedna zajęta, druga zawsze pusta  │  │  po przekroczeniu    │\n│             │                                     │  │  tenuring threshold  │\n└─────────────┴─────────────────────────────────────┘  └──────────────────────┘</code></pre>\n<ol><li><code>new</code> alokuje w <strong>Eden</strong> (strategia <em>bump-pointer</em> — bardzo tani przydział).</li><li>Minor GC: żywe obiekty z Edenu trafiają do pustej przestrzeni Survivor (np. S0).</li><li>Kolejny cykl: żywe z Edenu <strong>i</strong> z S0 są kopiowane do S1. Wiek każdego ocalałego rośnie o 1.</li><li>Po przekroczeniu <strong>tenuring threshold</strong> obiekt jest promowany do Old Gen.</li></ol>\n<h3>Dlaczego dwie przestrzenie Survivor, a nie jedna</h3>\n<p>To pytanie oddziela osoby, które czytały, od tych, które rozumieją.</p>\n<blockquote><p>W danym momencie <strong>jedna przestrzeń Survivor jest zawsze pusta</strong>. Przy każdym Minor GC obiekty są kopiowane do tej pustej. Kopiowanie <strong>samo w sobie kompaktuje pamięć</strong> — nie trzeba osobnego algorytmu defragmentacji.</p></blockquote>\n<p>Korzyści: szybki przydział (bump-pointer w Edenie), tani Minor GC (większość obiektów i tak jest martwa), zerowa fragmentacja młodej generacji.</p>\n<h2>GC roots — fundament całego mechanizmu</h2>\n<p>GC nie liczy referencji. GC wykonuje <strong>analizę osiągalności</strong>: startuje z korzeni i idzie po grafie obiektów.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Typ GC root</th><th>Dlaczego jest korzeniem</th></tr></thead><tbody><tr><td>Aktywne wątki</td><td>są niezbędne do wykonania programu</td></tr><tr><td>Zmienne lokalne i parametry na stosie</td><td>metoda właśnie ich używa</td></tr><tr><td>Pola statyczne załadowanych klas</td><td>żyją tak długo jak klasa</td></tr><tr><td>Referencje z JNI</td><td>JVM zakłada, że kod natywny ich używa</td></tr></tbody></table></div>\n<p>Wszystko osiągalne z korzeni → <strong>żywe</strong>. Reszta → <strong>śmieci</strong>.</p>\n<blockquote><p><strong>Konsekwencja, o którą pytają:</strong> obiekt z tysiącem referencji między sobą nawzajem, ale bez ścieżki od korzenia, zostanie zebrany. Cykle referencji <strong>nie są</strong> problemem w Javie — w odróżnieniu od zliczania referencji.</p></blockquote>\n<h2>Fazy GC</h2>\n<ol><li><strong>Identyfikacja żywych</strong> — osiągalnych z GC roots.</li><li><strong>Mark</strong> — przejście grafu i oznaczenie osiągalnych.</li><li><strong>Sweep</strong> — odzyskanie pamięci nieoznaczonych.</li><li><strong>Compact</strong> — opcjonalne przesunięcie obiektów przeciw fragmentacji.</li></ol>\n<h2>Stop-the-World</h2>\n<p><strong>Czym jest:</strong> JVM wstrzymuje <strong>wszystkie</strong> wątki aplikacji, by wykonać operacje wymagające stabilnego obrazu pamięci.</p>\n<p><strong>Dlaczego konieczne:</strong> referencje zmieniają się w trakcie działania programu. Gdyby wątek modyfikował referencje podczas analizy, GC zebrałby żywy obiekt albo zostawił martwy. STW gwarantuje spójność.</p>\n<p><strong>Kiedy występuje:</strong> Minor GC · Major/Full GC · czyszczenie metadanych i wyładowywanie klas · <strong>faza initial mark nawet w kolektorach współbieżnych</strong> (G1, CMS).</p>\n<p><strong>Skala problemu:</strong> dla sterty 8 GB z milionami obiektów Full GC potrafi zatrzymać aplikację na setki milisekund. Dla usługi obsługującej tysiące żądań na sekundę pauza 500 ms jest odczuwalna dla użytkownika.</p>\n<p><strong>Jak zmniejszać:</strong> nowoczesne kolektory (G1, ZGC, Shenandoah) wykonujące większość pracy współbieżnie · strojenie rozmiaru sterty tak, by Full GC był rzadki · ograniczenie produkcji obiektów tymczasowych.</p>\n<h2>Minor GC kontra Major GC</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Minor GC</th><th>Major / Full GC</th></tr></thead><tbody><tr><td><strong>Zakres</strong></td><td>Young Generation</td><td>Old Generation, często cała sterta</td></tr><tr><td><strong>Wyzwalacz</strong></td><td>Eden jest pełny</td><td>Old Gen bliski zapełnienia, <code>System.gc()</code>, operacje JVM</td></tr><tr><td><strong>Częstotliwość</strong></td><td>często</td><td>rzadko</td></tr><tr><td><strong>Czas pauzy</strong></td><td>krótki (ms)</td><td>od setek ms do sekund</td></tr><tr><td><strong>Koszt</strong></td><td>niski</td><td>wysoki — CPU i czas</td></tr></tbody></table></div>\n<blockquote><p><code>System.gc()</code> <strong>nie jest poleceniem</strong>, tylko sugestią — i w kodzie produkcyjnym jest antywzorcem.</p></blockquote>\n<h2>Wycieki pamięci</h2>\n<p><strong>Definicja:</strong> obiekt nie jest już potrzebny, ale <strong>wciąż jest osiągalny</strong>, więc GC nie może go zebrać. To błąd w kodzie, nie w GC.</p>\n<h3>Typowe przyczyny</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Przyczyna</th><th>Mechanizm</th></tr></thead><tbody><tr><td><strong>Pola statyczne</strong></td><td>żyją tyle, co aplikacja — duży obiekt w <code>static</code> nigdy nie zniknie</td></tr><tr><td><strong>Niezamknięte zasoby</strong></td><td>strumienie, gniazda, połączenia do bazy</td></tr><tr><td><strong>Kolekcje bez usuwania</strong></td><td><code>List</code>/<code>Map</code> rosnąca w nieskończoność</td></tr><tr><td><strong>Listenery i callbacki</strong></td><td>zarejestrowane, nigdy niewyrejestrowane</td></tr><tr><td><strong>Klasy wewnętrzne / anonimowe</strong></td><td>niejawna referencja do klasy zewnętrznej</td></tr><tr><td><strong><code>ThreadLocal</code></strong></td><td>wątek z puli żyje długo i trzyma wartość</td></tr></tbody></table></div>\n<h3>Przykład — kanoniczny wyciek</h3>\n<pre><code class=\"language-java\">public class MemoryLeakExample {\n    // pole statyczne: osiągalne przez całe życie aplikacji\n    private static final List&lt;byte[]&gt; leak = new ArrayList&lt;&gt;();\n\n    public static void main(String[] args) {\n        while (true) {\n            leak.add(new byte[1024 * 1024]); // 1 MB, nigdy nieusuwane\n        }\n    }\n}</code></pre>\n<h3>Jak wykryć</h3>\n<ol><li><strong>Obserwuj zużycie w czasie</strong> — JVisualVM, JConsole, Java Flight Recorder. Sygnał: pamięć rośnie i <strong>nie spada po cyklach GC</strong>.</li><li><strong>Włącz logi GC</strong> — <code>-Xlog:gc*</code>. Sygnał: Full GC uruchamia się często, a pamięć nie wraca.</li><li><strong>Zrób heap dump</strong> i analizuj.</li><li><strong>Sprawdź retained heap i łańcuchy referencji</strong> — dlaczego obiekt wciąż żyje.</li></ol>\n<h3>Jak naprawić</h3>\n<pre><code class=\"language-java\">// zamykaj zasoby — try-with-resources zamiast finally\ntry (FileInputStream fis = new FileInputStream(&quot;file.txt&quot;)) {\n    // użycie strumienia\n} catch (IOException e) {\n    log.error(&quot;nie udało się odczytać pliku&quot;, e);\n}</code></pre>\n<ul><li>Ogranicz pola statyczne do rzeczy <strong>naprawdę</strong> globalnych.</li><li>Usuwaj elementy z kolekcji; dla cache'y używaj <code>WeakHashMap</code> albo biblioteki z eviction.</li><li>Wyrejestrowuj listenery.</li><li><code>WeakReference</code> / <code>SoftReference</code> tam, gdzie referencja <strong>nie powinna</strong> blokować zbierania.</li></ul>\n<h2>Heap dump</h2>\n<p><strong>Czym jest:</strong> migawka wszystkich obiektów na stercie w danym momencie — wraz z referencjami i zużyciem pamięci. Format <code>.hprof</code>.</p>\n<pre><code class=\"language-bash\"># ręcznie, tylko żywe obiekty\njmap -dump:live,format=b,file=heap.hprof &lt;pid&gt;</code></pre>\n<pre><code># automatycznie przy OOM — ustaw to ZANIM wystąpi awaria\n-XX:+HeapDumpOnOutOfMemoryError\n-XX:HeapDumpPath=/sciezka/heapdump.hprof</code></pre>\n<p><strong>Co analizować</strong> (Eclipse MAT, VisualVM, JProfiler):</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Widok</th><th>Odpowiada na pytanie</th></tr></thead><tbody><tr><td><strong>Dominator Tree</strong></td><td>który obiekt trzyma największy podgraf pamięci</td></tr><tr><td><strong>Histogram</strong></td><td>ile instancji każdego typu i ile zajmują</td></tr><tr><td><strong>Reference Chains</strong></td><td><em>dlaczego</em> ten obiekt wciąż żyje — ścieżka do GC root</td></tr></tbody></table></div>\n<p><strong>Przykład z praktyki:</strong> aplikacja webowa rzuca <code>OutOfMemoryError: Java heap space</code> po kilku godzinach. Heap dump pokazuje <code>HashMap</code> z milionami wpisów, choć logika biznesowa zakłada tysiąc. Mapa nigdy nie była czyszczona między żądaniami.</p>\n<h2>Warianty <code>OutOfMemoryError</code></h2>\n<p><strong>Każdy wariant to inna diagnoza.</strong> Czytanie komunikatu do końca oszczędza godziny.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Komunikat</th><th>Co się wyczerpało</th><th>Pierwszy krok</th></tr></thead><tbody><tr><td><code>Java heap space</code></td><td>sterta</td><td>heap dump, szukaj wycieku lub za małego <code>-Xmx</code></td></tr><tr><td><code>Metaspace</code></td><td>metadane klas</td><td>sprawdź dynamiczne generowanie klas, proxy, przeładowania</td></tr><tr><td><code>Direct buffer memory</code></td><td>bufory NIO poza stertą</td><td><code>-XX:MaxDirectMemorySize</code>, audyt kodu NIO</td></tr><tr><td><code>unable to create new native thread</code></td><td>pamięć natywna / limit OS</td><td>za dużo wątków, źle skonfigurowane pule</td></tr><tr><td><code>GC overhead limit exceeded</code></td><td>GC pracuje, nie odzyskując</td><td>prawie zawsze wyciek</td></tr></tbody></table></div>\n<p>Dodatkowe częste przyczyny: nieograniczone cache'y, zbyt duży string intern pool, wczytywanie całych plików lub wyników zapytań do pamięci zamiast strumieniowania.</p>\n<h2>Strojenie — parametry warte zapamiętania</h2>\n<pre><code class=\"language-bash\"># rozmiar sterty\n-Xms2g -Xmx2g            # równe wartości = brak kosztownego zmieniania rozmiaru\n\n# cele G1\n-XX:MaxGCPauseMillis=200            # cel pauzy\n-XX:GCTimeRatio=9                   # cel przepustowości\n-XX:InitiatingHeapOccupancyPercent=45  # wcześniejszy start cyklu współbieżnego\n\n# pamięć natywna\n-XX:MaxMetaspaceSize=512m\n-XX:MaxDirectMemorySize=256m\n\n# logowanie\n-Xlog:gc*</code></pre>\n<h3>Metoda, nie zgadywanie</h3>\n<ol><li><strong>Zmierz</strong> — JVisualVM / JConsole / JFR.</li><li><strong>Nazwij charakterystykę aplikacji</strong> — niskie opóźnienie czy maksymalna przepustowość? Jakie tempo alokacji?</li><li><strong>Zacznij od domyślnego kolektora.</strong> G1 to dobry punkt wyjścia dla większości aplikacji.</li><li><strong>Testuj pod obciążeniem zbliżonym do produkcyjnego.</strong></li><li><strong>Zmieniaj jeden parametr naraz.</strong> Trzy zmiany naraz oznaczają, że nie wiesz, która zadziałała.</li></ol>\n<h2>Metaspace zamiast PermGen</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>PermGen (≤ Java 7)</th><th>Metaspace (Java 8+)</th></tr></thead><tbody><tr><td>Lokalizacja</td><td>część sterty Javy</td><td><strong>pamięć natywna</strong></td></tr><tr><td>Rozmiar</td><td>stały</td><td>rośnie dynamicznie</td></tr><tr><td>Strojenie</td><td>częste i uciążliwe</td><td>rzadko potrzebne</td></tr></tbody></table></div>\n<p>Powód zmiany: skalowalność, prostsze strojenie i wydajniejszy przydział metadanych w pamięci natywnej.</p>\n<p><strong>Niuans wart znania:</strong> <code>ClassLoader</code> <strong>jest obiektem Javy i żyje na stercie</strong>, ale dane, którymi zarządza — definicje klas — leżą w Metaspace. To dlatego wyciek classloaderów (typowy przy wielokrotnym redeploy) objawia się jako <code>OutOfMemoryError: Metaspace</code>, a nie jako błąd sterty.</p>\n<h2>Object pooling</h2>\n<p><strong>Co daje:</strong> ponowne użycie drogich obiektów (połączenia do bazy, gniazda, wątki) zamiast ciągłego tworzenia i zbierania. Mniej alokacji → mniejsza presja na GC.</p>\n<p><strong>Czym grozi:</strong> zbyt duża pula trzyma obiekty w pamięci, choć nie są używane — i staje się wyciekiem. Zbyt mała niweczy korzyść, bo aplikacja i tak tworzy nowe obiekty.</p>\n<p><strong>Kanoniczny przykład:</strong> pula połączeń — HikariCP, Apache DBCP, C3P0.</p>\n<blockquote><p>Dla <strong>zwykłych, lekkich obiektów pooling jest dziś antywzorcem</strong> — alokacja w Edenie jest tak tania, że pula dokłada złożoność bez zysku.</p></blockquote>\n<h2><code>finalize()</code> — dlaczego go nie używać</h2>\n<pre><code class=\"language-java\">protected void finalize() throws Throwable</code></pre>\n<div class=\"table-wrap\"><table><thead><tr><th>Problem</th><th>Mechanizm</th></tr></thead><tbody><tr><td><strong>Opóźnia zbieranie</strong></td><td>obiekt z <code>finalize()</code> trafia do kolejki finalizacji i czeka na wątek Finalizer — potrzebuje <strong>co najmniej dwóch cykli GC</strong></td></tr><tr><td><strong>Niedeterministyczny</strong></td><td>nie wiadomo <em>czy</em> i <em>kiedy</em> się wykona</td></tr><tr><td><strong>Ryzyko OOM</strong></td><td>przy dużej liczbie obiektów oczekujących na finalizację</td></tr></tbody></table></div>\n<p><strong>Zamiast tego:</strong> <code>try-with-resources</code> dla zasobów, <code>java.lang.ref.Cleaner</code> dla sprzątania powiązanego z cyklem życia obiektu.</p>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Jak GC decyduje, co usunąć?</strong> <strong>O:</strong> Analizą osiągalności od GC roots — wątki, zmienne lokalne na stosie, pola statyczne, referencje JNI. Co nieosiągalne, to śmieć. To nie jest zliczanie referencji, więc cykle nie są problemem.</p>\n<p><strong>P: Dlaczego dwie przestrzenie Survivor?</strong> <strong>O:</strong> Żeby jedna była zawsze pusta. Kopiowanie do pustej przestrzeni kompaktuje pamięć przy każdym Minor GC, więc fragmentacja młodej generacji nie powstaje.</p>\n<p><strong>P: Czym jest wyciek pamięci w języku z GC?</strong> <strong>O:</strong> Obiektem, który jest wciąż osiągalny, choć logicznie już niepotrzebny. GC działa poprawnie — to kod trzyma referencję.</p>\n<p><strong>P: Masz <code>OutOfMemoryError</code> na produkcji. Pierwszy krok?</strong> <strong>O:</strong> Przeczytać, <strong>który</strong> wariant — heap, Metaspace, direct buffer czy native thread. Każdy prowadzi w inne miejsce. Potem heap dump (najlepiej już wcześniej włączony przez <code>-XX:+HeapDumpOnOutOfMemoryError</code>) i łańcuchy referencji w MAT.</p>\n<p><strong>P: Po co <code>-Xms</code> równe <code>-Xmx</code>?</strong> <strong>O:</strong> Żeby JVM nie zmieniała rozmiaru sterty w czasie pracy — zmiana rozmiaru jest kosztowna i wprowadza nieprzewidywalność w pomiarach.</p>\n<h2>Pułapki</h2>\n<ul><li><strong><code>-Xmx</code> nie ogranicza procesu</strong>, tylko stertę. W kontenerze liczy się suma: sterta + Metaspace + stosy wątków + direct buffers + code cache.</li><li><strong>„GC zwolnił pamięć&quot; ≠ „system operacyjny ją odzyskał&quot;.</strong> JVM potrafi trzymać zwolnioną stertę dla siebie.</li><li><strong>Kolektory współbieżne też mają pauzy.</strong> G1 i CMS wymagają fazy initial mark w trybie STW.</li><li><strong><code>System.gc()</code> w kodzie produkcyjnym</strong> potrafi wymusić Full GC i zepsuć opóźnienia.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/JVM_Internals/JVM_Architecture_And_Classloaders_PL\">Architektura JVM, JRE i class loadery</a> · <a href=\"#/Java/JVM_Internals/JIT_JMM_GC_Monitoring_PL\">JIT, Java Memory Model, monitoring i observability</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_PL\">Wielowątkowość — wątki, executory, zakleszczenia</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a></p>"},"Java/Language_Fundamentals/Exception_Handling_And_IO_EN":{"title":"Exception handling and I/O operations","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","exceptions","error-handling","io","try-with-resources","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>An <strong>exception</strong> is an event you can recover from. An <strong><code>Error</code></strong> is a situation you usually cannot.</li><li><strong>Checked</strong> must be handled or declared. <strong>Unchecked</strong> (<code>RuntimeException</code>, <code>Error</code> and subclasses) need neither.</li><li><code>throw</code> <strong>throws</strong> an exception; <code>throws</code> <strong>declares</strong> that a method may throw one.</li><li><code>finally</code> runs almost always — <strong>except</strong> after <code>System.exit()</code> or a fatal JVM failure.</li><li><strong><code>try-with-resources</code> (Java 7) replaces <code>finally</code> for closing resources.</strong> Make it your default.</li></ul></blockquote>\n<h2>Mental model</h2>\n<p>Exceptions are a <strong>separate communication channel</strong> alongside the return value. Ordinary code flows down the main course; when something goes wrong, control jumps onto a side track to the nearest matching <code>catch</code> — possibly several stack frames up.</p>\n<p>That is what keeps business logic from being interleaved with error-code checks. It is the main advantage over the classic &quot;return −1&quot;.</p>\n<h2>Key concepts</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Concept</th><th>Meaning</th></tr></thead><tbody><tr><td><code>throw</code></td><td><strong>throws</strong> an exception object, interrupting the normal flow</td></tr><tr><td><code>throws</code></td><td><strong>declares</strong> in the signature that a method may throw — forces the caller to deal with it</td></tr><tr><td><strong>checked</strong></td><td>the compiler requires handling or declaration (= <em>compile-time</em>)</td></tr><tr><td><strong>unchecked</strong></td><td><code>RuntimeException</code>, <code>Error</code> and their subclasses (= <em>runtime</em>)</td></tr><tr><td><strong>stack trace</strong></td><td>the list of classes and methods from application start to the throw site</td></tr><tr><td><strong>chaining</strong></td><td>an exception thrown in response to another, preserving the cause</td></tr></tbody></table></div>\n<h2>Hierarchy: <code>Exception</code> versus <code>Error</code></h2>\n<ul><li><strong><code>Exception</code></strong> — a condition you <strong>can recover from</strong>. The file is missing → ask for another one.</li><li><strong><code>Error</code></strong> — usually an <strong>external</strong> situation you cannot recover from. Everything the JVM throws.</li></ul>\n<p>The common JVM errors:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Error</th><th>When</th></tr></thead><tbody><tr><td><code>OutOfMemoryError</code></td><td>the JVM cannot allocate an object and GC freed nothing → <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a></td></tr><tr><td><code>StackOverflowError</code></td><td>a thread's stack is exhausted, typically by recursion that goes too deep</td></tr><tr><td><code>ExceptionInInitializerError</code></td><td>an exception during a static initialiser</td></tr><tr><td><code>NoClassDefFoundError</code></td><td>the classloader <strong>could not find</strong> a class definition absent from the classpath</td></tr><tr><td><code>UnsupportedClassVersionError</code></td><td>a <code>.class</code> file built by a newer Java than the one reading it</td></tr></tbody></table></div>\n<blockquote><p>You <strong>can</strong> catch an <code>Error</code> in a <code>try</code>, but it is <strong>bad practice</strong> — there is no guarantee the program can do anything reliably afterwards.</p></blockquote>\n<h3><code>ClassNotFoundException</code> versus <code>NoClassDefFoundError</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>ClassNotFoundException</code></th><th><code>NoClassDefFoundError</code></th></tr></thead><tbody><tr><td>Kind</td><td><strong>checked exception</strong></td><td><strong>Error</strong></td></tr><tr><td>When</td><td>a dynamically loaded class (reflection, <code>Class.forName</code>) does not exist</td><td>the class <strong>was</strong> there at compile time, but the JVM cannot find it at runtime</td></tr></tbody></table></div>\n<h2>How to handle</h2>\n<pre><code class=\"language-java\">try {\n    // &quot;guarded&quot; code\n} catch (ExceptionType1 ex) {\n    // ...\n} catch (ExceptionType2 ex) {\n    // ...\n} finally {\n    // runs after the try block exits — exception or not\n}</code></pre>\n<h3>Three ways to handle multiple exceptions</h3>\n<pre><code class=\"language-java\">// 1. One broad catch — WORKS, but do not do this\ntry { /* ... */ } catch (Exception ex) { /* ... */ }\n\n// 2. Multiple catch blocks — child BEFORE parent, otherwise a compile error\ntry { /* ... */ }\ncatch (FileNotFoundException ex) { /* ... */ }\ncatch (EOFException ex)          { /* ... */ }\n\n// 3. Multi-catch (Java 7) — less duplication\ntry { /* ... */ }\ncatch (FileNotFoundException | EOFException ex) { /* ... */ }</code></pre>\n<blockquote><p><strong>Rule:</strong> catch as <strong>narrowly</strong> as you can. An over-broad handler catches exceptions you never anticipated and turns a failure into quiet, wrong behaviour.</p></blockquote>\n<h2>Exception chaining</h2>\n<p>You throw a new exception <strong>in response</strong> to another while preserving the original cause. Without it you lose the whole history of the problem.</p>\n<pre><code class=\"language-java\">try {\n    task.readConfigFile();\n} catch (FileNotFoundException ex) {\n    throw new TaskException(&quot;Could not perform task&quot;, ex);   // ex = cause\n}</code></pre>\n<p><code>Throwable.getCause()</code> retrieves the cause set via the constructor or <code>initCause()</code>.</p>\n<h2>Custom exceptions</h2>\n<p>Create your own type when:</p>\n<ul><li>no existing platform type describes the situation,</li><li>you want to give the caller <strong>more context</strong> to react precisely.</li></ul>\n<pre><code class=\"language-java\">class MyException extends Exception {\n    public MyException(String message) { super(message); }\n}</code></pre>\n<p><strong>Checked or unchecked?</strong> Rule of thumb: if code using your exception <strong>can be expected to recover</strong>, make it checked. Otherwise unchecked. Inherit from the <strong>most specific</strong> matching class; if there is none, from <code>Exception</code>.</p>\n<h2><code>try-with-resources</code> (Java 7)</h2>\n<p>Automatically closes resources implementing <code>AutoCloseable</code> — files, sockets, connections.</p>\n<pre><code class=\"language-java\">try (BufferedReader br = new BufferedReader(new FileReader(&quot;file.txt&quot;))) {\n    // ...\n} catch (IOException e) {\n    log.error(&quot;Failed to read the file&quot;, e);\n}</code></pre>\n<p>Advantages over a hand-written <code>finally</code>:</p>\n<ul><li>The resource is <strong>always</strong> closed, even when the <code>catch</code> itself throws.</li><li>An exception from <code>close()</code> does not <strong>mask</strong> the one from the <code>try</code> block — it goes to the suppressed exceptions (<code>getSuppressed()</code>).</li></ul>\n<blockquote><p>That last point is a real bug in hand-written <code>finally</code> code: an exception thrown in <code>finally</code> <strong>swallows</strong> the one from <code>try</code> or <code>catch</code>.</p></blockquote>\n<h2>Exceptions and inheritance — overriding rules</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Parent method</th><th>What the child method may do</th></tr></thead><tbody><tr><td>declares nothing</td><td><strong>no checked</strong>, any unchecked</td></tr><tr><td>declares checked <code>A, B</code></td><td>none, a subset, or <strong>narrower</strong> subtypes; never broader or new ones</td></tr><tr><td>declares unchecked</td><td>any unchecked, even unrelated ones</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">// ✅ OK — fewer exceptions and a narrower scope\nclass Parent {\n    void doSomething()     throws IOException, ParseException { }\n    void doSomethingElse() throws IOException { }\n}\nclass Child extends Parent {\n    void doSomething()     throws IOException { }\n    void doSomethingElse() throws FileNotFoundException, EOFException { }\n}\n\n// ❌ Compile error — IOException is BROADER than FileNotFoundException\nclass P { void doSomething() throws FileNotFoundException { } }\nclass C extends P { void doSomething() throws IOException { } }</code></pre>\n<h2>Exceptions in lambdas</h2>\n<p>Java's standard functional interfaces have <strong>no <code>throws</code> clause</strong> — so inside a lambda passed to <code>forEach</code>, <code>map</code> and friends you can only throw <strong>unchecked</strong> exceptions.</p>\n<pre><code class=\"language-java\">List&lt;Integer&gt; integers = Arrays.asList(3, 9, 7, 0, 10, 20);\nintegers.forEach(i -&gt; {\n    if (i == 0) throw new IllegalArgumentException(&quot;Zero not allowed&quot;);\n    System.out.println(Math.PI / i);\n});</code></pre>\n<p>With your <strong>own</strong> functional interface, checked exceptions are possible:</p>\n<pre><code class=\"language-java\">@FunctionalInterface\npublic interface CheckedFunction&lt;T&gt; {\n    void apply(T t) throws Exception;\n}\n\npublic void processTasks(List&lt;Task&gt; tasks, CheckedFunction&lt;Task&gt; fn) {\n    for (Task task : tasks) {\n        try { fn.apply(task); } catch (Exception e) { /* ... */ }\n    }\n}</code></pre>\n<h2>Interview questions</h2>\n<p><strong>Q: How does <code>throw</code> differ from <code>throws</code>?</strong> <strong>A:</strong> <code>throw</code> is a statement — it throws a specific exception object. <code>throws</code> is part of the signature — it tells callers the method may throw that type and, for checked exceptions, forces them to handle it.</p>\n<p><strong>Q: Checked or unchecked — how do you choose for a custom exception?</strong> <strong>A:</strong> Can the caller realistically react and carry on? If yes — checked. If it is a programming error or an unrecoverable state — unchecked.</p>\n<p><strong>Q: Does <code>finally</code> always run?</strong> <strong>A:</strong> Almost. It does not run after <code>System.exit()</code>, a fatal JVM failure, a killed process, or a stopped thread. And an exception thrown <strong>inside</strong> <code>finally</code> will mask the one from <code>try</code>.</p>\n<p><strong>Q: What does this code throw?</strong></p>\n<pre><code class=\"language-java\">Integer[][] ints = { { 1, 2, 3 }, { null }, { 7, 8, 9 } };\nSystem.out.println(&quot;value = &quot; + ints[1][1].intValue());</code></pre>\n<p><strong>A:</strong> <code>ArrayIndexOutOfBoundsException</code>, not <code>NullPointerException</code>. The array <code>ints[1]</code> has <strong>length 1</strong>, so index <code>1</code> is out of bounds before the <code>null</code> is ever dereferenced.</p>\n<p><strong>Q: Why is exception handling considered expensive?</strong> <strong>A:</strong> The main cost is <strong>building the stack trace</strong> when the exception object is created — it requires walking the stack. On top of that comes the disruption of normal flow and the loss of JIT optimisation on that path. Which is why an exception is not a flow-control tool.</p>\n<p><strong>Q: Can you throw a checked exception from a method with no <code>throws</code>?</strong> <strong>A:</strong> Yes — a <em>sneaky throw</em>, exploiting type erasure. A curiosity, not a pattern:</p>\n<pre><code class=\"language-java\">@SuppressWarnings(&quot;unchecked&quot;)\npublic &lt;T extends Throwable&gt; void sneakyThrow(Throwable ex) throws T {\n    throw (T) ex;\n}</code></pre>\n<h2>Best practices</h2>\n<ul><li><strong>Catch specifically</strong>, not <code>catch (Exception e)</code>.</li><li><strong>Never an empty <code>catch</code></strong> — a swallowed exception is the most expensive kind of bug.</li><li><strong>Log through SLF4J/Log4j</strong>, not <code>System.out.println</code>. Log the <strong>exception</strong>, not just <code>e.getMessage()</code>, or you lose the stack trace.</li><li><strong>Always <code>try-with-resources</code></strong> instead of a hand-written <code>finally</code> for closing.</li><li><strong>Preserve the cause</strong> when wrapping — <code>new TaskException(msg, ex)</code>, not <code>new TaskException(msg)</code>.</li><li><strong>Custom exceptions</strong> for domain context.</li></ul>\n<h2>Pitfalls</h2>\n<ul><li><strong>Parent before child in <code>catch</code></strong> → compile error. Order matters.</li><li><strong><code>return</code> in <code>finally</code></strong> overrides the <code>try</code> value and <strong>swallows the exception</strong>. Never do it.</li><li><strong>Catching <code>Error</code></strong> — technically allowed, almost never sensible.</li><li><strong>Exceptions as flow control</strong> — expensive and unreadable.</li><li><strong><code>e.printStackTrace()</code> in production</strong> — goes to <code>stderr</code> outside the logging system, so it never reaches Kibana.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_EN\">Type system and language building blocks</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN\">Java 8 — lambdas, functional interfaces, streams</a> · <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_PL\">Obsługa wyjątków i operacje I/O</a></p>"},"Java/Language_Fundamentals/Exception_Handling_And_IO_PL":{"title":"Obsługa wyjątków i operacje I/O","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","exceptions","error-handling","io","try-with-resources","interview"],"minutes":7,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li><strong>Wyjątek</strong> = zdarzenie, z którego da się wyjść. <strong><code>Error</code></strong> = sytuacja, z której zwykle nie da się wyjść.</li><li><strong>Checked</strong> musisz obsłużyć albo zadeklarować. <strong>Unchecked</strong> (<code>RuntimeException</code>, <code>Error</code> i potomkowie) — nie musisz.</li><li><code>throw</code> <strong>rzuca</strong> wyjątek, <code>throws</code> <strong>deklaruje</strong>, że metoda może go rzucić.</li><li><code>finally</code> wykonuje się prawie zawsze — <strong>poza</strong> <code>System.exit()</code> i fatalnym błędem JVM.</li><li><strong><code>try-with-resources</code> (Java 7) zastępuje <code>finally</code> do zamykania zasobów.</strong> Używaj go domyślnie.</li></ul></blockquote>\n<h2>Model mentalny</h2>\n<p>Wyjątki to <strong>oddzielny kanał komunikacji</strong> obok wartości zwracanej. Zwykły kod płynie głównym nurtem; gdy coś pójdzie źle, sterowanie przeskakuje bocznym torem do najbliższego <code>catch</code>, który pasuje — nawet kilka ramek stosu wyżej.</p>\n<p>Dzięki temu logika biznesowa nie jest poprzeplatana sprawdzaniem kodów błędu. To główna przewaga wyjątków nad klasycznym „zwróć −1&quot;.</p>\n<h2>Kluczowe pojęcia</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Pojęcie</th><th>Znaczenie</th></tr></thead><tbody><tr><td><code>throw</code></td><td><strong>rzuca</strong> obiekt wyjątku, przerywając normalny przepływ</td></tr><tr><td><code>throws</code></td><td><strong>deklaruje</strong> w sygnaturze, że metoda może rzucić wyjątek — wymusza obsługę u wywołującego</td></tr><tr><td><strong>checked</strong></td><td>kompilator wymaga obsługi albo deklaracji (= <em>compile-time</em>)</td></tr><tr><td><strong>unchecked</strong></td><td><code>RuntimeException</code>, <code>Error</code> i ich potomkowie (= <em>runtime</em>)</td></tr><tr><td><strong>stack trace</strong></td><td>lista klas i metod od startu aplikacji aż do punktu rzucenia</td></tr><tr><td><strong>chaining</strong></td><td>wyjątek rzucony w odpowiedzi na inny, z zachowaniem przyczyny</td></tr></tbody></table></div>\n<h2>Hierarchia: <code>Exception</code> kontra <code>Error</code></h2>\n<ul><li><strong><code>Exception</code></strong> — stan, z którego <strong>da się wyjść</strong>. Plik nie istnieje → poproś o inny.</li><li><strong><code>Error</code></strong> — zwykle <strong>zewnętrzna</strong> sytuacja, z której wyjść się nie da. Wszystko rzucane przez JVM.</li></ul>\n<p>Najczęstsze błędy JVM:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Error</th><th>Kiedy</th></tr></thead><tbody><tr><td><code>OutOfMemoryError</code></td><td>JVM nie może zaalokować obiektu, a GC nie zwolnił pamięci → <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a></td></tr><tr><td><code>StackOverflowError</code></td><td>wyczerpany stos wątku, typowo przez zbyt głęboką rekurencję</td></tr><tr><td><code>ExceptionInInitializerError</code></td><td>wyjątek w inicjalizatorze statycznym</td></tr><tr><td><code>NoClassDefFoundError</code></td><td>classloader <strong>nie znalazł</strong> definicji klasy, której nie było w classpath</td></tr><tr><td><code>UnsupportedClassVersionError</code></td><td>plik <code>.class</code> zbudowany nowszą wersją Javy niż ta, która go czyta</td></tr></tbody></table></div>\n<blockquote><p><code>Error</code> <strong>da się</strong> złapać w <code>try</code>, ale to <strong>zła praktyka</strong> — nie ma gwarancji, że program zrobi potem cokolwiek sensownego.</p></blockquote>\n<h3><code>ClassNotFoundException</code> kontra <code>NoClassDefFoundError</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>ClassNotFoundException</code></th><th><code>NoClassDefFoundError</code></th></tr></thead><tbody><tr><td>Typ</td><td><strong>checked exception</strong></td><td><strong>Error</strong></td></tr><tr><td>Kiedy</td><td>klasa ładowana dynamicznie (refleksja, <code>Class.forName</code>) nie istnieje</td><td>klasa <strong>była</strong> przy kompilacji, ale JVM nie znajduje jej w runtime</td></tr></tbody></table></div>\n<h2>Jak obsługiwać</h2>\n<pre><code class=\"language-java\">try {\n    // kod &quot;chroniony&quot;\n} catch (ExceptionType1 ex) {\n    // ...\n} catch (ExceptionType2 ex) {\n    // ...\n} finally {\n    // wykonuje się po wyjściu z try — niezależnie od tego, czy był wyjątek\n}</code></pre>\n<h3>Trzy sposoby na wiele wyjątków</h3>\n<pre><code class=\"language-java\">// 1. Jeden szeroki catch — DZIAŁA, ale nie rób tego\ntry { /* ... */ } catch (Exception ex) { /* ... */ }\n\n// 2. Wiele bloków catch — dziecko PRZED rodzicem, inaczej błąd kompilacji\ntry { /* ... */ }\ncatch (FileNotFoundException ex) { /* ... */ }\ncatch (EOFException ex)          { /* ... */ }\n\n// 3. Multi-catch (Java 7) — mniej duplikacji\ntry { /* ... */ }\ncatch (FileNotFoundException | EOFException ex) { /* ... */ }</code></pre>\n<blockquote><p><strong>Reguła:</strong> łap tak <strong>wąsko</strong>, jak się da. Zbyt szeroki handler łapie wyjątki, których nie przewidziałeś, i zamienia awarię w ciche, błędne zachowanie.</p></blockquote>\n<h2>Łańcuchowanie wyjątków</h2>\n<p>Rzucasz nowy wyjątek <strong>w odpowiedzi</strong> na inny, zachowując oryginalną przyczynę. Bez tego gubisz całą historię problemu.</p>\n<pre><code class=\"language-java\">try {\n    task.readConfigFile();\n} catch (FileNotFoundException ex) {\n    throw new TaskException(&quot;Could not perform task&quot;, ex);   // ex = cause\n}</code></pre>\n<p><code>Throwable.getCause()</code> wyciąga przyczynę ustawioną konstruktorem lub przez <code>initCause()</code>.</p>\n<h2>Własne wyjątki</h2>\n<p>Twórz własny typ, gdy:</p>\n<ul><li>żaden istniejący typ z platformy nie opisuje sytuacji,</li><li>chcesz przekazać wywołującemu <strong>więcej kontekstu</strong> do precyzyjnej reakcji.</li></ul>\n<pre><code class=\"language-java\">class MyException extends Exception {\n    public MyException(String message) { super(message); }\n}</code></pre>\n<p><strong>Checked czy unchecked?</strong> Reguła kciuka: jeśli kod używający Twojego wyjątku <strong>może się po nim podnieść</strong> — checked. Jeśli nie — unchecked. Dziedzicz po <strong>najbardziej szczegółowej</strong> pasującej klasie; jeśli takiej nie ma, po <code>Exception</code>.</p>\n<h2><code>try-with-resources</code> (Java 7)</h2>\n<p>Automatycznie zamyka zasoby implementujące <code>AutoCloseable</code> — pliki, gniazda, połączenia.</p>\n<pre><code class=\"language-java\">try (BufferedReader br = new BufferedReader(new FileReader(&quot;file.txt&quot;))) {\n    // ...\n} catch (IOException e) {\n    log.error(&quot;Nie udało się odczytać pliku&quot;, e);\n}</code></pre>\n<p>Zalety nad ręcznym <code>finally</code>:</p>\n<ul><li>Zasób zamyka się <strong>zawsze</strong>, także gdy <code>catch</code> sam rzuci.</li><li>Wyjątek z <code>close()</code> nie <strong>przykrywa</strong> wyjątku z bloku <code>try</code> — trafia do <em>suppressed exceptions</em> (<code>getSuppressed()</code>).</li></ul>\n<blockquote><p>To ostatnie jest realnym bugiem w kodzie z ręcznym <code>finally</code>: wyjątek rzucony w <code>finally</code> <strong>zagłusza</strong> wyjątek z <code>try</code> lub <code>catch</code>.</p></blockquote>\n<h2>Wyjątki a dziedziczenie — reguły nadpisywania</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Metoda rodzica</th><th>Co może metoda dziecka</th></tr></thead><tbody><tr><td>nie deklaruje nic</td><td><strong>żadnych checked</strong>, dowolne unchecked</td></tr><tr><td>deklaruje checked <code>A, B</code></td><td>żadne, podzbiór, lub <strong>węższe</strong> podtypy; nigdy szersze ani nowe</td></tr><tr><td>deklaruje unchecked</td><td>dowolne unchecked, nawet niespokrewnione</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">// ✅ OK — mniej wyjątków i węższy zakres\nclass Parent {\n    void doSomething()     throws IOException, ParseException { }\n    void doSomethingElse() throws IOException { }\n}\nclass Child extends Parent {\n    void doSomething()     throws IOException { }\n    void doSomethingElse() throws FileNotFoundException, EOFException { }\n}\n\n// ❌ Błąd kompilacji — IOException jest SZERSZy niż FileNotFoundException\nclass P { void doSomething() throws FileNotFoundException { } }\nclass C extends P { void doSomething() throws IOException { } }</code></pre>\n<h2>Wyjątki w lambdach</h2>\n<p>Standardowe interfejsy funkcyjne Javy <strong>nie mają klauzuli <code>throws</code></strong> — więc w lambdzie przekazanej do <code>forEach</code>, <code>map</code> itd. możesz rzucić <strong>tylko unchecked</strong>.</p>\n<pre><code class=\"language-java\">List&lt;Integer&gt; integers = Arrays.asList(3, 9, 7, 0, 10, 20);\nintegers.forEach(i -&gt; {\n    if (i == 0) throw new IllegalArgumentException(&quot;Zero not allowed&quot;);\n    System.out.println(Math.PI / i);\n});</code></pre>\n<p>Z <strong>własnym</strong> interfejsem funkcyjnym checked są możliwe:</p>\n<pre><code class=\"language-java\">@FunctionalInterface\npublic interface CheckedFunction&lt;T&gt; {\n    void apply(T t) throws Exception;\n}\n\npublic void processTasks(List&lt;Task&gt; tasks, CheckedFunction&lt;Task&gt; fn) {\n    for (Task task : tasks) {\n        try { fn.apply(task); } catch (Exception e) { /* ... */ }\n    }\n}</code></pre>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Czym różni się <code>throw</code> od <code>throws</code>?</strong> <strong>O:</strong> <code>throw</code> to instrukcja — rzuca konkretny obiekt wyjątku. <code>throws</code> to element sygnatury — informuje wywołującego, że metoda może rzucić dany typ, i przy checked wymusza na nim obsługę.</p>\n<p><strong>P: Checked czy unchecked — jak wybrać przy własnym wyjątku?</strong> <strong>O:</strong> Czy wywołujący ma realną możliwość zareagować i kontynuować? Jeśli tak — checked. Jeśli to błąd programisty albo stan nienaprawialny — unchecked.</p>\n<p><strong>P: Czy <code>finally</code> zawsze się wykona?</strong> <strong>O:</strong> Prawie. Nie wykona się po <code>System.exit()</code>, przy fatalnym błędzie JVM, zabiciu procesu albo zatrzymaniu wątku. Dodatkowo wyjątek rzucony <strong>wewnątrz</strong> <code>finally</code> przykryje ten z <code>try</code>.</p>\n<p><strong>P: Co rzuci ten kod?</strong></p>\n<pre><code class=\"language-java\">Integer[][] ints = { { 1, 2, 3 }, { null }, { 7, 8, 9 } };\nSystem.out.println(&quot;value = &quot; + ints[1][1].intValue());</code></pre>\n<p><strong>O:</strong> <code>ArrayIndexOutOfBoundsException</code>, nie <code>NullPointerException</code>. Tablica <code>ints[1]</code> ma <strong>długość 1</strong>, więc indeks <code>1</code> wychodzi poza nią, zanim w ogóle dojdzie do wyłuskania <code>null</code>.</p>\n<p><strong>P: Dlaczego obsługa wyjątków jest kosztowna?</strong> <strong>O:</strong> Główny koszt to <strong>budowa stack trace'u</strong> przy tworzeniu obiektu wyjątku — wymaga przejścia stosu. Do tego dochodzi przerwanie normalnego przepływu i utrata optymalizacji JIT na tej ścieżce. Dlatego wyjątek nie jest narzędziem sterowania przepływem.</p>\n<p><strong>P: Czy można rzucić checked z metody bez <code>throws</code>?</strong> <strong>O:</strong> Tak — <em>sneaky throw</em>, wykorzystując wymazywanie typów. Ciekawostka, nie wzorzec:</p>\n<pre><code class=\"language-java\">@SuppressWarnings(&quot;unchecked&quot;)\npublic &lt;T extends Throwable&gt; void sneakyThrow(Throwable ex) throws T {\n    throw (T) ex;\n}</code></pre>\n<h2>Dobre praktyki</h2>\n<ul><li><strong>Łap konkretnie</strong>, nie <code>catch (Exception e)</code>.</li><li><strong>Nigdy pusty <code>catch</code></strong> — połknięty wyjątek to najdroższy rodzaj błędu.</li><li><strong>Loguj przez SLF4J/Log4j</strong>, nie <code>System.out.println</code>. Loguj <strong>wyjątek</strong>, nie tylko <code>e.getMessage()</code> — stracisz stack trace.</li><li><strong>Zawsze <code>try-with-resources</code></strong> zamiast ręcznego <code>finally</code> do zamykania.</li><li><strong>Zachowuj przyczynę</strong> przy opakowywaniu — <code>new TaskException(msg, ex)</code>, nie <code>new TaskException(msg)</code>.</li><li><strong>Własne wyjątki</strong> dla kontekstu domenowego.</li></ul>\n<h2>Pułapki</h2>\n<ul><li><strong>Rodzic przed dzieckiem w <code>catch</code></strong> → błąd kompilacji. Kolejność ma znaczenie.</li><li><strong><code>return</code> w <code>finally</code></strong> nadpisuje wartość z <code>try</code> i <strong>połyka wyjątek</strong>. Nigdy tego nie rób.</li><li><strong>Łapanie <code>Error</code></strong> — technicznie wolno, praktycznie prawie nigdy nie ma sensu.</li><li><strong>Wyjątek jako sterowanie przepływem</strong> — kosztowny i nieczytelny.</li><li><strong><code>e.printStackTrace()</code> w produkcji</strong> — trafia na <code>stderr</code> poza systemem logowania, więc nie zobaczysz go w Kibanie.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_PL\">System typów i podstawowe konstrukcje języka</a> · <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL\">Java 8 — lambdy, interfejsy funkcyjne, strumienie</a> · <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_EN\">Exception handling and I/O operations</a></p>"},"Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN":{"title":"Java 8 — lambdas, functional interfaces, streams","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","java8","lambda","streams","optional","functional-interface","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>A <strong>functional interface</strong> has exactly <strong>one</strong> abstract method. <code>default</code> methods do not count.</li><li>A <strong>lambda</strong> is a function you can pass around like an object — its target type is a functional interface.</li><li>A stream has <strong>intermediate</strong> operations (lazy, return a <code>Stream</code>) and <strong>terminal</strong> ones (they start the processing).</li><li><strong>Without a terminal operation a stream does nothing.</strong> That is the most common trap.</li><li><code>map</code> returns a value, <strong><code>flatMap</code> returns a stream</strong> and flattens the nesting.</li><li><code>Optional</code> is a <strong>return</strong> type, not an entity field — it is not <code>Serializable</code>.</li></ul></blockquote>\n<h2>What Java 8 brought</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Feature</th><th>What for</th></tr></thead><tbody><tr><td><strong>Lambdas</strong></td><td>treating actions as objects</td></tr><tr><td><strong>Method references</strong></td><td>a lambda written as a method name, without invoking it</td></tr><tr><td><strong><code>Optional</code></strong></td><td>expressing &quot;the value may be absent&quot; explicitly</td></tr><tr><td><strong>Functional interfaces</strong></td><td>the target type for a lambda</td></tr><tr><td><strong><code>default</code> methods</strong></td><td>adding a method to an interface without breaking implementations</td></tr><tr><td><strong>Stream API</strong></td><td>declarative collection processing</td></tr><tr><td><strong>Date API</strong> (<code>java.time</code>)</td><td>immutable, thread-safe dates</td></tr><tr><td><strong>Nashorn</strong></td><td>the JavaScript engine in the JDK (successor to Rhino; <code>jjs</code> on the console)</td></tr></tbody></table></div>\n<h2>Functional interfaces</h2>\n<p><strong>Definition:</strong> an interface with <strong>exactly one</strong> abstract method — no more, no less. <code>default</code> methods do <strong>not</strong> bump that count.</p>\n<p>The <code>@FunctionalInterface</code> annotation is <strong>informative</strong> — it does not change semantics, but it makes the compiler enforce the rule.</p>\n<pre><code class=\"language-java\">// Before Java 8\nThread thread = new Thread(new Runnable() {\n    public void run() { System.out.println(&quot;Hello World!&quot;); }\n});\n\n// After — Runnable is a functional interface\nThread thread = new Thread(() -&gt; System.out.println(&quot;Hello World!&quot;));</code></pre>\n<h3>The standard library — <code>java.util.function</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Interface</th><th>Takes</th><th>Returns</th></tr></thead><tbody><tr><td><code>Function&lt;T,R&gt;</code></td><td>1 argument</td><td>a result</td></tr><tr><td><code>Consumer&lt;T&gt;</code></td><td>1 argument</td><td>nothing (a side effect)</td></tr><tr><td><code>Supplier&lt;T&gt;</code></td><td>nothing</td><td>a result</td></tr><tr><td><code>Predicate&lt;T&gt;</code></td><td>1 argument</td><td><code>boolean</code></td></tr><tr><td><code>BiFunction&lt;T,U,R&gt;</code></td><td>2 arguments</td><td>a result</td></tr><tr><td><code>BinaryOperator&lt;T&gt;</code></td><td>2 arguments of <strong>the same type</strong></td><td>a result of <strong>the same type</strong></td></tr><tr><td><code>UnaryOperator&lt;T&gt;</code></td><td>1 argument</td><td>a result of <strong>the same type</strong></td></tr></tbody></table></div>\n<pre><code class=\"language-java\">Function&lt;String, String&gt; toUpperCase = String::toUpperCase;\nPredicate&lt;String&gt; longerThanThree = name -&gt; name.length() &gt; 3;\n\nList&lt;String&gt; filtered = names.stream()\n        .map(toUpperCase)\n        .filter(longerThanThree)\n        .collect(Collectors.toList());</code></pre>\n<p>The payoff: the logic becomes <strong>reusable and composable</strong>, and the code declarative.</p>\n<h3>Will this compile?</h3>\n<pre><code class=\"language-java\">@FunctionalInterface\npublic interface Function2&lt;T, U, V&gt; {\n    V apply(T t, U u);\n    default void count() { /* ... */ }\n}</code></pre>\n<p><strong>Yes.</strong> One abstract method, and <code>count()</code> is <code>default</code>, so it does not count towards the limit.</p>\n<h2>Lambdas</h2>\n<p>A lambda is <strong>a function you can reference and pass around like an object</strong>. The natural replacement for anonymous classes used as method arguments.</p>\n<p>Syntax: <code>params -&gt; expressions</code></p>\n<div class=\"table-wrap\"><table><thead><tr><th>Element</th><th>Optional when</th></tr></thead><tbody><tr><td>Parameter type</td><td>always — the compiler infers it</td></tr><tr><td>Parentheses</td><td>there is <strong>one</strong> parameter; required for several</td></tr><tr><td>Braces</td><td>the body is <strong>one</strong> statement</td></tr><tr><td><code>return</code></td><td>the expression yields a value and there are <strong>no</strong> braces</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">(a, b) -&gt; { return a + b; }   // ✅\n(a, b) -&gt; a + b               // ✅ equivalent</code></pre>\n<h2>Method references</h2>\n<p><strong>Syntactic sugar</strong> that shortens lambdas. Recognisable by <code>::</code>.</p>\n<pre><code class=\"language-java\">(o) -&gt; o.toString()     →   Object::toString</code></pre>\n<div class=\"table-wrap\"><table><thead><tr><th>Variant</th><th>Example</th></tr></thead><tbody><tr><td>Constructor</td><td><code>String::new</code></td></tr><tr><td>Static method</td><td><code>String::valueOf</code></td></tr><tr><td><strong>Bound</strong> instance method</td><td><code>str::toString</code></td></tr><tr><td><strong>Unbound</strong> instance method</td><td><code>String::toString</code></td></tr></tbody></table></div>\n<blockquote><p><code>String::valueOf</code> is a reference to the <strong>static</strong> <code>valueOf</code> method of <code>String</code>.</p></blockquote>\n<h2><code>default</code> methods</h2>\n<p>A method <strong>with an implementation</strong> inside an interface. It solves backward compatibility.</p>\n<pre><code class=\"language-java\">public interface Vehicle {\n    void move();\n    default void hoot() { System.out.println(&quot;peep!&quot;); }\n}</code></pre>\n<p>Without <code>default</code>, adding <code>forEach</code> to the <code>Collection</code> interface would have <strong>broken the entire collections API</strong> — every implementation in every project on earth would stop compiling.</p>\n<h3>Clash between two <code>default</code> methods</h3>\n<p>When a class implements two interfaces with a same-named <code>default</code> method, it <strong>must</strong> override it and resolve the conflict explicitly:</p>\n<pre><code class=\"language-java\">interface A { default void show() { System.out.println(&quot;A's show method&quot;); } }\ninterface B { default void show() { System.out.println(&quot;B's show method&quot;); } }\n\nclass C implements A, B {\n    @Override public void show() {\n        A.super.show();   // explicit resolution\n    }\n}</code></pre>\n<h2><code>Optional</code></h2>\n<p>A container for <strong>zero or one</strong> element. Instead of a wrapped <code>null</code> it has <code>Optional.empty()</code>.</p>\n<p><strong>Its designers' main intent:</strong> a <strong>return type</strong> for methods that previously returned <code>null</code>. It forces the caller to treat both cases explicitly.</p>\n<pre><code class=\"language-java\">int min1 = Arrays.stream(new int[]{1, 2, 3, 4, 5}).min().orElse(0);   // 1\nint min2 = Arrays.stream(new int[]{}).min().orElse(0);                // 0</code></pre>\n<pre><code class=\"language-java\">class Employee {\n    Optional&lt;Department&gt; department;\n    Employee(Department d) { this.department = Optional.ofNullable(d); }\n}\n\nemp.department.map(d -&gt; d.name).orElse(&quot;No Department&quot;);</code></pre>\n<blockquote><p><strong>Important:</strong> <code>Optional</code> is <strong>not</strong> Scala's <code>Option</code>. <strong>Do not use it as an entity field</strong> — it does not implement <code>Serializable</code>, and its authors explicitly did not intend that use.</p></blockquote>\n<h2>Streams</h2>\n<p>A stream is <strong>an iterator that accepts a set of actions</strong> to apply to each element. It represents a sequence of objects from a source (e.g. a collection) and supports aggregate operations.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Collection</th><th>Stream</th></tr></thead><tbody><tr><td>Iteration</td><td><strong>external</strong> — you write the loop</td><td><strong>internal</strong> — the iteration logic lives in the stream</td></tr><tr><td>Processing</td><td>eager</td><td><strong>lazy</strong></td></tr><tr><td>Style</td><td>imperative</td><td>declarative, chainable</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">int sum = Arrays.stream(new int[]{1, 2, 3})\n  .filter(i -&gt; i &gt;= 2)\n  .map(i -&gt; i * 3)\n  .sum();</code></pre>\n<h3>Intermediate versus terminal operations</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Intermediate</th><th>Terminal</th></tr></thead><tbody><tr><td>Return</td><td>a <code>Stream</code></td><td>a final result</td></tr><tr><td>Behaviour</td><td><strong>lazy</strong> — compute nothing at the call site</td><td><strong>trigger</strong> the whole pipeline</td></tr><tr><td>Examples</td><td><code>filter</code>, <code>map</code>, <code>flatMap</code>, <code>sorted</code>, <code>distinct</code></td><td><code>forEach</code>, <code>reduce</code>, <code>collect</code>, <code>sum</code>, <code>findFirst</code></td></tr></tbody></table></div>\n<p><strong>Proof that intermediate operations are lazy:</strong></p>\n<pre><code class=\"language-java\">System.out.println(&quot;Stream without terminal operation&quot;);\nArrays.stream(new int[]{1, 2, 3}).map(i -&gt; {\n    System.out.println(&quot;doubling &quot; + i);\n    return i * 2;\n});\n\nSystem.out.println(&quot;Stream with terminal operation&quot;);\nArrays.stream(new int[]{1, 2, 3}).map(i -&gt; {\n    System.out.println(&quot;doubling &quot; + i);\n    return i * 2;\n}).sum();</code></pre>\n<p>Output:</p>\n<pre><code>Stream without terminal operation\nStream with terminal operation\ndoubling 1\ndoubling 2\ndoubling 3</code></pre>\n<p>The first pipeline printed <strong>nothing</strong> — no terminal operation.</p>\n<h3><code>map</code> versus <code>flatMap</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>map</code></th><th><code>flatMap</code></th></tr></thead><tbody><tr><td>The function returns</td><td>a <strong>value</strong></td><td>a <strong>stream</strong></td></tr><tr><td>Effect</td><td>the result stays wrapped in its ordinal type</td><td>nested streams get <strong>flattened</strong> into one</td></tr><tr><td>In <code>Optional</code></td><td><code>Optional&lt;String&gt;</code></td><td><code>String</code></td></tr></tbody></table></div>\n<pre><code class=\"language-java\">Map&lt;String, List&lt;String&gt;&gt; people = new HashMap&lt;&gt;();\npeople.put(&quot;John&quot;,  Arrays.asList(&quot;555-1123&quot;, &quot;555-3389&quot;));\npeople.put(&quot;Mary&quot;,  Arrays.asList(&quot;555-2243&quot;, &quot;555-5264&quot;));\npeople.put(&quot;Steve&quot;, Arrays.asList(&quot;555-6654&quot;, &quot;555-3242&quot;));\n\nList&lt;String&gt; phones = people.values().stream()\n  .flatMap(Collection::stream)     // List&lt;List&lt;String&gt;&gt; → Stream&lt;String&gt;\n  .collect(Collectors.toList());</code></pre>\n<h2>The common operations — cheatsheet</h2>\n<pre><code class=\"language-java\">// filter + sort\nList&lt;Employee&gt; filtered = employees.stream()\n    .filter(emp -&gt; emp.getSalary() &gt; 50_000)\n    .sorted(Comparator.comparingDouble(Employee::getSalary))\n    .collect(Collectors.toList());\n\n// grouping\nMap&lt;String, List&lt;Employee&gt;&gt; byDept = employees.stream()\n    .collect(Collectors.groupingBy(Employee::getDepartment));\n\n// grouping + counting\nMap&lt;String, Long&gt; wordCount = words.stream()\n    .collect(Collectors.groupingBy(w -&gt; w, Collectors.counting()));\n\n// reduction\nint totalSalary = employees.stream()\n    .map(Employee::getSalary)\n    .reduce(0, Integer::sum);\n\n// joining\nString productList = products.stream()\n    .map(Product::getName)\n    .collect(Collectors.joining(&quot;, &quot;));\n\n// distinct\nList&lt;String&gt; unique = names.stream().distinct().collect(Collectors.toList());\n\n// creating a stream\nStream&lt;String&gt;  s1 = Stream.of(&quot;Java&quot;, &quot;Python&quot;, &quot;C++&quot;);\nStream&lt;Integer&gt; s2 = Arrays.stream(new Integer[]{1, 2, 3, 4});\n\n// in parallel\nList&lt;Employee&gt; big = largeList.parallelStream()\n    .filter(emp -&gt; emp.getSalary() &gt; 5_000)\n    .collect(Collectors.toList());</code></pre>\n<h3><code>findFirst()</code> versus <code>findAny()</code></h3>\n<ul><li><code>findFirst()</code> — <strong>always the first</strong> element in stream order.</li><li><code>findAny()</code> — <strong>any</strong> element; optimised for parallel processing.</li></ul>\n<h2>The new Date API (<code>java.time</code>)</h2>\n<p>The old <code>java.util.Date</code> and <code>SimpleDateFormat</code> are <strong>not thread-safe</strong> — a genuine source of concurrency bugs. On top of that, poor API design: years counted from 1900, months from 1, days from 0.</p>\n<p>Hence the popularity of Joda-Time, and in Java 8 the <code>java.time</code> package modelled on it: <strong>immutable</strong> and thread-safe.</p>\n<h2>Interview questions</h2>\n<p><strong>Q: What is a functional interface?</strong> <strong>A:</strong> An interface with exactly one abstract method. It provides the <em>target type</em> for a lambda or method reference — the lambda's arguments and return type must match that single method. <code>default</code> and <code>static</code> methods do not count.</p>\n<p><strong>Q: Why are intermediate operations lazy?</strong> <strong>A:</strong> So the whole pipeline can run in a <strong>single pass</strong> over the data, and so terminal operations like <code>findFirst</code> can stop early. With no terminal operation the pipeline never runs at all.</p>\n<p><strong>Q: <code>map</code> or <code>flatMap</code>?</strong> <strong>A:</strong> <code>map</code> when the function returns a single value. <code>flatMap</code> when it returns a stream or collection and you want one flat stream rather than a stream of streams.</p>\n<p><strong>Q: Is <code>Optional</code> suitable as an entity field?</strong> <strong>A:</strong> No. It does not implement <code>Serializable</code> and was never designed for that. Its place is the return type of a method that may have no result.</p>\n<p><strong>Q: Is a parallel stream always faster?</strong> <strong>A:</strong> No. It pays off on <strong>large</strong> data sets with stateless operations. On small collections the split-and-merge overhead exceeds the gain, and operations with side effects can produce wrong results.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong>A stream with no terminal operation</strong> does nothing — and reports no error.</li><li><strong>A stream cannot be reused</strong> — after a terminal operation it is closed (<code>IllegalStateException</code>).</li><li><strong>Side effects inside a lambda</strong> (a <code>forEach</code> mutating an outer list) break under <code>parallelStream</code>.</li><li><strong><code>Optional.get()</code> without a check</strong> is the same <code>NullPointerException</code> in a new wrapper. Use <code>orElse</code>, <code>orElseThrow</code>, <code>map</code>, <code>ifPresent</code>.</li><li><strong>Inside a lambda passed to a standard functional interface you can only throw unchecked exceptions</strong> → <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_EN\">Exception handling and I/O operations</a>.</li><li><strong><code>parallelStream()</code> uses the common ForkJoin pool by default</strong> — one slow pipeline can starve the others.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/Language_Fundamentals/OOP_Concepts_EN\">OOP concepts — inheritance, abstraction, polymorphism</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_EN\">Collections Framework — cheatsheet</a> · <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_EN\">Exception handling and I/O operations</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_EN\">Multithreading — threads, executors, deadlocks</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL\">Java 8 — lambdy, interfejsy funkcyjne, strumienie</a></p>"},"Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL":{"title":"Java 8 — lambdy, interfejsy funkcyjne, strumienie","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","java8","lambda","streams","optional","functional-interface","interview"],"minutes":7,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li><strong>Interfejs funkcyjny</strong> = dokładnie <strong>jedna</strong> metoda abstrakcyjna. Metody <code>default</code> się nie liczą.</li><li><strong>Lambda</strong> to funkcja, którą można przekazać jak obiekt — docelowym typem jest interfejs funkcyjny.</li><li>Strumień ma <strong>operacje pośrednie</strong> (leniwe, zwracają <code>Stream</code>) i <strong>terminalne</strong> (uruchamiają przetwarzanie).</li><li><strong>Bez operacji terminalnej strumień nie zrobi nic.</strong> To najczęstsza pułapka.</li><li><code>map</code> zwraca wartość, <strong><code>flatMap</code> zwraca strumień</strong> i spłaszcza zagnieżdżenie.</li><li><code>Optional</code> to typ <strong>zwracany</strong> z metod, nie pole encji — nie jest <code>Serializable</code>.</li></ul></blockquote>\n<h2>Co przyniosła Java 8</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Funkcja</th><th>Po co</th></tr></thead><tbody><tr><td><strong>Lambdy</strong></td><td>traktowanie akcji jak obiektów</td></tr><tr><td><strong>Referencje do metod</strong></td><td>lambda przez nazwę metody, bez jej wywołania</td></tr><tr><td><strong><code>Optional</code></strong></td><td>jawne wyrażenie „wartości może nie być&quot;</td></tr><tr><td><strong>Interfejsy funkcyjne</strong></td><td>typ docelowy dla lambdy</td></tr><tr><td><strong>Metody <code>default</code></strong></td><td>dodanie metody do interfejsu bez psucia implementacji</td></tr><tr><td><strong>Stream API</strong></td><td>deklaratywne przetwarzanie kolekcji</td></tr><tr><td><strong>Date API</strong> (<code>java.time</code>)</td><td>niemutowalne, bezpieczne wątkowo daty</td></tr><tr><td><strong>Nashorn</strong></td><td>silnik JavaScript w JDK (następca Rhino; <code>jjs</code> w konsoli)</td></tr></tbody></table></div>\n<h2>Interfejsy funkcyjne</h2>\n<p><strong>Definicja:</strong> interfejs z <strong>dokładnie jedną</strong> metodą abstrakcyjną — nie więcej, nie mniej. Metody <code>default</code> <strong>nie podbijają</strong> tego licznika.</p>\n<p>Adnotacja <code>@FunctionalInterface</code> jest <strong>informacyjna</strong> — nie zmienia semantyki, ale każe kompilatorowi pilnować reguły.</p>\n<pre><code class=\"language-java\">// Przed Java 8\nThread thread = new Thread(new Runnable() {\n    public void run() { System.out.println(&quot;Hello World!&quot;); }\n});\n\n// Po — Runnable jest interfejsem funkcyjnym\nThread thread = new Thread(() -&gt; System.out.println(&quot;Hello World!&quot;));</code></pre>\n<h3>Standardowa biblioteka — <code>java.util.function</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Interfejs</th><th>Bierze</th><th>Zwraca</th></tr></thead><tbody><tr><td><code>Function&lt;T,R&gt;</code></td><td>1 argument</td><td>wynik</td></tr><tr><td><code>Consumer&lt;T&gt;</code></td><td>1 argument</td><td>nic (efekt uboczny)</td></tr><tr><td><code>Supplier&lt;T&gt;</code></td><td>nic</td><td>wynik</td></tr><tr><td><code>Predicate&lt;T&gt;</code></td><td>1 argument</td><td><code>boolean</code></td></tr><tr><td><code>BiFunction&lt;T,U,R&gt;</code></td><td>2 argumenty</td><td>wynik</td></tr><tr><td><code>BinaryOperator&lt;T&gt;</code></td><td>2 argumenty <strong>tego samego typu</strong></td><td>wynik <strong>tego samego typu</strong></td></tr><tr><td><code>UnaryOperator&lt;T&gt;</code></td><td>1 argument</td><td>wynik <strong>tego samego typu</strong></td></tr></tbody></table></div>\n<pre><code class=\"language-java\">Function&lt;String, String&gt; toUpperCase = String::toUpperCase;\nPredicate&lt;String&gt; longerThanThree = name -&gt; name.length() &gt; 3;\n\nList&lt;String&gt; filtered = names.stream()\n        .map(toUpperCase)\n        .filter(longerThanThree)\n        .collect(Collectors.toList());</code></pre>\n<p>Zysk: logika staje się <strong>reużywalna i komponowalna</strong>, a kod deklaratywny.</p>\n<h3>Czy ten kod się skompiluje?</h3>\n<pre><code class=\"language-java\">@FunctionalInterface\npublic interface Function2&lt;T, U, V&gt; {\n    V apply(T t, U u);\n    default void count() { /* ... */ }\n}</code></pre>\n<p><strong>Tak.</strong> Jedna metoda abstrakcyjna, a <code>count()</code> jest <code>default</code> i nie wlicza się do limitu.</p>\n<h2>Lambdy</h2>\n<p>Lambda to <strong>funkcja, którą można referencjonować i przekazywać jak obiekt</strong>. Naturalny zamiennik klas anonimowych w roli argumentu metody.</p>\n<p>Składnia: <code>params -&gt; expressions</code></p>\n<div class=\"table-wrap\"><table><thead><tr><th>Element</th><th>Opcjonalny gdy</th></tr></thead><tbody><tr><td>Typ parametru</td><td>zawsze — kompilator go wywnioskuje</td></tr><tr><td>Nawiasy</td><td><strong>jeden</strong> parametr; przy wielu są wymagane</td></tr><tr><td>Klamry</td><td><strong>jedna</strong> instrukcja w ciele</td></tr><tr><td><code>return</code></td><td>wyrażenie zwraca wartość i <strong>nie ma</strong> klamer</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">(a, b) -&gt; { return a + b; }   // ✅\n(a, b) -&gt; a + b               // ✅ równoważne</code></pre>\n<h2>Referencje do metod</h2>\n<p><strong>Cukier składniowy</strong> skracający lambdy. Rozpoznasz po <code>::</code>.</p>\n<pre><code class=\"language-java\">(o) -&gt; o.toString()     →   Object::toString</code></pre>\n<div class=\"table-wrap\"><table><thead><tr><th>Wariant</th><th>Przykład</th></tr></thead><tbody><tr><td>Konstruktor</td><td><code>String::new</code></td></tr><tr><td>Metoda statyczna</td><td><code>String::valueOf</code></td></tr><tr><td>Metoda instancyjna <strong>związana</strong></td><td><code>str::toString</code></td></tr><tr><td>Metoda instancyjna <strong>niezwiązana</strong></td><td><code>String::toString</code></td></tr></tbody></table></div>\n<blockquote><p><code>String::valueOf</code> to referencja do <strong>statycznej</strong> metody <code>valueOf</code> klasy <code>String</code>.</p></blockquote>\n<h2>Metody <code>default</code></h2>\n<p>Metoda <strong>z implementacją</strong> w interfejsie. Rozwiązuje problem kompatybilności wstecznej.</p>\n<pre><code class=\"language-java\">public interface Vehicle {\n    void move();\n    default void hoot() { System.out.println(&quot;peep!&quot;); }\n}</code></pre>\n<p>Bez <code>default</code> dodanie <code>forEach</code> do interfejsu <code>Collection</code> <strong>zepsułoby całe API kolekcji</strong> — każda implementacja w każdym projekcie na świecie przestałaby się kompilować.</p>\n<h3>Konflikt dwóch metod <code>default</code></h3>\n<p>Gdy klasa implementuje dwa interfejsy z <code>default</code> o tej samej nazwie, <strong>musi</strong> nadpisać metodę i rozstrzygnąć konflikt jawnie:</p>\n<pre><code class=\"language-java\">interface A { default void show() { System.out.println(&quot;A's show method&quot;); } }\ninterface B { default void show() { System.out.println(&quot;B's show method&quot;); } }\n\nclass C implements A, B {\n    @Override public void show() {\n        A.super.show();   // jawne rozstrzygnięcie\n    }\n}</code></pre>\n<h2><code>Optional</code></h2>\n<p>Kontener na <strong>zero lub jeden</strong> element. Zamiast owiniętego <code>null</code> ma wartość <code>Optional.empty()</code>.</p>\n<p><strong>Główny cel wg autorów:</strong> <strong>typ zwracany</strong> z metod, które wcześniej zwracały <code>null</code>. Wymusza na wywołującym jawne potraktowanie obu przypadków.</p>\n<pre><code class=\"language-java\">int min1 = Arrays.stream(new int[]{1, 2, 3, 4, 5}).min().orElse(0);   // 1\nint min2 = Arrays.stream(new int[]{}).min().orElse(0);                // 0</code></pre>\n<pre><code class=\"language-java\">class Employee {\n    Optional&lt;Department&gt; department;\n    Employee(Department d) { this.department = Optional.ofNullable(d); }\n}\n\nemp.department.map(d -&gt; d.name).orElse(&quot;No Department&quot;);</code></pre>\n<blockquote><p><strong>Ważne:</strong> <code>Optional</code> <strong>nie</strong> jest odpowiednikiem <code>Option</code> ze Scali. <strong>Nie używaj go jako pola encji</strong> — nie implementuje <code>Serializable</code>, i autorzy wprost tego nie przewidzieli.</p></blockquote>\n<h2>Strumienie</h2>\n<p>Strumień to <strong>iterator, który przyjmuje zestaw akcji</strong> do zastosowania na każdym elemencie. Reprezentuje sekwencję obiektów ze źródła (np. kolekcji) i wspiera operacje agregujące.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Kolekcja</th><th>Strumień</th></tr></thead><tbody><tr><td>Iteracja</td><td><strong>zewnętrzna</strong> — piszesz pętlę</td><td><strong>wewnętrzna</strong> — logika iteracji jest w strumieniu</td></tr><tr><td>Przetwarzanie</td><td>natychmiastowe</td><td><strong>leniwe</strong></td></tr><tr><td>Styl</td><td>imperatywny</td><td>deklaratywny, łańcuchowalny</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">int sum = Arrays.stream(new int[]{1, 2, 3})\n  .filter(i -&gt; i &gt;= 2)\n  .map(i -&gt; i * 3)\n  .sum();</code></pre>\n<h3>Operacje pośrednie kontra terminalne</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Pośrednie</th><th>Terminalne</th></tr></thead><tbody><tr><td>Zwracają</td><td><code>Stream</code></td><td>wynik końcowy</td></tr><tr><td>Zachowanie</td><td><strong>leniwe</strong> — nic nie liczą w miejscu wywołania</td><td><strong>uruchamiają</strong> cały potok</td></tr><tr><td>Przykłady</td><td><code>filter</code>, <code>map</code>, <code>flatMap</code>, <code>sorted</code>, <code>distinct</code></td><td><code>forEach</code>, <code>reduce</code>, <code>collect</code>, <code>sum</code>, <code>findFirst</code></td></tr></tbody></table></div>\n<p><strong>Dowód, że pośrednie są leniwe:</strong></p>\n<pre><code class=\"language-java\">System.out.println(&quot;Stream without terminal operation&quot;);\nArrays.stream(new int[]{1, 2, 3}).map(i -&gt; {\n    System.out.println(&quot;doubling &quot; + i);\n    return i * 2;\n});\n\nSystem.out.println(&quot;Stream with terminal operation&quot;);\nArrays.stream(new int[]{1, 2, 3}).map(i -&gt; {\n    System.out.println(&quot;doubling &quot; + i);\n    return i * 2;\n}).sum();</code></pre>\n<p>Wyjście:</p>\n<pre><code>Stream without terminal operation\nStream with terminal operation\ndoubling 1\ndoubling 2\ndoubling 3</code></pre>\n<p>Pierwszy potok <strong>nie wypisał nic</strong> — brak operacji terminalnej.</p>\n<h3><code>map</code> kontra <code>flatMap</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th><code>map</code></th><th><code>flatMap</code></th></tr></thead><tbody><tr><td>Funkcja zwraca</td><td><strong>wartość</strong></td><td><strong>strumień</strong></td></tr><tr><td>Efekt</td><td>wynik zostaje opakowany w typ porządkowy</td><td>zagnieżdżone strumienie zostają <strong>spłaszczone</strong> w jeden</td></tr><tr><td>W <code>Optional</code></td><td><code>Optional&lt;String&gt;</code></td><td><code>String</code></td></tr></tbody></table></div>\n<pre><code class=\"language-java\">Map&lt;String, List&lt;String&gt;&gt; people = new HashMap&lt;&gt;();\npeople.put(&quot;John&quot;,  Arrays.asList(&quot;555-1123&quot;, &quot;555-3389&quot;));\npeople.put(&quot;Mary&quot;,  Arrays.asList(&quot;555-2243&quot;, &quot;555-5264&quot;));\npeople.put(&quot;Steve&quot;, Arrays.asList(&quot;555-6654&quot;, &quot;555-3242&quot;));\n\nList&lt;String&gt; phones = people.values().stream()\n  .flatMap(Collection::stream)     // List&lt;List&lt;String&gt;&gt; → Stream&lt;String&gt;\n  .collect(Collectors.toList());</code></pre>\n<h2>Najczęstsze operacje — ściągawka</h2>\n<pre><code class=\"language-java\">// filtrowanie + sortowanie\nList&lt;Employee&gt; filtered = employees.stream()\n    .filter(emp -&gt; emp.getSalary() &gt; 50_000)\n    .sorted(Comparator.comparingDouble(Employee::getSalary))\n    .collect(Collectors.toList());\n\n// grupowanie\nMap&lt;String, List&lt;Employee&gt;&gt; byDept = employees.stream()\n    .collect(Collectors.groupingBy(Employee::getDepartment));\n\n// grupowanie + zliczanie\nMap&lt;String, Long&gt; wordCount = words.stream()\n    .collect(Collectors.groupingBy(w -&gt; w, Collectors.counting()));\n\n// redukcja\nint totalSalary = employees.stream()\n    .map(Employee::getSalary)\n    .reduce(0, Integer::sum);\n\n// sklejanie\nString productList = products.stream()\n    .map(Product::getName)\n    .collect(Collectors.joining(&quot;, &quot;));\n\n// unikalne\nList&lt;String&gt; unique = names.stream().distinct().collect(Collectors.toList());\n\n// tworzenie strumienia\nStream&lt;String&gt;  s1 = Stream.of(&quot;Java&quot;, &quot;Python&quot;, &quot;C++&quot;);\nStream&lt;Integer&gt; s2 = Arrays.stream(new Integer[]{1, 2, 3, 4});\n\n// równolegle\nList&lt;Employee&gt; big = largeList.parallelStream()\n    .filter(emp -&gt; emp.getSalary() &gt; 5_000)\n    .collect(Collectors.toList());</code></pre>\n<h3><code>findFirst()</code> kontra <code>findAny()</code></h3>\n<ul><li><code>findFirst()</code> — <strong>zawsze pierwszy</strong> element w kolejności strumienia.</li><li><code>findAny()</code> — <strong>dowolny</strong>; zoptymalizowany pod przetwarzanie równoległe.</li></ul>\n<h2>Nowe Date API (<code>java.time</code>)</h2>\n<p>Stare <code>java.util.Date</code> i <code>SimpleDateFormat</code> <strong>nie są bezpieczne wątkowo</strong> — realne źródło błędów współbieżności. Do tego słabe API: lata liczone od 1900, miesiące od 1, dni od 0.</p>\n<p>Stąd popularność Joda-Time, a w Java 8 — pakiet <code>java.time</code> wzorowany na niej: <strong>niemutowalny</strong> i bezpieczny wątkowo.</p>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Co to interfejs funkcyjny?</strong> <strong>O:</strong> Interfejs z dokładnie jedną metodą abstrakcyjną. Dostarcza <em>typu docelowego</em> dla lambdy lub referencji do metody — argumenty i typ zwracany lambdy muszą pasować do tej jednej metody. Metody <code>default</code> i <code>static</code> nie wliczają się do licznika.</p>\n<p><strong>P: Dlaczego operacje pośrednie są leniwe?</strong> <strong>O:</strong> Żeby cały potok dało się wykonać <strong>jednym przejściem</strong> po danych i żeby operacje terminalne typu <code>findFirst</code> mogły przerwać przetwarzanie wcześniej. Bez operacji terminalnej potok nie wykona się w ogóle.</p>\n<p><strong>P: <code>map</code> czy <code>flatMap</code>?</strong> <strong>O:</strong> <code>map</code>, gdy funkcja zwraca pojedynczą wartość. <code>flatMap</code>, gdy zwraca strumień albo kolekcję i chcesz jeden płaski strumień zamiast strumienia strumieni.</p>\n<p><strong>P: Czy <code>Optional</code> nadaje się na pole encji?</strong> <strong>O:</strong> Nie. Nie implementuje <code>Serializable</code> i nie był do tego projektowany. Jego miejsce to typ zwracany metody, która może nie mieć wyniku.</p>\n<p><strong>P: Czy strumień równoległy jest zawsze szybszy?</strong> <strong>O:</strong> Nie. Opłaca się przy <strong>dużych</strong> zbiorach i operacjach bez stanu dzielonego. Przy małych kolekcjach narzut na podział i scalenie przewyższa zysk, a operacje z efektami ubocznymi mogą dać błędne wyniki.</p>\n<h2>Pułapki</h2>\n<ul><li><strong>Strumień bez operacji terminalnej</strong> nic nie robi — i nie zgłasza błędu.</li><li><strong>Strumienia nie da się użyć dwa razy</strong> — po operacji terminalnej jest zamknięty (<code>IllegalStateException</code>).</li><li><strong>Efekty uboczne w lambdzie</strong> (<code>forEach</code> modyfikujący listę zewnętrzną) psują się przy <code>parallelStream</code>.</li><li><strong><code>Optional.get()</code> bez sprawdzenia</strong> to ten sam <code>NullPointerException</code> w nowym opakowaniu. Używaj <code>orElse</code>, <code>orElseThrow</code>, <code>map</code>, <code>ifPresent</code>.</li><li><strong>W lambdzie przekazanej do standardowego interfejsu funkcyjnego rzucisz tylko unchecked</strong> → <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_PL\">Obsługa wyjątków i operacje I/O</a>.</li><li><strong><code>parallelStream()</code> domyślnie korzysta ze wspólnej puli ForkJoin</strong> — jeden wolny potok potrafi zagłodzić pozostałe.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/Language_Fundamentals/OOP_Concepts_PL\">Koncepcje obiektowe — dziedziczenie, abstrakcja, polimorfizm</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_PL\">Collections Framework — ściągawka</a> · <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_PL\">Obsługa wyjątków i operacje I/O</a> · <a href=\"#/Java/Concurrency/Multithreading_Executors_Deadlocks_PL\">Wielowątkowość — wątki, executory, zakleszczenia</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN\">Java 8 — lambdas, functional interfaces, streams</a></p>"},"Java/Language_Fundamentals/OOP_Concepts_EN":{"title":"OOP concepts — inheritance, abstraction, polymorphism","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","oop","inheritance","polymorphism","encapsulation","abstraction","interview"],"minutes":7,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>Four pillars of OOP: <strong>encapsulation, abstraction, inheritance, polymorphism</strong>.</li><li><strong>Abstraction</strong> hides the <em>implementation</em>; <strong>encapsulation</strong> hides the <em>data</em>. Different question, different answer.</li><li>Java has <strong>no multiple inheritance of classes</strong> — the diamond problem. It does allow multiple interfaces.</li><li>Static polymorphism = <strong>overloading</strong> (compile time). Dynamic polymorphism = <strong>overriding</strong> (runtime).</li><li><code>record</code> (Java 16) and <code>sealed</code> (Java 17) are the modern modelling tools — increasingly common interview material.</li></ul></blockquote>\n<h2>Mental model</h2>\n<p><strong>A class is a building's blueprint, an object is an actual building.</strong> The blueprint says what rooms exist (fields) and what you can do in them (methods). One blueprint yields many buildings, each with its own state.</p>\n<p>Where the analogy breaks: a building cannot &quot;inherit&quot; from another building and bolt on an extra floor. A class can.</p>\n<h2>Key concepts</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Concept</th><th>Definition</th><th>How you achieve it</th></tr></thead><tbody><tr><td><strong>Encapsulation</strong></td><td>Binding data and the methods that operate on it into one unit, plus hiding the data</td><td><code>private</code> fields + getters/setters with validation</td></tr><tr><td><strong>Abstraction</strong></td><td>Showing <em>what</em> a component does, hiding <em>how</em></td><td><code>abstract class</code>, <code>interface</code></td></tr><tr><td><strong>Inheritance</strong></td><td>The <strong>IS-A</strong> relationship: the child has everything the parent has (not vice versa)</td><td><code>extends</code></td></tr><tr><td><strong>Polymorphism</strong></td><td>One name, many behaviours</td><td>overloading + overriding</td></tr></tbody></table></div>\n<h3>Why OOP at all</h3>\n<ul><li>Easier development and maintenance.</li><li><strong>Data hiding</strong> → security.</li><li>Models real-world entities.</li><li><strong>Code reuse</strong> through inheritance → less duplication.</li><li>Polymorphism → flexibility.</li></ul>\n<h3>Limitations of OOP (worth being able to list — it signals maturity)</h3>\n<ul><li>Overkill for small problems.</li><li>Without class documentation the code can be hard to follow.</li><li>Longer design time and heavier testing.</li><li>Forces you to think &quot;in objects&quot;, which does not always fit the problem.</li></ul>\n<h2>Class and object</h2>\n<pre><code class=\"language-java\">public class Dog {\n    private String name;   // field = state\n    private int age;\n\n    public Dog(String name, int age) {   // constructor\n        this.name = name;\n        this.age = age;\n    }\n}\n\nDog myDog = new Dog(&quot;Max&quot;, 3);   // object = instance of the class</code></pre>\n<p>Convention: <strong>class names start with a capital letter</strong>.</p>\n<h2>Abstraction</h2>\n<p>You do not want to know <em>how</em> a function works — you want to know <em>that</em> it works.</p>\n<p><strong>Analogy:</strong> a car exposes the brake, clutch, steering wheel and horn to the driver. That is all they need in order to drive. How the injector works is not their problem.</p>\n<p>Two routes in Java:</p>\n<pre><code class=\"language-java\">abstract class Shape {\n    abstract void draw();         // abstract method = no body\n}\nclass Circle extends Shape {\n    @Override void draw() { System.out.println(&quot;Drawing a Circle&quot;); }\n}</code></pre>\n<p>An <strong>abstract method</strong> is declared with no body. If a class has one, it <strong>must</strong> be declared <code>abstract</code>. The converse does <strong>not</strong> hold: an abstract class may contain only concrete methods.</p>\n<p>Benefits: no code duplication, and you can change the internal implementation without touching callers.</p>\n<h3>Abstract class versus interface</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Abstract class</th><th>Interface</th></tr></thead><tbody><tr><td>Keyword</td><td><code>abstract class</code></td><td><code>interface</code></td></tr><tr><td>Multiple inheritance</td><td><strong>no</strong></td><td><strong>yes</strong></td></tr><tr><td>Contents</td><td>abstract <strong>and</strong> concrete methods</td><td>abstract, <code>default</code>, <code>static</code> methods</td></tr><tr><td>State</td><td>may hold instance fields</td><td><code>public static final</code> only</td></tr></tbody></table></div>\n<h2>Encapsulation</h2>\n<p>Grouping fields and methods into one unit, plus <strong>data hiding</strong>: from the outside you cannot reach the state directly — only through a method that can validate the access.</p>\n<pre><code class=\"language-java\">public class Person {\n    private String name;                                   // hidden\n    public String getName() { return name; }               // controlled read\n    public void setName(String name) { this.name = name; } // controlled write\n}</code></pre>\n<ul><li><strong>Upside:</strong> security, easier enhancement, maintainability, modularity.</li><li><strong>Downside (worth mentioning):</strong> more lines of code — getters, setters, validation. Occasionally a performance cost.</li></ul>\n<h3>Abstraction versus encapsulation — the classic question</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Abstraction</th><th>Encapsulation</th></tr></thead><tbody><tr><td>What it hides</td><td>the <strong>implementation</strong> / unwanted detail</td><td>the <strong>data</strong></td></tr><tr><td>By what means</td><td>abstract classes, interfaces</td><td><code>private</code> fields + getters/setters</td></tr><tr><td>Why</td><td>simplify the contract</td><td>protect the state</td></tr></tbody></table></div>\n<h2>Inheritance</h2>\n<p>The <strong>IS-A</strong> relationship: every method and field of the parent is available in the child, <strong>not the other way round</strong>. Keyword <code>extends</code>. In Java, <code>Object</code> is the parent of every class.</p>\n<pre><code class=\"language-java\">class Animal { void eat()  { System.out.println(&quot;This animal eats food&quot;); } }\nclass Dog extends Animal { void bark() { System.out.println(&quot;Dog barks&quot;); } }</code></pre>\n<h3>Five kinds of inheritance</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Kind</th><th>Description</th><th>Java</th></tr></thead><tbody><tr><td>Single</td><td>one class extends one class</td><td>✅</td></tr><tr><td>Multi-level</td><td>A → B → C</td><td>✅</td></tr><tr><td>Hierarchical</td><td>several children, one parent</td><td>✅</td></tr><tr><td>Multiple</td><td>one child, several parents</td><td>❌ for classes, ✅ for interfaces</td></tr><tr><td>Hybrid</td><td>combination of the above</td><td>❌ for classes</td></tr></tbody></table></div>\n<p><strong>Why no multiple class inheritance — the diamond problem:</strong> if two base classes declared a method with the same name, the compiler could not decide which one to pick. Interfaces are safe, because (<code>default</code> aside) they carry only a declaration — the implementing class supplies the body.</p>\n<ul><li><strong>Upside:</strong> code reuse. Common methods in the parent, specific ones in the child.</li><li><strong>Limitation:</strong> <strong>tight coupling</strong> between parent and child. A change in the parent forces changes in the children.</li></ul>\n<h2>Polymorphism</h2>\n<p>One name, many behaviours.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Static (compile time)</th><th>Dynamic (runtime)</th></tr></thead><tbody><tr><td>Mechanism</td><td><strong>overloading</strong></td><td><strong>overriding</strong></td></tr><tr><td>Resolved</td><td>by the compiler</td><td>by the JVM, from the object's type</td></tr><tr><td>Requirement</td><td>a different <strong>signature</strong></td><td>an identical signature</td></tr></tbody></table></div>\n<h3>Overloading</h3>\n<p>Same name, different arguments. Three ways: a different <strong>number</strong> of parameters, a different <strong>type</strong>, a different <strong>order</strong> of types.</p>\n<pre><code class=\"language-java\">class Calculator {\n    int    add(int a, int b)       { return a + b; }\n    double add(double a, double b) { return a + b; }\n}</code></pre>\n<blockquote><p><strong>Note:</strong> differing only in return type is <strong>not enough</strong> to overload.</p></blockquote>\n<h3>Overriding</h3>\n<p>A subclass supplies its own body for a method with an identical signature.</p>\n<pre><code class=\"language-java\">class Parent { void display() { System.out.println(&quot;Parent display&quot;); } }\nclass Child extends Parent {\n    @Override void display() { System.out.println(&quot;Child display&quot;); }\n}</code></pre>\n<p>Rules:</p>\n<ul><li>Parent and child arguments <strong>must be identical</strong>.</li><li><strong><code>private</code>, <code>static</code> and <code>final</code> methods cannot be overridden.</strong></li><li>An abstract superclass method <strong>must</strong> be overridden (unless the subclass is abstract too).</li></ul>\n<h2>Modern OOP — records and sealed classes</h2>\n<h3><code>record</code> (Java 16)</h3>\n<p>An immutable data carrier. The compiler generates the constructor, accessors, <code>toString()</code>, <code>equals()</code> and <code>hashCode()</code>.</p>\n<pre><code class=\"language-java\">public record Employee(String name, int id) { }\n\nEmployee e = new Employee(&quot;Ann&quot;, 7);\ne.name();   // accessor, not getName()</code></pre>\n<h3><code>sealed</code> (Java 17)</h3>\n<p>Restricts who may extend the type.</p>\n<pre><code class=\"language-java\">public sealed class Shape permits Circle, Square { }\n\nfinal      class Circle extends Shape { }\nnon-sealed class Square extends Shape { }</code></pre>\n<p>Benefit: control over the hierarchy plus an <strong>exhaustive <code>switch</code></strong> with no <code>default</code> branch.</p>\n<h2>Java 8 streams and OOP</h2>\n<ul><li><strong>Encapsulation:</strong> a stream encapsulates the data-manipulation logic.</li><li><strong>Polymorphism:</strong> lambdas and functional interfaces let you plug in arbitrary behaviour.</li></ul>\n<pre><code class=\"language-java\">List&lt;String&gt; names = List.of(&quot;Alice&quot;, &quot;Bob&quot;, &quot;Charlie&quot;);\nnames.stream()\n     .filter(name -&gt; name.startsWith(&quot;A&quot;))\n     .forEach(System.out::println);</code></pre>\n<p>Details → <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN\">Java 8 — lambdas, functional interfaces, streams</a>.</p>\n<h2>Interview questions</h2>\n<p><strong>Q: How does abstraction differ from encapsulation?</strong> <strong>A:</strong> Abstraction hides the implementation and exposes only the contract — you achieve it with abstract classes and interfaces. Encapsulation hides data inside one unit — you achieve it with <code>private</code> fields and accessors. The first is about <em>API design</em>, the second about <em>protecting state</em>.</p>\n<p><strong>Q: Why does Java not support multiple class inheritance?</strong> <strong>A:</strong> The diamond problem — with two parents declaring the same method there is no unambiguous resolution. Interfaces are safe because they carry a contract, not state.</p>\n<p><strong>Q: Must an abstract class have an abstract method?</strong> <strong>A:</strong> No. The implication runs one way only: a class with an abstract method must be abstract.</p>\n<p><strong>Q: How does overloading differ from overriding?</strong> <strong>A:</strong> Overloading is the same name with a different signature, resolved at compile time. Overriding is an identical signature in a subclass, resolved at runtime from the object's actual type.</p>\n<p><strong>Q: When a <code>record</code>, when a regular class?</strong> <strong>A:</strong> A <code>record</code> when the object is an <strong>immutable data carrier</strong> with no behaviour — a DTO, a map key, a query result. A regular class when you need mutability, inheritance, or non-trivial logic.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong>Confusing abstraction with encapsulation</strong> — the single most common interview slip.</li><li><strong>Reaching for inheritance instead of composition.</strong> Inheritance binds classes permanently; composition keeps them loose.</li><li><strong>Overloading plus autoboxing</strong> can select a surprising method — <code>remove(int)</code> versus <code>remove(Object)</code> on <code>List</code>.</li><li><strong><code>static</code> methods are hidden, not overridden</strong> — the call resolves from the reference type, not the object type.</li><li><strong>Fields are not polymorphic</strong> — field access resolves from the reference type.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_EN\">Type system and language building blocks</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_EN\">Java 8 — lambdas, functional interfaces, streams</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_EN\">Collections Framework — cheatsheet</a> · <a href=\"#/Java/Language_Fundamentals/OOP_Concepts_PL\">Koncepcje obiektowe — dziedziczenie, abstrakcja, polimorfizm</a></p>"},"Java/Language_Fundamentals/OOP_Concepts_PL":{"title":"Koncepcje obiektowe — dziedziczenie, abstrakcja, polimorfizm","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","oop","inheritance","polymorphism","encapsulation","abstraction","interview"],"minutes":7,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>Cztery filary OOP: <strong>enkapsulacja, abstrakcja, dziedziczenie, polimorfizm</strong>.</li><li><strong>Abstrakcja</strong> ukrywa <em>implementację</em>; <strong>enkapsulacja</strong> ukrywa <em>dane</em>. To nie to samo pytanie i nie ta sama odpowiedź.</li><li>Java <strong>nie wspiera wielodziedziczenia klas</strong> — problem diamentu. Wspiera wielodziedziczenie interfejsów.</li><li>Polimorfizm statyczny = <strong>przeciążanie</strong> (kompilacja). Polimorfizm dynamiczny = <strong>nadpisywanie</strong> (runtime).</li><li><code>record</code> (Java 16) i <code>sealed</code> (Java 17) to nowoczesne narzędzia modelowania — pytane coraz częściej.</li></ul></blockquote>\n<h2>Model mentalny</h2>\n<p><strong>Klasa to projekt budynku, obiekt to konkretny budynek.</strong> Projekt mówi, jakie są pokoje (pola) i co można w nich zrobić (metody). Z jednego projektu stawiasz wiele budynków — każdy z własnym stanem.</p>\n<p>Gdzie analogia się rozjeżdża: budynek nie może „odziedziczyć&quot; po innym budynku i dopisać sobie piętra. Klasa może.</p>\n<h2>Kluczowe pojęcia</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Pojęcie</th><th>Definicja</th><th>Jak osiągasz</th></tr></thead><tbody><tr><td><strong>Enkapsulacja</strong></td><td>Związanie danych i operujących na nich metod w jedną jednostkę + ukrycie danych</td><td>pola <code>private</code> + gettery/settery z walidacją</td></tr><tr><td><strong>Abstrakcja</strong></td><td>Pokazanie <em>co</em> robi komponent, ukrycie <em>jak</em></td><td><code>abstract class</code>, <code>interface</code></td></tr><tr><td><strong>Dziedziczenie</strong></td><td>Relacja <strong>IS-A</strong>: dziecko ma wszystko, co rodzic (nie odwrotnie)</td><td><code>extends</code></td></tr><tr><td><strong>Polimorfizm</strong></td><td>Jedna nazwa, wiele zachowań</td><td>przeciążanie + nadpisywanie</td></tr></tbody></table></div>\n<h3>Po co w ogóle OOP</h3>\n<ul><li>Łatwiejszy rozwój i utrzymanie projektu.</li><li><strong>Ukrywanie danych</strong> → bezpieczeństwo.</li><li>Modelowanie bytów ze świata rzeczywistego.</li><li><strong>Reużycie kodu</strong> przez dziedziczenie → mniej duplikacji.</li><li>Polimorfizm → elastyczność.</li></ul>\n<h3>Ograniczenia OOP (warto umieć wymienić — pokazuje dojrzałość)</h3>\n<ul><li>Przerost formy nad treścią przy małych problemach.</li><li>Bez dokumentacji klas kod bywa trudny do zrozumienia.</li><li>Dłuższy czas projektowania i intensywniejsze testowanie.</li><li>Wymaga myślenia „w obiektach&quot;, co nie zawsze pasuje do problemu.</li></ul>\n<h2>Klasa i obiekt</h2>\n<pre><code class=\"language-java\">public class Dog {\n    private String name;   // pole = stan\n    private int age;\n\n    public Dog(String name, int age) {   // konstruktor\n        this.name = name;\n        this.age = age;\n    }\n}\n\nDog myDog = new Dog(&quot;Max&quot;, 3);   // obiekt = instancja klasy</code></pre>\n<p>Konwencja: <strong>nazwa klasy zaczyna się wielką literą</strong>.</p>\n<h2>Abstrakcja</h2>\n<p>Nie chcesz wiedzieć, <em>jak</em> funkcja działa — chcesz wiedzieć, <em>że</em> działa.</p>\n<p><strong>Analogia:</strong> samochód pokazuje kierowcy hamulec, sprzęgło, kierownicę i klakson. To wszystko, czego potrzebuje do jazdy. Jak działa wtryskiwacz — nie jego problem.</p>\n<p>Dwie drogi w Javie:</p>\n<pre><code class=\"language-java\">abstract class Shape {\n    abstract void draw();         // metoda abstrakcyjna = bez ciała\n}\nclass Circle extends Shape {\n    @Override void draw() { System.out.println(&quot;Drawing a Circle&quot;); }\n}</code></pre>\n<p><strong>Metoda abstrakcyjna</strong> = zadeklarowana bez ciała. Jeśli klasa ma metodę abstrakcyjną, <strong>musi</strong> być zadeklarowana jako <code>abstract</code>. Odwrotnie <strong>nie</strong>: klasa abstrakcyjna może zawierać wyłącznie metody konkretne.</p>\n<p>Korzyści: brak duplikacji kodu, możliwość zmiany implementacji wewnętrznej bez ruszania klientów.</p>\n<h3>Klasa abstrakcyjna kontra interfejs</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Klasa abstrakcyjna</th><th>Interfejs</th></tr></thead><tbody><tr><td>Słowo kluczowe</td><td><code>abstract class</code></td><td><code>interface</code></td></tr><tr><td>Wielodziedziczenie</td><td><strong>nie</strong></td><td><strong>tak</strong></td></tr><tr><td>Zawartość</td><td>metody abstrakcyjne <strong>i</strong> konkretne</td><td>metody abstrakcyjne, <code>default</code>, <code>static</code></td></tr><tr><td>Stan</td><td>może mieć pola instancji</td><td>tylko <code>public static final</code></td></tr></tbody></table></div>\n<h2>Enkapsulacja</h2>\n<p>Grupowanie pól i metod w jedną jednostkę, plus <strong>ukrycie danych</strong>: z zewnątrz nie dobierzesz się do stanu bezpośrednio — dopiero po przejściu przez metodę, która może zwalidować dostęp.</p>\n<pre><code class=\"language-java\">public class Person {\n    private String name;                                   // ukryte\n    public String getName() { return name; }               // kontrolowany odczyt\n    public void setName(String name) { this.name = name; } // kontrolowany zapis\n}</code></pre>\n<ul><li><strong>Zaleta:</strong> bezpieczeństwo, łatwiejsze rozszerzanie, utrzymywalność, modularność.</li><li><strong>Wada (warto wspomnieć):</strong> więcej linii kodu — gettery, settery, walidacja. Czasem koszt wydajnościowy.</li></ul>\n<h3>Abstrakcja kontra enkapsulacja — klasyczne pytanie</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Abstrakcja</th><th>Enkapsulacja</th></tr></thead><tbody><tr><td>Co ukrywa</td><td><strong>implementację</strong> / zbędne szczegóły</td><td><strong>dane</strong></td></tr><tr><td>Czym</td><td>klasy abstrakcyjne, interfejsy</td><td>pola <code>private</code> + gettery/settery</td></tr><tr><td>Po co</td><td>uproszczenie kontraktu</td><td>ochrona stanu</td></tr></tbody></table></div>\n<h2>Dziedziczenie</h2>\n<p>Relacja <strong>IS-A</strong>: wszystkie metody i pola rodzica są dostępne w dziecku, <strong>nie odwrotnie</strong>. Słowo kluczowe <code>extends</code>. W Javie <code>Object</code> jest rodzicem wszystkich klas.</p>\n<pre><code class=\"language-java\">class Animal { void eat()  { System.out.println(&quot;This animal eats food&quot;); } }\nclass Dog extends Animal { void bark() { System.out.println(&quot;Dog barks&quot;); } }</code></pre>\n<h3>Pięć typów dziedziczenia</h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Typ</th><th>Opis</th><th>Java</th></tr></thead><tbody><tr><td>Pojedyncze</td><td>jedna klasa dziedziczy po jednej</td><td>✅</td></tr><tr><td>Wielopoziomowe</td><td>A → B → C</td><td>✅</td></tr><tr><td>Hierarchiczne</td><td>wiele dzieci po jednym rodzicu</td><td>✅</td></tr><tr><td>Wielokrotne</td><td>jedno dziecko po wielu rodzicach</td><td>❌ dla klas, ✅ dla interfejsów</td></tr><tr><td>Hybrydowe</td><td>kombinacja powyższych</td><td>❌ dla klas</td></tr></tbody></table></div>\n<p><strong>Dlaczego brak wielodziedziczenia klas — problem diamentu:</strong> gdyby dwie klasy bazowe miały metodę o tej samej nazwie, kompilator nie wiedziałby, którą wybrać. W interfejsach problemu nie ma, bo (poza <code>default</code>) niosą samą deklarację — implementację daje klasa.</p>\n<ul><li><strong>Zaleta:</strong> reużycie kodu. Wspólne metody w rodzicu, specyficzne w dziecku.</li><li><strong>Ograniczenie:</strong> <strong>ciasne sprzężenie</strong> rodzica z dzieckiem. Zmiana w rodzicu wymusza zmiany w dzieciach.</li></ul>\n<h2>Polimorfizm</h2>\n<p>Jedna nazwa, wiele zachowań.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Statyczny (kompilacja)</th><th>Dynamiczny (runtime)</th></tr></thead><tbody><tr><td>Mechanizm</td><td><strong>przeciążanie</strong> (<code>overloading</code>)</td><td><strong>nadpisywanie</strong> (<code>overriding</code>)</td></tr><tr><td>Kiedy rozstrzygane</td><td>przez kompilator</td><td>przez JVM, po typie obiektu</td></tr><tr><td>Warunek</td><td>różna <strong>sygnatura</strong></td><td>identyczna sygnatura</td></tr></tbody></table></div>\n<h3>Przeciążanie</h3>\n<p>Ta sama nazwa, inne argumenty. Trzy sposoby: inna <strong>liczba</strong> parametrów, inny <strong>typ</strong>, inna <strong>kolejność</strong> typów.</p>\n<pre><code class=\"language-java\">class Calculator {\n    int    add(int a, int b)       { return a + b; }\n    double add(double a, double b) { return a + b; }\n}</code></pre>\n<blockquote><p><strong>Uwaga:</strong> sama różnica w typie zwracanym <strong>nie wystarcza</strong> do przeciążenia.</p></blockquote>\n<h3>Nadpisywanie</h3>\n<p>Podklasa dostarcza własną implementację metody o identycznej sygnaturze.</p>\n<pre><code class=\"language-java\">class Parent { void display() { System.out.println(&quot;Parent display&quot;); } }\nclass Child extends Parent {\n    @Override void display() { System.out.println(&quot;Child display&quot;); }\n}</code></pre>\n<p>Zasady:</p>\n<ul><li>Argumenty rodzica i dziecka <strong>muszą być identyczne</strong>.</li><li><strong><code>private</code>, <code>static</code> i <code>final</code> nie da się nadpisać.</strong></li><li>Metoda abstrakcyjna nadklasy <strong>musi</strong> zostać nadpisana (chyba że podklasa też jest abstrakcyjna).</li></ul>\n<h2>Nowoczesne OOP — rekordy i klasy sealed</h2>\n<h3><code>record</code> (Java 16)</h3>\n<p>Niemutowalny nośnik danych. Kompilator sam generuje konstruktor, akcesory, <code>toString()</code>, <code>equals()</code>, <code>hashCode()</code>.</p>\n<pre><code class=\"language-java\">public record Employee(String name, int id) { }\n\nEmployee e = new Employee(&quot;Ann&quot;, 7);\ne.name();   // akcesor, nie getName()</code></pre>\n<h3><code>sealed</code> (Java 17)</h3>\n<p>Ogranicza, kto może rozszerzać typ.</p>\n<pre><code class=\"language-java\">public sealed class Shape permits Circle, Square { }\n\nfinal      class Circle extends Shape { }\nnon-sealed class Square extends Shape { }</code></pre>\n<p>Korzyść: kontrola nad hierarchią + <strong>wyczerpujący <code>switch</code></strong> bez gałęzi <code>default</code>.</p>\n<h2>Strumienie Java 8 a OOP</h2>\n<ul><li><strong>Enkapsulacja:</strong> strumień zamyka logikę przetwarzania danych.</li><li><strong>Polimorfizm:</strong> lambdy i interfejsy funkcyjne pozwalają podstawić dowolne zachowanie.</li></ul>\n<pre><code class=\"language-java\">List&lt;String&gt; names = List.of(&quot;Alice&quot;, &quot;Bob&quot;, &quot;Charlie&quot;);\nnames.stream()\n     .filter(name -&gt; name.startsWith(&quot;A&quot;))\n     .forEach(System.out::println);</code></pre>\n<p>Szczegóły → <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL\">Java 8 — lambdy, interfejsy funkcyjne, strumienie</a>.</p>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Czym różni się abstrakcja od enkapsulacji?</strong> <strong>O:</strong> Abstrakcja ukrywa implementację i pokazuje tylko kontrakt — realizujesz ją klasami abstrakcyjnymi i interfejsami. Enkapsulacja ukrywa dane w jednej jednostce — realizujesz ją polami <code>private</code> i akcesorami. Pierwsza dotyczy <em>projektu API</em>, druga <em>ochrony stanu</em>.</p>\n<p><strong>P: Dlaczego Java nie wspiera wielodziedziczenia klas?</strong> <strong>O:</strong> Problem diamentu — przy dwóch rodzicach z metodą o tej samej nazwie nie da się jednoznacznie rozstrzygnąć, którą wywołać. Interfejsy są bezpieczne, bo niosą kontrakt, a nie stan.</p>\n<p><strong>P: Czy klasa abstrakcyjna musi mieć metodę abstrakcyjną?</strong> <strong>O:</strong> Nie. Implikacja idzie tylko w jedną stronę: klasa z metodą abstrakcyjną musi być abstrakcyjna.</p>\n<p><strong>P: Czym przeciążanie różni się od nadpisywania?</strong> <strong>O:</strong> Przeciążanie to ta sama nazwa z inną sygnaturą, rozstrzygane w czasie kompilacji. Nadpisywanie to identyczna sygnatura w podklasie, rozstrzygane w czasie wykonania po rzeczywistym typie obiektu.</p>\n<p><strong>P: Kiedy <code>record</code>, a kiedy zwykła klasa?</strong> <strong>O:</strong> <code>record</code> gdy obiekt jest <strong>niemutowalnym nośnikiem danych</strong> bez zachowania — DTO, klucz mapy, wynik zapytania. Zwykła klasa, gdy potrzebujesz mutowalności, dziedziczenia albo nietrywialnej logiki.</p>\n<h2>Pułapki</h2>\n<ul><li><strong>Mylenie abstrakcji z enkapsulacją</strong> — najczęstszy błąd na rozmowie.</li><li><strong>Nadużywanie dziedziczenia</strong> zamiast kompozycji. Dziedziczenie wiąże klasy na stałe; kompozycja zostawia luz.</li><li><strong>Przeciążanie z autoboxingiem</strong> potrafi wybrać zaskakującą metodę — <code>remove(int)</code> kontra <code>remove(Object)</code> w <code>List</code>.</li><li><strong><code>static</code> nie nadpisujesz, tylko przesłaniasz</strong> (<em>hiding</em>) — wywołanie idzie po typie referencji, nie po typie obiektu.</li><li><strong>Pola nie są polimorficzne</strong> — dostęp do pola rozstrzyga się po typie referencji.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_PL\">System typów i podstawowe konstrukcje języka</a> · <a href=\"#/Java/Language_Fundamentals/Java_8_Lambdas_Streams_Functional_Interfaces_PL\">Java 8 — lambdy, interfejsy funkcyjne, strumienie</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_PL\">Collections Framework — ściągawka</a> · <a href=\"#/Java/Language_Fundamentals/OOP_Concepts_EN\">OOP concepts — inheritance, abstraction, polymorphism</a></p>"},"Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_EN":{"title":"Type system and language building blocks","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","types","object","primitives","autoboxing","equals","switch","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>Java has a <strong>dual type system</strong>: reference types inherit from <code>Object</code>, the <strong>eight primitive types inherit from nothing</strong>.</li><li><strong>Arrays are objects</strong> — per the language specification, even <code>int[]</code>.</li><li>An interface does <strong>not extend</strong> <code>Object</code>, but the specification treats interface types as its subtypes — which is why <code>toString()</code> works on an interface reference.</li><li><code>==</code> compares <strong>identity</strong>, <code>equals()</code> compares <strong>value</strong>, provided someone overrode it.</li><li>Primitives are passed <strong>by value via the stack</strong> — a change inside a method does not escape it.</li></ul></blockquote>\n<h2>The type hierarchy</h2>\n<p><code>java.lang.Object</code> is the root of the class hierarchy. The rule: <strong>every class has <code>Object</code> as a superclass</strong>. If a class does not explicitly extend another, the compiler <strong>implicitly adds <code>extends Object</code></strong>.</p>\n<p>Consequence: a variable of type <code>Object</code> can hold a reference to an instance of <strong>any</strong> reference type.</p>\n<h3>What inherits from <code>Object</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Category</th><th>Example</th><th>Note</th></tr></thead><tbody><tr><td>User classes</td><td><code>public class MyClass {}</code></td><td></td></tr><tr><td>Library classes</td><td><code>String</code>, <code>Integer</code>, <code>ArrayList</code></td><td></td></tr><tr><td><strong>Arrays</strong></td><td><code>int[]</code>, <code>String[]</code></td><td><strong>including primitive arrays</strong> — they are objects per the spec</td></tr><tr><td>Enums</td><td><code>enum Color { RED, BLUE }</code></td><td>implicitly extend <code>java.lang.Enum</code></td></tr><tr><td>Records</td><td><code>record Point(int x, int y)</code></td><td>implicitly extend <code>java.lang.Record</code></td></tr><tr><td>Interfaces</td><td><code>interface Comparable</code></td><td><strong>nuance</strong> — an interface cannot extend a class, but the JLS treats interface types as subtypes of <code>Object</code></td></tr></tbody></table></div>\n<blockquote><p><strong>Trick question:</strong> <em>&quot;Do arrays inherit from <code>Object</code>?&quot;</em> Yes. They can be assigned to an <code>Object</code> reference and every <code>Object</code> method can be called on them.</p></blockquote>\n<h3>What does NOT — the eight primitive types</h3>\n<p>Java is <strong>not purely object-oriented</strong> (unlike Smalltalk or Ruby). Primitives are raw data: no methods, no object header.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Type</th><th>Size</th><th>Note</th></tr></thead><tbody><tr><td><code>boolean</code></td><td><strong>not defined by the JVM specification</strong></td><td>may vary between implementations</td></tr><tr><td><code>byte</code></td><td>8-bit, signed</td><td></td></tr><tr><td><code>short</code></td><td>16-bit, signed</td><td></td></tr><tr><td><code>char</code></td><td>16-bit, <strong>unsigned</strong></td><td></td></tr><tr><td><code>int</code></td><td>32-bit, signed</td><td></td></tr><tr><td><code>long</code></td><td>64-bit, signed</td><td></td></tr><tr><td><code>float</code></td><td>32-bit, IEEE 754</td><td></td></tr><tr><td><code>double</code></td><td>64-bit, IEEE 754</td><td></td></tr></tbody></table></div>\n<h3>Primitives versus reference types</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Primitive</th><th>Reference</th></tr></thead><tbody><tr><td>Inheritance</td><td>none, cannot be subclassed</td><td>from <code>Object</code>, themselves inheritable (unless <code>final</code>)</td></tr><tr><td>Passing</td><td><strong>always by value, via the stack</strong></td><td>the reference is passed by value</td></tr><tr><td>Effect</td><td>a change inside a method <strong>does not propagate</strong> to the argument</td><td>mutations of the object's state are visible outside</td></tr></tbody></table></div>\n<h2>Wrapper classes and autoboxing</h2>\n<p>Each of the eight primitives has a wrapper: <code>Boolean</code>, <code>Byte</code>, <code>Short</code>, <code>Character</code>, <code>Integer</code>, <code>Float</code>, <code>Long</code>, <code>Double</code>. <strong>Wrappers inherit from <code>Object</code></strong> — they are the bridge between the two worlds.</p>\n<p>They matter when a primitive value has to go into a generic collection, which only accepts reference types.</p>\n<pre><code class=\"language-java\">// explicit — before autoboxing\nList&lt;Integer&gt; list = new ArrayList&lt;&gt;();\nlist.add(Integer.valueOf(5));\n\n// with autoboxing — the compiler converts automatically\nList&lt;Integer&gt; list2 = new ArrayList&lt;&gt;();\nlist2.add(5);              // autoboxing     int → Integer\nint value = list2.get(0);  // auto-unboxing  Integer → int</code></pre>\n<h2><code>equals()</code> versus <code>==</code></h2>\n<pre><code class=\"language-java\">String a = new String(&quot;Hello&quot;);\nString b = new String(&quot;Hello&quot;);\n\na == b;        // false — new ALWAYS creates a new object\na.equals(b);   // true  — String compares character content\n\nint i1 = 5, i2 = 5;\ni1 == i2;      // true — for primitives == compares values</code></pre>\n<div class=\"table-wrap\"><table><thead><tr><th>Operator</th><th>What it compares</th></tr></thead><tbody><tr><td><code>==</code></td><td><strong>identity</strong> — whether both variables point at the same object in memory; for primitives, the value</td></tr><tr><td><code>equals()</code></td><td>defined on <code>Object</code>, so available everywhere. By default it falls back to <code>==</code>, but it is <strong>usually overridden</strong> to express comparison semantics for the class</td></tr></tbody></table></div>\n<h2>Checking a type when the class is unknown at compile time</h2>\n<p><code>instanceof</code> requires a <strong>literal class name</strong>, so it is useless when all you have is a <code>Class</code> object:</p>\n<pre><code class=\"language-java\">Class&lt;?&gt; integerClass = Integer.valueOf(5).getClass();\nintegerClass.isInstance(Integer.valueOf(4));   // true</code></pre>\n<h2>Abstract class versus interface</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Abstract class</th><th>Interface</th></tr></thead><tbody><tr><td>Count</td><td>you can extend <strong>one</strong></td><td>you can implement <strong>many</strong></td></tr><tr><td>Role</td><td>base type of a hierarchy; expresses the <strong>main intention</strong> of its subclasses</td><td>a <strong>contract</strong> the class agrees to</td></tr><tr><td>Implementation</td><td>can supply methods shared by subclasses</td><td><code>default</code> methods since Java 8</td></tr><tr><td>Example</td><td><code>AbstractMap</code> implements <code>equals()</code> and others on behalf of subclasses</td><td><code>Comparable</code> means &quot;these instances can be compared&quot;, whatever the class is mainly for</td></tr></tbody></table></div>\n<h3>Restrictions on interface members</h3>\n<ul><li>Fields are <strong>implicitly <code>public static final</code></strong> — constants only. <strong>You cannot declare a private field or any instance state.</strong></li><li>Methods are implicitly <code>public</code>, and either (implicitly) <code>abstract</code> or <code>default</code>.</li></ul>\n<h3>Does Java have multiple inheritance?</h3>\n<p><strong>Not for classes</strong> — a class inherits from a single superclass. But it can implement many interfaces, some of whose methods may carry a <code>default</code> implementation. That is a <strong>safer way of mixing functionality</strong> than class multiple inheritance.</p>\n<h2>Nested classes</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Inner class</th><th>Static nested class</th></tr></thead><tbody><tr><td>Binding</td><td><strong>every instance is bound to an instance of the enclosing class</strong></td><td>independent</td></tr><tr><td>Creation</td><td>requires an outer instance</td><td>like any other class</td></tr><tr><td>Risk</td><td>implicit reference to the outer object → <strong>potential memory leak</strong></td><td>none</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">// inner — needs an outer instance\npublic class OuterClass1 {\n    public class InnerClass {\n        public OuterClass1 getOuterInstance() {\n            return OuterClass1.this;      // access to the outer object\n        }\n    }\n}\nOuterClass1 outer = new OuterClass1();\nOuterClass1.InnerClass inner = outer.new InnerClass();\n\n// static nested — independent\npublic class OuterClass2 {\n    public static class StaticNestedClass { }\n}\nOuterClass2.StaticNestedClass nested = new OuterClass2.StaticNestedClass();</code></pre>\n<blockquote><p>That implicit inner-to-outer reference is one of the classic causes of memory leaks → <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_EN\">Memory management and garbage collection</a>.</p></blockquote>\n<h2>Anonymous classes</h2>\n<p>A one-shot class defined exactly where its instance is needed — so it needs no name.</p>\n<p>Before Java 8 they were mostly used to implement single-method interfaces (<code>Runnable</code>). <strong>Lambdas replaced that</strong>, but anonymous classes still earn their place when you need an instance of an interface with <strong>several</strong> methods, or a class with extra behaviour.</p>\n<pre><code class=\"language-java\">// double-brace initialisation — neat-looking, creates an anonymous subclass\nMap&lt;String, Integer&gt; ages = new HashMap&lt;String, Integer&gt;() {{\n    put(&quot;David&quot;, 30);\n    put(&quot;John&quot;, 25);\n}};</code></pre>\n<blockquote><p><strong>Caution:</strong> the idiom above creates an anonymous <code>HashMap</code> subclass holding a reference to the enclosing class. It looks tidy and is a known source of leaks and serialization problems. In new code: <code>Map.of(...)</code>.</p></blockquote>\n<h2>Flow control</h2>\n<h3><code>if</code> / <code>if-else</code></h3>\n<p><strong>Java accepts only <code>boolean</code> expressions</strong> as conditions. Anything else is a compile error — unlike languages where <code>if (0)</code> is meaningful.</p>\n<h3><code>switch</code></h3>\n<p>Permitted selector types: <code>byte</code>, <code>short</code>, <code>char</code>, <code>int</code>, their wrappers, <strong>enums</strong> and <strong><code>String</code></strong>.</p>\n<p><strong>Fall-through</strong> — a missing <code>break</code> executes every subsequent branch until the first <code>break</code>, <strong>regardless of whether the labels match</strong>:</p>\n<pre><code class=\"language-java\">int operation = 2;\nint number = 10;\n\nswitch (operation) {\n    case 1: number = number + 10; break;\n    case 2: number = number - 4;      // ← no break\n    case 3: number = number / 3;      // ← runs despite not matching\n    case 4: number = number * 10; break;\n}\n// number == 20, not 6</code></pre>\n<p>Sometimes that is <strong>deliberate</strong> — when several values should trigger the same action:</p>\n<pre><code class=\"language-java\">switch (month) {\n    case 1: case 3: case 5: case 7: case 8: case 10: case 12:\n        days = 31;\n        break;\n    // ...\n}</code></pre>\n<p><strong>When <code>switch</code>, when <code>if-else</code>:</strong> <code>switch</code> wins for testing <strong>one variable</strong> against many single values, or when several values run the same code. <code>if-else</code> wins for compound conditions, different variables, or ranges.</p>\n<h3>Loops and labels</h3>\n<p>Java supports <code>for</code>, <code>while</code>, <code>do-while</code> and the <strong>enhanced for</strong> (<code>for-each</code>) over arrays and <code>Iterable</code>.</p>\n<p>Early exit: <code>break</code> (leaves the loop), <code>continue</code> (next iteration), <code>return</code>.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Unlabeled</th><th>Labeled</th></tr></thead><tbody><tr><td><code>break</code></td><td>leaves the <strong>nearest</strong> loop</td><td>leaves the <strong>named</strong> loop, including an outer one</td></tr><tr><td><code>continue</code></td><td>next iteration of the nearest loop</td><td>next iteration of the <strong>named</strong> loop</td></tr></tbody></table></div>\n<h3><code>try-catch-finally</code></h3>\n<p>Details, including the cases where <code>finally</code> <strong>does not run</strong>, plus <code>try-with-resources</code> → <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_EN\">Exception handling and I/O operations</a>.</p>\n<h2>Interview questions</h2>\n<p><strong>Q: Is everything an object in Java?</strong> <strong>A:</strong> No. The eight primitive types are raw data with no methods and no headers. Java has a dual type system, and wrappers bridge the two.</p>\n<p><strong>Q: Does an array inherit from <code>Object</code>?</strong> <strong>A:</strong> Yes, including a primitive array. The specification treats arrays as objects.</p>\n<p><strong>Q: How does <code>==</code> differ from <code>equals()</code>?</strong> <strong>A:</strong> <code>==</code> checks reference identity (value equality for primitives); <code>equals()</code> checks logical equality, if the class overrode it. <code>new</code> always produces an object that fails <code>==</code>.</p>\n<p><strong>Q: When an abstract class, when an interface?</strong> <strong>A:</strong> Abstract class when modelling a hierarchy and sharing implementation. Interface when defining a contract that classes with different purposes can satisfy — and when you need several such contracts at once.</p>\n<p><strong>Q: Why can an inner class cause a memory leak?</strong> <strong>A:</strong> Because it holds an implicit reference to the enclosing instance. If the inner object outlives the outer one, it blocks its collection.</p>\n<h2>Pitfalls</h2>\n<ul><li><strong><code>boolean</code> has no specified size</strong> in the JVM specification — do not assume one bit.</li><li><strong><code>char</code> is unsigned</strong>, uniquely among the integral types.</li><li><strong>Autoboxing in a loop</strong> creates thousands of <code>Integer</code> objects — a cost that is easy to miss.</li><li><strong><code>==</code> on wrappers</strong> works &quot;by accident&quot; for small values thanks to the <code>Integer</code> cache (−128…127) and fails above it. Never compare wrappers with <code>==</code>.</li><li><strong><code>switch</code> fall-through is the default and is silent.</strong> The modern arrow syntax (<code>-&gt;</code>) removes it.</li></ul>\n<h2>Related</h2>\n<p><a href=\"#/Java/Language_Fundamentals/OOP_Concepts_EN\">OOP concepts — inheritance, abstraction, polymorphism</a> · <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_EN\">Exception handling and I/O operations</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_EN\">Collections Framework — cheatsheet</a> · <a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_PL\">System typów i podstawowe konstrukcje języka</a></p>"},"Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_PL":{"title":"System typów i podstawowe konstrukcje języka","category":"Java/Language_Fundamentals","date":"2026-11-04","tags":["java","typy","object","primitives","autoboxing","equals","switch","interview"],"minutes":8,"lead":"","html":"<blockquote><p><strong>TL;DR</strong></p><ul><li>Java ma <strong>dualny system typów</strong>: typy referencyjne dziedziczą po <code>Object</code>, <strong>osiem typów prymitywnych nie dziedziczy po niczym</strong>.</li><li><strong>Tablice są obiektami</strong> — zgodnie ze specyfikacją języka, mimo że <code>int[]</code> zawiera prymitywy.</li><li>Interfejs <strong>nie rozszerza</strong> <code>Object</code>, ale specyfikacja traktuje typy interfejsowe jako jego podtypy — dlatego <code>toString()</code> działa na referencji do interfejsu.</li><li><code>==</code> porównuje <strong>tożsamość</strong>, <code>equals()</code> — <strong>wartość</strong>, o ile ktoś ją nadpisał.</li><li>Prymitywy są przekazywane <strong>przez wartość przez stos</strong> — zmiana wewnątrz metody nie wychodzi na zewnątrz.</li></ul></blockquote>\n<h2>Hierarchia typów</h2>\n<p><code>java.lang.Object</code> jest korzeniem hierarchii klas. Reguła: <strong>każda klasa ma <code>Object</code> jako nadklasę</strong>. Jeśli klasa nie rozszerza jawnie innej, kompilator <strong>domyślnie dopisuje <code>extends Object</code></strong>.</p>\n<p>Konsekwencja: zmienna typu <code>Object</code> może trzymać referencję do instancji <strong>dowolnego</strong> typu referencyjnego.</p>\n<h3>Co dziedziczy po <code>Object</code></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Kategoria</th><th>Przykład</th><th>Uwaga</th></tr></thead><tbody><tr><td>Klasy użytkownika</td><td><code>public class MyClass {}</code></td><td></td></tr><tr><td>Klasy biblioteczne</td><td><code>String</code>, <code>Integer</code>, <code>ArrayList</code></td><td></td></tr><tr><td><strong>Tablice</strong></td><td><code>int[]</code>, <code>String[]</code></td><td><strong>również tablice prymitywów</strong> — są obiektami wg specyfikacji</td></tr><tr><td>Enumy</td><td><code>enum Color { RED, BLUE }</code></td><td>niejawnie rozszerzają <code>java.lang.Enum</code></td></tr><tr><td>Rekordy</td><td><code>record Point(int x, int y)</code></td><td>niejawnie rozszerzają <code>java.lang.Record</code></td></tr><tr><td>Interfejsy</td><td><code>interface Comparable</code></td><td><strong>niuans</strong> — interfejs nie może rozszerzać klasy, ale JLS traktuje typy interfejsowe jako podtypy <code>Object</code></td></tr></tbody></table></div>\n<blockquote><p><strong>Pytanie-pułapka:</strong> <em>„Czy tablice dziedziczą po <code>Object</code>?&quot;</em> Tak. Można je przypisać do referencji <code>Object</code> i wywołać na nich każdą metodę <code>Object</code>.</p></blockquote>\n<h3>Co NIE dziedziczy — osiem typów prymitywnych</h3>\n<p>Java <strong>nie jest czysto obiektowa</strong> (w odróżnieniu od Smalltalka czy Ruby). Prymitywy to surowe dane: bez metod, bez nagłówka obiektu.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Typ</th><th>Rozmiar</th><th>Uwaga</th></tr></thead><tbody><tr><td><code>boolean</code></td><td><strong>niezdefiniowany przez specyfikację JVM</strong></td><td>może się różnić między implementacjami</td></tr><tr><td><code>byte</code></td><td>8 bitów, ze znakiem</td><td></td></tr><tr><td><code>short</code></td><td>16 bitów, ze znakiem</td><td></td></tr><tr><td><code>char</code></td><td>16 bitów, <strong>bez znaku</strong></td><td></td></tr><tr><td><code>int</code></td><td>32 bity, ze znakiem</td><td></td></tr><tr><td><code>long</code></td><td>64 bity, ze znakiem</td><td></td></tr><tr><td><code>float</code></td><td>32 bity, IEEE 754</td><td></td></tr><tr><td><code>double</code></td><td>64 bity, IEEE 754</td><td></td></tr></tbody></table></div>\n<h3>Prymitywy kontra typy referencyjne</h3>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Prymitywne</th><th>Referencyjne</th></tr></thead><tbody><tr><td>Dziedziczenie</td><td>brak, nie można dziedziczyć</td><td>po <code>Object</code>, same też dziedziczalne (poza <code>final</code>)</td></tr><tr><td>Przekazywanie</td><td><strong>zawsze przez wartość, przez stos</strong></td><td>przez wartość referencji</td></tr><tr><td>Skutek</td><td>zmiana wewnątrz metody <strong>nie propaguje</strong> na argument</td><td>zmiana stanu obiektu jest widoczna na zewnątrz</td></tr></tbody></table></div>\n<h2>Klasy opakowujące i autoboxing</h2>\n<p>Dla każdego z ośmiu prymitywów istnieje wrapper: <code>Boolean</code>, <code>Byte</code>, <code>Short</code>, <code>Character</code>, <code>Integer</code>, <code>Float</code>, <code>Long</code>, <code>Double</code>. <strong>Wrappery dziedziczą po <code>Object</code></strong> — to one są mostem między dwoma światami.</p>\n<p>Przydają się, gdy trzeba włożyć wartość prymitywną do kolekcji generycznej, która przyjmuje wyłącznie typy referencyjne.</p>\n<pre><code class=\"language-java\">// jawnie — przed autoboxingiem\nList&lt;Integer&gt; list = new ArrayList&lt;&gt;();\nlist.add(Integer.valueOf(5));\n\n// z autoboxingiem — kompilator konwertuje automatycznie\nList&lt;Integer&gt; list2 = new ArrayList&lt;&gt;();\nlist2.add(5);          // autoboxing   int → Integer\nint value = list2.get(0);  // auto-unboxing Integer → int</code></pre>\n<h2><code>equals()</code> kontra <code>==</code></h2>\n<pre><code class=\"language-java\">String a = new String(&quot;Hello&quot;);\nString b = new String(&quot;Hello&quot;);\n\na == b;        // false — new ZAWSZE tworzy nowy obiekt\na.equals(b);   // true  — String porównuje zawartość znaków\n\nint i1 = 5, i2 = 5;\ni1 == i2;      // true — dla prymitywów == porównuje wartości</code></pre>\n<div class=\"table-wrap\"><table><thead><tr><th>Operator</th><th>Co porównuje</th></tr></thead><tbody><tr><td><code>==</code></td><td><strong>tożsamość</strong> — czy obie zmienne wskazują ten sam obiekt w pamięci; dla prymitywów: wartość</td></tr><tr><td><code>equals()</code></td><td>zdefiniowane w <code>Object</code>, więc dostępne wszędzie. Domyślnie sprowadza się do <code>==</code>, ale <strong>zwykle jest nadpisywane</strong>, by dać semantykę porównania właściwą dla klasy</td></tr></tbody></table></div>\n<h2>Sprawdzanie typu, gdy klasa nie jest znana w czasie kompilacji</h2>\n<p><code>instanceof</code> wymaga <strong>literalnej nazwy klasy</strong>, więc nie zadziała, gdy masz tylko obiekt <code>Class</code>:</p>\n<pre><code class=\"language-java\">Class&lt;?&gt; integerClass = Integer.valueOf(5).getClass();\nintegerClass.isInstance(Integer.valueOf(4));   // true</code></pre>\n<h2>Klasa abstrakcyjna kontra interfejs</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Klasa abstrakcyjna</th><th>Interfejs</th></tr></thead><tbody><tr><td>Liczba</td><td>można rozszerzyć <strong>jedną</strong></td><td>można implementować <strong>wiele</strong></td></tr><tr><td>Rola</td><td>typ bazowy hierarchii; wyraża <strong>główną intencję</strong> klas potomnych</td><td><strong>kontrakt</strong>, na który klasa się godzi</td></tr><tr><td>Implementacja</td><td>może dostarczyć metody wspólne dla potomków</td><td>metody <code>default</code> od Javy 8</td></tr><tr><td>Przykład</td><td><code>AbstractMap</code> implementuje <code>equals()</code> i inne metody za potomków</td><td><code>Comparable</code> oznacza „te instancje da się porównywać&quot;, niezależnie od ich głównego przeznaczenia</td></tr></tbody></table></div>\n<h3>Ograniczenia składowych interfejsu</h3>\n<ul><li>Pola są <strong>niejawnie <code>public static final</code></strong> — czyli wyłącznie stałe. <strong>Nie da się zdefiniować pola prywatnego ani polowego stanu instancji.</strong></li><li>Metody są niejawnie <code>public</code>, a ponadto (niejawnie) <code>abstract</code> albo <code>default</code>.</li></ul>\n<h3>Czy Java ma wielodziedziczenie?</h3>\n<p><strong>Nie dla klas</strong> — klasa dziedziczy po jednej nadklasie. Ale można implementować wiele interfejsów, a część ich metod może mieć implementację <code>default</code>. To <strong>bezpieczniejszy sposób mieszania funkcjonalności</strong> niż wielodziedziczenie klas.</p>\n<h2>Klasy zagnieżdżone</h2>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Klasa wewnętrzna (inner)</th><th>Statyczna klasa zagnieżdżona</th></tr></thead><tbody><tr><td>Powiązanie</td><td><strong>każda instancja jest związana z instancją klasy zewnętrznej</strong></td><td>niezależna</td></tr><tr><td>Tworzenie</td><td>wymaga instancji zewnętrznej</td><td>jak każda inna klasa</td></tr><tr><td>Ryzyko</td><td>niejawna referencja do obiektu zewnętrznego → <strong>potencjalny wyciek pamięci</strong></td><td>brak</td></tr></tbody></table></div>\n<pre><code class=\"language-java\">// inner — potrzebna instancja zewnętrzna\npublic class OuterClass1 {\n    public class InnerClass {\n        public OuterClass1 getOuterInstance() {\n            return OuterClass1.this;      // dostęp do obiektu zewnętrznego\n        }\n    }\n}\nOuterClass1 outer = new OuterClass1();\nOuterClass1.InnerClass inner = outer.new InnerClass();\n\n// static nested — niezależna\npublic class OuterClass2 {\n    public static class StaticNestedClass { }\n}\nOuterClass2.StaticNestedClass nested = new OuterClass2.StaticNestedClass();</code></pre>\n<blockquote><p>Ta niejawna referencja z klasy wewnętrznej do zewnętrznej to jedna z typowych przyczyn wycieków pamięci → <a href=\"#/Java/JVM_Internals/Memory_Management_And_Garbage_Collection_PL\">Zarządzanie pamięcią i Garbage Collection</a>.</p></blockquote>\n<h2>Klasy anonimowe</h2>\n<p>Klasa „jednorazowa&quot;, definiowana dokładnie tam, gdzie potrzebna jest jej instancja — więc nie potrzebuje nazwy.</p>\n<p>Przed Javą 8 służyły głównie do implementowania interfejsów jednometodowych (<code>Runnable</code>). <strong>Dziś zastąpiły je lambdy</strong>, ale klasy anonimowe wciąż mają sens, gdy potrzebujesz instancji interfejsu z <strong>wieloma</strong> metodami albo klasy z dodatkowym zachowaniem.</p>\n<pre><code class=\"language-java\">// inicjalizacja podwójnym nawiasem — efektowna, ale tworzy anonimową podklasę\nMap&lt;String, Integer&gt; ages = new HashMap&lt;String, Integer&gt;() {{\n    put(&quot;David&quot;, 30);\n    put(&quot;John&quot;, 25);\n}};</code></pre>\n<blockquote><p><strong>Uwaga:</strong> powyższy idiom tworzy anonimową podklasę <code>HashMap</code> trzymającą referencję do klasy otaczającej. Wygląda zgrabnie, a bywa źródłem wycieków i problemów z serializacją. W nowym kodzie: <code>Map.of(...)</code>.</p></blockquote>\n<h2>Sterowanie przepływem</h2>\n<h3><code>if</code> / <code>if-else</code></h3>\n<p><strong>Java dopuszcza wyłącznie wyrażenia typu <code>boolean</code></strong> jako warunek. Inny typ to błąd kompilacji — w odróżnieniu od języków, gdzie <code>if (0)</code> ma sens.</p>\n<h3><code>switch</code></h3>\n<p>Dozwolone typy wyrażenia: <code>byte</code>, <code>short</code>, <code>char</code>, <code>int</code>, ich wrappery, <strong>enumy</strong> i <strong><code>String</code></strong>.</p>\n<p><strong>Fall-through</strong> — brak <code>break</code> powoduje wykonanie wszystkich kolejnych gałęzi aż do pierwszego <code>break</code>, <strong>niezależnie od dopasowania etykiet</strong>:</p>\n<pre><code class=\"language-java\">int operation = 2;\nint number = 10;\n\nswitch (operation) {\n    case 1: number = number + 10; break;\n    case 2: number = number - 4;      // ← brak break\n    case 3: number = number / 3;      // ← wykona się mimo niedopasowania\n    case 4: number = number * 10; break;\n}\n// number == 20, a nie 6</code></pre>\n<p>To bywa <strong>celowe</strong> — gdy chcemy przypisać to samo działanie wielu przypadkom:</p>\n<pre><code class=\"language-java\">switch (month) {\n    case 1: case 3: case 5: case 7: case 8: case 10: case 12:\n        days = 31;\n        break;\n    // ...\n}</code></pre>\n<p><strong>Kiedy <code>switch</code>, a kiedy <code>if-else</code>:</strong> <code>switch</code> wygrywa przy testowaniu <strong>jednej zmiennej</strong> względem wielu pojedynczych wartości lub gdy kilka wartości ma wykonać ten sam kod. <code>if-else</code> — gdy warunki są złożone, dotyczą różnych zmiennych albo zakresów.</p>\n<h3>Pętle i etykiety</h3>\n<p>Java wspiera <code>for</code>, <code>while</code>, <code>do-while</code> oraz <strong>pętlę rozszerzoną</strong> (<code>for-each</code>) po tablicach i <code>Iterable</code>.</p>\n<p>Wyjście przed czasem: <code>break</code> (opuszcza pętlę), <code>continue</code> (przechodzi do następnej iteracji), <code>return</code>.</p>\n<div class=\"table-wrap\"><table><thead><tr><th></th><th>Bez etykiety</th><th>Z etykietą</th></tr></thead><tbody><tr><td><code>break</code></td><td>opuszcza <strong>najbliższą</strong> pętlę</td><td>opuszcza <strong>oznaczoną</strong> pętlę, także zewnętrzną</td></tr><tr><td><code>continue</code></td><td>następna iteracja najbliższej pętli</td><td>następna iteracja <strong>oznaczonej</strong> pętli</td></tr></tbody></table></div>\n<h3><code>try-catch-finally</code></h3>\n<p>Szczegóły, w tym sytuacje, gdy <code>finally</code> <strong>się nie wykona</strong>, oraz <code>try-with-resources</code> → <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_PL\">Obsługa wyjątków i operacje I/O</a>.</p>\n<h2>Pytania rekrutacyjne</h2>\n<p><strong>P: Czy w Javie wszystko jest obiektem?</strong> <strong>O:</strong> Nie. Osiem typów prymitywnych to surowe dane bez metod i nagłówków. Java ma dualny system typów, a wrappery są mostem między nimi.</p>\n<p><strong>P: Czy tablica dziedziczy po <code>Object</code>?</strong> <strong>O:</strong> Tak, również tablica prymitywów. Specyfikacja traktuje tablice jako obiekty.</p>\n<p><strong>P: Czym różni się <code>==</code> od <code>equals()</code>?</strong> <strong>O:</strong> <code>==</code> sprawdza tożsamość referencji (dla prymitywów — równość wartości), <code>equals()</code> sprawdza równość logiczną, o ile klasa ją nadpisała. <code>new</code> zawsze tworzy obiekt, który nie przejdzie testu <code>==</code>.</p>\n<p><strong>P: Kiedy klasa abstrakcyjna, a kiedy interfejs?</strong> <strong>O:</strong> Klasa abstrakcyjna, gdy modelujesz hierarchię i chcesz dzielić implementację. Interfejs, gdy definiujesz kontrakt, który klasy o różnym przeznaczeniu mogą spełniać — i gdy potrzebujesz wielu takich kontraktów naraz.</p>\n<p><strong>P: Dlaczego klasa wewnętrzna może powodować wyciek pamięci?</strong> <strong>O:</strong> Bo trzyma niejawną referencję do instancji klasy zewnętrznej. Jeśli obiekt wewnętrzny przeżyje zewnętrzny, blokuje jego zebranie.</p>\n<h2>Pułapki</h2>\n<ul><li><strong><code>boolean</code> nie ma zdefiniowanego rozmiaru</strong> w specyfikacji JVM — nie licz na 1 bit.</li><li><strong><code>char</code> jest bez znaku</strong>, jako jedyny spośród typów całkowitych.</li><li><strong>Autoboxing w pętli</strong> generuje tysiące obiektów <code>Integer</code> — koszt, który łatwo przeoczyć.</li><li><strong><code>==</code> na wrapperach</strong> działa „przypadkiem&quot; dla małych wartości przez cache <code>Integer</code> (−128…127) i zawodzi powyżej. Nigdy nie porównuj wrapperów przez <code>==</code>.</li><li><strong>Fall-through w <code>switch</code></strong> jest domyślny i cichy. Nowoczesna składnia <code>switch</code> ze strzałką (<code>-&gt;</code>) go eliminuje.</li></ul>\n<h2>Powiązane</h2>\n<p><a href=\"#/Java/Language_Fundamentals/OOP_Concepts_PL\">Koncepcje obiektowe — dziedziczenie, abstrakcja, polimorfizm</a> · <a href=\"#/Java/Language_Fundamentals/Exception_Handling_And_IO_PL\">Obsługa wyjątków i operacje I/O</a> · <a href=\"#/Java/Collections/Collections_Framework_Cheatsheet_PL\">Collections Framework — ściągawka</a> · <a href=\"#/Java/Language_Fundamentals/Type_System_And_Language_Building_Blocks_EN\">Type system and language building blocks</a></p>"},"Java/garbage collection":{"title":"garbage collection","category":"Java","date":"","tags":[],"minutes":1,"lead":"","html":""},"Java/heap":{"title":"heap","category":"Java","date":"","tags":[],"minutes":1,"lead":"","html":""},"Java/Record keyword":{"title":"Record keyword","category":"Java","date":"","tags":[],"minutes":1,"lead":"<a href=\"https://www.baeldung.com/java-record-keyword\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.baeldung.com/java-record-keyword</a>","html":"<p>As of JDK 14, we can replace our repetitious data classes with records. <strong>Records are immutable data classes that require only the type and name of fields.</strong></p>\n<p><em>In many cases, this data is <a href=\"https://www.baeldung.com/java-immutable-object\" target=\"_blank\" rel=\"noopener noreferrer\">immutable</a>, since <strong>immutability ensures the <a href=\"https://www.baeldung.com/java-immutable-object#benefits-of-immutability\" target=\"_blank\" rel=\"noopener noreferrer\">validity of the data without synchronization</a></strong>.</em></p>\n<p><em>To accomplish this, we create data classes with the following:</em></p>\n<ol><li><em>private, final field for each piece of data</em></li><li><em>getter for each field</em></li><li><em>public constructor with a corresponding argument for each field</em></li><li><em>equals method that returns true for objects of the same class when all fields match</em></li><li><em>hashCode method that returns the same value when all fields match</em></li><li><em>toString method that includes the name of the class and the name of each field and its corresponding value</em></li></ol>"},"Java/Spring Data JPA - tips":{"title":"Spring Data JPA - tips","category":"Java","date":"","tags":[],"minutes":2,"lead":"<strong>1.Mapping relation 'Many to Many'</strong>","html":"<p>In cases when we have relation many to many (for example: single Budget entity could have multiple users and single user can be assigned to multiple Budgets), we can use @ManyToMany annotation</p>\n<p><span class=\"missing-link\" title=\"Brak pliku w datasource\">Pasted image 20250210204131.png</span></p>\n<p>in 'Budget' entity we have:</p>\n<p>@ManyToMany(mappedBy = &quot;budgets&quot;) // Inverse side of the relationship private Set&lt;User&gt; users;</p>\n<p>and in User entity:</p>\n<p>@ManyToMany(cascade = CascadeType.ALL) @JoinTable( name = &quot;user_budget&quot;, // Join table name joinColumns = @JoinColumn(name = &quot;user_id&quot;), // Foreign key for User inverseJoinColumns = @JoinColumn(name = &quot;budget_id&quot;) // Foreign key for Budget ) private Set&lt;Budget&gt; budgets;</p>\n<ul><li>Join table name: is a name of the table which will be generated to create a relation between both entities</li><li>Join columns (self explainatory) - names of the foreign keys</li></ul>\n<p>2.Creating method which will be used to create budget with assigned users</p>\n<p>Your issue is that you're setting the <code>users</code> field in the <code>Budget</code> entity, but since <code>Budget</code> is the inverse side of the <code>@ManyToMany</code> relationship, changes made to it are not persisted automatically. In a bidirectional <code>@ManyToMany</code> relationship, you should update both sides explicitly.</p>\n<h3>Solution:</h3>\n<p>Update both the <code>Budget</code> and <code>User</code> entities when assigning users to a budget. Modify your <code>createBudget</code> method to explicitly update both sides:</p>\n<p>@Override public Optional&lt;BudgetResponse&gt; createBudget(String budgetName, List&lt;Long&gt; userIds) { try { Budget budget = new Budget(); budget.setName(budgetName);</p>\n<p>List&lt;User&gt; users = userRepository.findAllById(userIds); Set&lt;User&gt; userSet = new HashSet&lt;&gt;(users); budget.setUsers(userSet);</p>\n<p>// Important: Update users to include the new budget for (User user : users) { user.getBudgets().add(budget); }</p>\n<p>Budget createdBudget = budgetRepository.save(budget); userRepository.saveAll(users); // Ensure users are updated in DB</p>\n<p>return Optional.of(new BudgetResponse( createdBudget.getId(), createdBudget.getName(), users.stream().map(User::getEmail).collect(Collectors.toList()) )); } catch (Exception e) { e.printStackTrace(); return Optional.empty(); } }</p>\n<p>Explanation:</p>\n<ol><li><strong>Fetching Users Properly</strong>: Instead of fetching users one by one (<code>userRepository.findById(userId).get()</code>), use <code>userRepository.findAllById(userIds)</code> to fetch them efficiently in a single query.</li><li><strong>Updating Both Sides</strong>:<ul><li>You set <code>budget.setUsers(userSet)</code>, which updates the inverse side of the relationship.</li><li>Then, you explicitly update the <code>User</code> entities by adding the <code>budget</code> to <code>user.getBudgets()</code>.</li></ul></li><li><strong>Persisting Changes</strong>:<ul><li><code>budgetRepository.save(budget)</code>: Saves the new <code>Budget</code> entity.</li><li><code>userRepository.saveAll(users)</code>: Ensures that the changes to the <code>User</code> entities (i.e., the relationship update) are persisted.</li></ul></li></ol>\n<p>This should correctly insert records into the <code>user_budget</code> join table. 🚀</p>\n<p>4o</p>"},"Java/Spring Security":{"title":"Spring Security","category":"Java","date":"","tags":[],"minutes":1,"lead":"1. If you configure the filterChain in Spring Security, for example, to perform additional analysis of the request body before the request reaches the target endpoint, remember that the InputStream from HttpServletRequest can only be consumed once. To ensure it remains available for the next doFilter methods, you need to use an object that allows storing a copy of this input stream, such as CachedBodyHttpServletRequest.","html":""},"Microservices/Spring Boot - Autentykacja z JWT_PL":{"title":"Autentykacja JWT w mikroserwisach Spring Boot oraz alternatywy dla Keycloak","category":"Microservices","date":"2026-11-06","tags":["spring-boot","security","jwt","oauth2","microservices","idp","logto","zitadel"],"minutes":4,"lead":"","html":"<h1>Zabezpieczanie mikroserwisów tokenem JWT - Współczesne standardy</h1>\n<p>Zgodnie ze współczesnymi standardami (Spring Boot 3.x / Spring Security 6.x), pojedynczy mikroserwis <strong>nie powinien w ogóle generować tokenów JWT ani zarządzać hasłami</strong>. Zamiast tego pełni on wyłącznie rolę <strong>OAuth2 Resource Server</strong> (Serwera Zasobów), a za logowanie i wystawianie tokenów odpowiada centralny Identity Provider (IdP), taki jak Keycloak, Auth0 czy Microsoft Entra ID.</p>\n<h2>1. Kluczowe standardy i antywzorce</h2>\n<ul><li>🛑 <strong>Brak własnych filtrów JWT (Antywzorzec):</strong> Najczęstszym błędem ze starych tutoriali jest ręczne pisanie klasy <code>JwtAuthenticationFilter</code> i używanie bibliotek takich jak <code>jjwt</code> do weryfikacji podpisu. Współczesny Spring Security robi to automatycznie, znacznie bezpieczniej i wydajniej.</li><li>🛑 <strong>Klucze symetryczne (Antywzorzec):</strong> Używanie algorytmu HS256 i zaszytego w kodzie <code>secret-key</code> to poważny błąd w świecie mikroserwisów.</li><li>✅ <strong>Klucze asymetryczne (JWKS):</strong> Nowoczesne systemy używają algorytmów asymetrycznych (RS256). Mikroserwis nie zna klucza prywatnego – pobiera dynamicznie z serwera tożsamości klucze publiczne (JWKS) do weryfikacji sygnatur.</li><li>✅ <strong>Restrykcyjna walidacja Claimów:</strong> Sam poprawny podpis to za mało. Mikroserwis musi bezwzględnie weryfikować claimy <code>iss</code> (Issuer - czy token wydał zaufany serwer), <code>exp</code> (Expiration) oraz <code>aud</code> (Audience - czy token był wygenerowany dla tego konkretnego serwisu).</li><li>✅ <strong>Pełna bezstanowość:</strong> Mikroserwis musi całkowicie wyłączyć sesje HTTP (<code>STATELESS</code>), opierając każdy request wyłącznie na weryfikacji nagłówka <code>Authorization: Bearer</code>.</li></ul>\n<hr>\n<h2>2. Implementacja w Spring Boot</h2>\n<p>Wystarczy jeden dodatkowy starter, aby włączyć natywną obsługę Resource Servera.</p>\n<h3>Zależności (Maven)</h3>\n<pre><code class=\"language-xml\">&lt;dependency&gt;\n    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n    &lt;artifactId&gt;spring-boot-starter-security&lt;/artifactId&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n    &lt;artifactId&gt;spring-boot-starter-oauth2-resource-server&lt;/artifactId&gt;\n&lt;/dependency&gt;</code></pre>\n<h3>Konfiguracja (<code>application.yml</code>)</h3>\n<p>Zamiast podawać klucze, podajesz jedynie adres serwera tożsamości. Spring Boot sam pobierze konfigurację (OIDC Discovery) oraz klucze publiczne przy starcie.</p>\n<pre><code class=\"language-yaml\">spring:\n  security:\n    oauth2:\n      resourceserver:\n        jwt:\n          issuer-uri: https://twoj-serwer-auth.com/realms/myrealm # Np. adres Twojego IdP\n          audiences: my-microservice-audience # Opcjonalnie, ale mocno zalecane</code></pre>\n<h3>Konfiguracja Bezpieczeństwa (Java)</h3>\n<p>Kod konfigurujący filtr bezpieczeństwa w pełni oparty na wbudowanym DSL Springa.</p>\n<pre><code class=\"language-java\">import org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.Customizer;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.web.SecurityFilterChain;\n\n@Configuration\n@EnableWebSecurity\npublic class SecurityConfig {\n\n    @Bean\n    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {\n        http\n            // 1. Zabezpieczenie endpointów\n            .authorizeHttpRequests(auth -&gt; auth\n                .requestMatchers(&quot;/api/public/**&quot;).permitAll()\n                .requestMatchers(&quot;/api/admin/**&quot;).hasRole(&quot;ADMIN&quot;)\n                .anyRequest().authenticated()\n            )\n            // 2. Włączenie OAuth2 Resource Server i obsługi JWT\n            .oauth2ResourceServer(oauth2 -&gt; oauth2\n                .jwt(Customizer.withDefaults()) // Domyślnie użyje issuer-uri z application.yml\n            )\n            // 3. Wymuszenie architektury bezstanowej (stateless)\n            .sessionManagement(session -&gt; session\n                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)\n            )\n            // 4. Wyłączenie CSRF (nie jest potrzebne przy tokenach w nagłówku)\n            .csrf(csrf -&gt; csrf.disable());\n\n        return http.build();\n    }\n}</code></pre>\n<p><em>Wskazówka: Domyślnie Spring Security szuka uprawnień w claimie <code>scope</code> lub <code>scp</code>. Jeśli Twój dostawca tożsamości ukrywa role głębiej w strukturze JSON tokenu, konieczne będzie napisanie klasy implementującej <code>JwtAuthenticationConverter</code>.</em></p>\n<hr>\n<h2>3. Lekkie i darmowe alternatywy dla Keycloak</h2>\n<p>Keycloak to potężne narzędzie, ale często bywa zbyt ciężkie, trudne w konfiguracji i zasobożerne dla prostych, autorskich projektów. Do aplikacji webowych i mobilnych świetnie sprawdzają się nowoczesne rozwiązania CIAM (Customer Identity and Access Management), które można łatwo hostować samodzielnie np. przez Docker.</p>\n<h3>Opcja 1: Logto (Najlepsze dla B2C i frontendowców)</h3>\n<p>Stworzone z myślą o programistach budujących aplikacje konsumenckie.</p>\n<ul><li><strong>Wygląd:</strong> Posiada bardzo nowoczesne i minimalistyczne gotowe ekrany logowania. Nie musisz kodować własnych formularzy.</li><li><strong>Integracja:</strong> Posiada dedykowane, proste w użyciu SDK dla Reacta, Vue, Fluttera, iOS i Androida.</li><li><strong>Funkcje:</strong> Skupia się na logowaniu hasłem, Social Login (Google, Apple) oraz procesach rejestracji i odzyskiwania hasła.</li></ul>\n<h3>Opcja 2: ZITADEL (Wydajność i nowoczesność)</h3>\n<p>Szybko rosnąca alternatywa dla Keycloaka.</p>\n<ul><li><strong>Wydajność:</strong> Napisany w języku Go, dzięki czemu zużywa ułamek zasobów RAM/CPU w porównaniu do rozwiązań w Javie.</li><li><strong>Innowacja (Passkeys):</strong> Posiada natywne, świetne wsparcie dla logowania biometrycznego (WebAuthn / FaceID / TouchID) od razu po instalacji.</li><li><strong>Skalowalność:</strong> Posiada zaawansowane zarządzanie organizacjami (dobry wybór pod systemy B2B w przyszłości).</li></ul>\n<h3>Opcja 3: Pocket ID (Minimalizm absolutny)</h3>\n<p>Rozwiązanie idealne do projektów hobbystycznych, gdzie chcesz całkowicie porzucić hasła.</p>\n<ul><li><strong>Działanie:</strong> Ultra-lekki dostawca OIDC (Go + SQLite) służący <strong>wyłącznie</strong> do logowania za pomocą biometrii/kluczy sprzętowych (Passkeys).</li><li><strong>Prostota:</strong> Zero skomplikowanych ról i maili transakcyjnych. Użytkownik skanuje odcisk palca, a aplikacja dostaje gotowy token JWT dla Twojego Spring Boota.</li></ul>"},"Microservices/Spring Boot - Authentication with JWT_ENG":{"title":"JWT Authentication in Spring Boot Microservices and Alternatives to Keycloak","category":"Microservices","date":"2026-11-06","tags":[],"minutes":4,"lead":"","html":"<h1>Securing Microservices with JWT - Modern Standards</h1>\n<p>According to modern standards (Spring Boot 3.x / Spring Security 6.x), a single microservice <strong>should not generate JWT tokens or manage passwords at all</strong>. Instead, it acts exclusively as an <strong>OAuth2 Resource Server</strong>, while a central Identity Provider (IdP) like Keycloak, Auth0, or Microsoft Entra ID is responsible for authentication and issuing tokens.</p>\n<h2>1. Key Standards and Anti-patterns</h2>\n<ul><li>🛑 <strong>No custom JWT filters (Anti-pattern):</strong> The most common mistake from outdated tutorials is manually writing a <code>JwtAuthenticationFilter</code> class and using libraries like <code>jjwt</code> to verify the signature. Modern Spring Security handles this automatically, much more securely, and efficiently.</li><li>🛑 <strong>Symmetric keys (Anti-pattern):</strong> Using the HS256 algorithm with a hardcoded <code>secret-key</code> is a serious security flaw in a microservices architecture.</li><li>✅ <strong>Asymmetric keys (JWKS):</strong> Modern systems use asymmetric algorithms (RS256). The microservice does not know the private key – it dynamically fetches public keys (JWKS) from the identity server to verify signatures.</li><li>✅ <strong>Strict Claim validation:</strong> A valid signature alone is not enough. The microservice must strictly verify the <code>iss</code> (Issuer - was the token issued by a trusted server?), <code>exp</code> (Expiration), and <code>aud</code> (Audience - was the token generated for this specific service?) claims.</li><li>✅ <strong>Full statelessness:</strong> The microservice must completely disable HTTP sessions (<code>STATELESS</code>), relying entirely on the <code>Authorization: Bearer</code> header for each request.</li></ul>\n<h2>2. Implementation in Spring Boot</h2>\n<p>You only need one additional starter to enable native Resource Server support.</p>\n<h3>Dependencies (Maven)</h3>\n<pre><code class=\"language-xml\">&lt;dependency&gt;\n    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n    &lt;artifactId&gt;spring-boot-starter-security&lt;/artifactId&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;\n    &lt;artifactId&gt;spring-boot-starter-oauth2-resource-server&lt;/artifactId&gt;\n&lt;/dependency&gt;</code></pre>\n<h3>Configuration (<code>application.yml</code>)</h3>\n<p>Instead of providing secret keys, you only provide the URL of your identity server. Spring Boot will automatically fetch the configuration (OIDC Discovery) and public keys on startup.</p>\n<pre><code class=\"language-yaml\">spring:\n  security:\n    oauth2:\n      resourceserver:\n        jwt:\n          issuer-uri: https://your-auth-server.com/realms/myrealm # E.g., your IdP URL\n          audiences: my-microservice-audience # Optional, but highly recommended</code></pre>\n<h3>Security Configuration (Java)</h3>\n<p>The code configuring the security filter is fully based on Spring's built-in DSL.</p>\n<pre><code class=\"language-java\">import org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.Customizer;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.web.SecurityFilterChain;\n\n@Configuration\n@EnableWebSecurity\npublic class SecurityConfig {\n\n    @Bean\n    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {\n        http\n            // 1. Secure endpoints\n            .authorizeHttpRequests(auth -&gt; auth\n                .requestMatchers(&quot;/api/public/**&quot;).permitAll()\n                .requestMatchers(&quot;/api/admin/**&quot;).hasRole(&quot;ADMIN&quot;)\n                .anyRequest().authenticated()\n            )\n            // 2. Enable OAuth2 Resource Server and JWT support\n            .oauth2ResourceServer(oauth2 -&gt; oauth2\n                .jwt(Customizer.withDefaults()) // Uses issuer-uri from application.yml by default\n            )\n            // 3. Enforce stateless architecture\n            .sessionManagement(session -&gt; session\n                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)\n            )\n            // 4. Disable CSRF (not needed with stateless token-based authentication)\n            .csrf(csrf -&gt; csrf.disable());\n\n        return http.build();\n    }\n}</code></pre>\n<p><em>Tip: By default, Spring Security looks for permissions in the <code>scope</code> or <code>scp</code> claim. If your identity provider hides roles deeper within the token's JSON structure, you will need to write a class that implements <code>JwtAuthenticationConverter</code>.</em></p>\n<h2>3. Lightweight and Free Alternatives to Keycloak</h2>\n<p>Keycloak is a powerful tool, but it can be too heavy, complex to configure, and resource-intensive for simple, custom projects. For web and mobile applications, modern CIAM (Customer Identity and Access Management) solutions are a great fit and can be easily self-hosted using Docker.</p>\n<h3>Option 1: Logto (Best for B2C and Frontend Developers)</h3>\n<p>Designed specifically for developers building consumer-facing apps.</p>\n<ul><li><strong>Appearance:</strong> Features highly modern and minimalist out-of-the-box login screens. You don't have to code your own authentication UI.</li><li><strong>Integration:</strong> Provides dedicated, easy-to-use SDKs for React, Vue, Flutter, iOS, and Android.</li><li><strong>Features:</strong> Focuses on password login, Social Login (Google, Apple), registration flows, and password recovery.</li></ul>\n<h3>Option 2: ZITADEL (Performance and Modernity)</h3>\n<p>A rapidly growing alternative to Keycloak.</p>\n<ul><li><strong>Performance:</strong> Written in Go, meaning it consumes a fraction of the RAM/CPU compared to Java-based solutions.</li><li><strong>Innovation (Passkeys):</strong> Offers native, excellent support for biometric login (WebAuthn / FaceID / TouchID) right out of the box.</li><li><strong>Scalability:</strong> Includes advanced organization management (making it a great choice for future B2B systems).</li></ul>\n<h3>Option 3: Pocket ID (Absolute Minimalism)</h3>\n<p>The perfect solution for hobby projects where you want to ditch passwords entirely.</p>\n<ul><li><strong>Operation:</strong> An ultra-lightweight OIDC provider (Go + SQLite) designed <strong>exclusively</strong> for login via biometrics or hardware keys (Passkeys).</li><li><strong>Simplicity:</strong> Zero complex roles or transactional emails. The user scans their fingerprint, and the app receives a valid JWT token ready for your Spring Boot backend.</li></ul>"},"System design/Common problems - ENG":{"title":"Common problems - ENG","category":"System design","date":"","tags":[],"minutes":3,"lead":"","html":"<h1>System Design – Interview Compendium</h1>\n<ul><li><strong>Slow reads</strong> ➔ <code>Add a cache</code><ul><li><strong>Mechanism:</strong> Slow read operations are optimized by introducing a caching layer.</li><li><strong>Interview aspects:</strong> It is worth discussing invalidation strategies (Cache-Aside, Write-Through) and managing eventual consistency using in-memory data stores (e.g., Redis, Memcached).</li></ul></li><li><strong>Write spikes</strong> ➔ <code>Buffer with a queue</code><ul><li><strong>Mechanism:</strong> Sudden surges in write requests are mitigated by buffering the traffic through a message queue.</li><li><strong>Interview aspects:</strong> Utilizing a message broker (e.g., <span class=\"missing-link\" title=\"Brak notatki w datasource\">Apache Kafka</span>) protects the database from being overwhelmed, but requires adopting an asynchronous processing model.</li></ul></li><li><strong>Too much traffic</strong> ➔ <code>Add a load balancer</code><ul><li><strong>Mechanism:</strong> Excessive incoming traffic is managed by implementing a Load Balancer to distribute requests across multiple instances.</li><li><strong>Interview aspects:</strong> Maintaining stateless server architecture is crucial, along with knowledge of traffic distribution algorithms (L4 vs L7, e.g., Ingress controllers in <span class=\"missing-link\" title=\"Brak notatki w datasource\">Kubernetes</span>).</li></ul></li><li><strong>Read-heavy DB</strong> ➔ <code>Add read replicas</code><ul><li><strong>Mechanism:</strong> Scaling a database dominated by read queries is achieved by adding read replicas.</li><li><strong>Interview aspects:</strong> Emphasize the <em>replication lag</em> problem (e.g., in <span class=\"missing-link\" title=\"Brak notatki w datasource\">PostgreSQL</span>) and the architectural pattern of segregating <code>SELECT</code> queries from state-mutating commands (CQRS).</li></ul></li><li><strong>Write-heavy DB</strong> ➔ <code>Shard the data</code><ul><li><strong>Mechanism:</strong> When the database bottleneck is caused by massive write volumes, the optimal solution is data partitioning (sharding).</li><li><strong>Interview aspects:</strong> Point out the operational complexity of selecting an appropriate <em>Shard Key</em> and the inability to easily execute cross-node <code>JOIN</code> operations.</li></ul></li><li><strong>Slow queries</strong> ➔ <code>Add indexes</code><ul><li><strong>Mechanism:</strong> Poorly performing database queries are optimized by creating appropriate indexes.</li><li><strong>Interview aspects:</strong> A B-Tree index significantly accelerates data retrieval but introduces a performance penalty for write operations (<code>INSERT</code>, <code>UPDATE</code>) and consumes additional storage space.</li></ul></li><li><strong>Slow file loads</strong> ➔ <code>Object storage + CDN</code><ul><li><strong>Mechanism:</strong> Sluggish static asset loading is resolved by placing files in object storage combined with a Content Delivery Network (CDN).</li><li><strong>Interview aspects:</strong> Highlight the architectural advantage of caching and serving static content at edge nodes closest to the end user, utilizing cloud solutions (e.g., <span class=\"missing-link\" title=\"Brak notatki w datasource\">GCP</span> Cloud Storage).</li></ul></li><li><strong>Temporary failures</strong> ➔ <code>Retry with backoff</code><ul><li><strong>Mechanism:</strong> The system should handle transient network errors by applying a delayed retry strategy.</li><li><strong>Interview aspects:</strong> Always mention adding a randomization factor (<em>Jitter</em>) alongside an <em>Exponential Backoff</em> algorithm to protect recovering downstream services from synchronized retry floods (<em>thundering herd problem</em>).</li></ul></li><li><strong>Too many requests</strong> ➔ <code>Rate limiting</code><ul><li><strong>Mechanism:</strong> The system protects its resources from excessive incoming requests by enforcing throughput limits.</li><li><strong>Interview aspects:</strong> This pattern shields API Gateways from abuse and DDoS attacks; familiarity with algorithms like <em>Token Bucket</em> or <em>Leaky Bucket</em> is highly valued.</li></ul></li><li><strong>One service failing</strong> ➔ <code>Circuit breaker</code><ul><li><strong>Mechanism:</strong> A single component's failure is isolated to prevent cascading system outages using the circuit breaker pattern.</li><li><strong>Interview aspects:</strong> Demonstrate an understanding of the <em>fail-fast</em> philosophy that prevents thread pool exhaustion (e.g., in <span class=\"missing-link\" title=\"Brak notatki w datasource\">Spring Boot</span> microservices) and discuss the states: closed, open, and half-open (e.g., using Resilience4j).</li></ul></li><li><strong>Duplicate requests</strong> ➔ <code>Idempotency keys</code><ul><li><strong>Mechanism:</strong> To prevent unintended double processing of operations, API requests are secured with idempotency keys.</li><li><strong>Interview aspects:</strong> This is a fundamental requirement in event-driven systems, ensuring that duplicate messages do not compromise state consistency (especially critical in financial transactions).</li></ul></li><li><strong>Can't see what broke</strong> ➔ <code>Logs, metrics, tracing</code><ul><li><strong>Mechanism:</strong> Difficulties in diagnosing root causes are resolved by implementing a comprehensive observability stack: logs, metrics, and distributed tracing.</li><li><strong>Interview aspects:</strong> Centralized observability involves aggregating full-text logs (e.g., <span class=\"missing-link\" title=\"Brak notatki w datasource\">Elasticsearch</span>), visualizing telemetry data on dashboards (e.g., <span class=\"missing-link\" title=\"Brak notatki w datasource\">Grafana</span>), and propagating <code>Trace ID</code> headers across distributed microservices.</li></ul></li></ul>"},"System design/Common problems - PL":{"title":"Common problems - PL","category":"System design","date":"","tags":[],"minutes":3,"lead":"","html":"<h1>System Design – Kompendium Rekrutacyjne</h1>\n<ul><li><strong>Wolne odczyty (Slow reads)</strong> ➔ <code>Add a cache</code><ul><li><strong>Mechanizm:</strong> Zbyt wolne odczyty optymalizuje się poprzez dodanie pamięci podręcznej.</li><li><strong>Aspekty rekrutacyjne:</strong> Warto omówić strategie inwalidacji (Cache-Aside, Write-Through) oraz zarządzanie opóźnioną spójnością danych, wykorzystując rozwiązania in-memory (np. Redis, Memcached).</li></ul></li><li><strong>Skokowy wzrost zapisów (Write spikes)</strong> ➔ <code>Buffer with a queue</code><ul><li><strong>Mechanizm:</strong> Na nagłe skoki ilości zapisów reaguje się buforowaniem ruchu za pomocą kolejki.</li><li><strong>Aspekty rekrutacyjne:</strong> Użycie brokera wiadomości (np. <span class=\"missing-link\" title=\"Brak notatki w datasource\">Apache Kafka</span>) chroni bazę przed przeciążeniem, narzucając wdrożenie przetwarzania asynchronicznego.</li></ul></li><li><strong>Zbyt duży ruch (Too much traffic)</strong> ➔ <code>Add a load balancer</code><ul><li><strong>Mechanizm:</strong> Nadmierny ruch w systemie opanowuje się przez wdrożenie mechanizmu równoważenia obciążenia (Load Balancer).</li><li><strong>Aspekty rekrutacyjne:</strong> Kluczowe jest utrzymanie bezstanowości serwerów (stateless) oraz znajomość algorytmów dystrybucji ruchu (L4 vs L7, np. Ingress w <span class=\"missing-link\" title=\"Brak notatki w datasource\">Kubernetes</span>).</li></ul></li><li><strong>Baza obciążona odczytami (Read-heavy DB)</strong> ➔ <code>Add read replicas</code><ul><li><strong>Mechanizm:</strong> Skalowanie bazy danych zdominowanej przez zapytania odczytujące wymaga dodania replik odczytu.</li><li><strong>Aspekty rekrutacyjne:</strong> Podkreśl problem opóźnienia replikacji (<em>replication lag</em>) – np. w <span class=\"missing-link\" title=\"Brak notatki w datasource\">PostgreSQL</span> – oraz fizyczne rozdzielenie komend <code>SELECT</code> od operacji modyfikujących stan.</li></ul></li><li><strong>Baza obciążona zapisami (Write-heavy DB)</strong> ➔ <code>Shard the data</code><ul><li><strong>Mechanizm:</strong> Gdy głównym obciążeniem bazy są liczne zapisy, optymalnym wyjściem jest podzielenie danych, czyli sharding.</li><li><strong>Aspekty rekrutacyjne:</strong> Zwróć uwagę na trudność operacyjną przy doborze klucza partycjonowania (<em>Shard Key</em>) oraz brak możliwości prostego łączenia danych (<code>JOIN</code>) między węzłami.</li></ul></li><li><strong>Wolne zapytania bazy danych (Slow queries)</strong> ➔ <code>Add indexes</code><ul><li><strong>Mechanizm:</strong> Niską wydajność zapytań bazodanowych koryguje się przez dodanie indeksów.</li><li><strong>Aspekty rekrutacyjne:</strong> Indeks oparty na B-Tree przyspiesza odczyt, ale nakłada narzut wydajnościowy na modyfikacje (<code>INSERT</code>, <code>UPDATE</code>) oraz wymaga dodatkowej przestrzeni dyskowej.</li></ul></li><li><strong>Wolne ładowanie plików (Slow file loads)</strong> ➔ <code>Object storage + CDN</code><ul><li><strong>Mechanizm:</strong> Powolne ładowanie zasobów neutralizuje się umieszczając je w pamięci obiektowej połączonej z siecią dostarczania treści (CDN).</li><li><strong>Aspekty rekrutacyjne:</strong> Zaznacz korzyść serwowania plików blisko użytkownika docelowego, wspominając o chmurze (np. <span class=\"missing-link\" title=\"Brak notatki w datasource\">GCP</span> Cloud Storage) w parze z mechanizmami brzegowymi.</li></ul></li><li><strong>Tymczasowe awarie (Temporary failures)</strong> ➔ <code>Retry with backoff</code><ul><li><strong>Mechanizm:</strong> Na tymczasowe błędy sieciowe system powinien odpowiadać strategią ponawiania z opóźnieniem.</li><li><strong>Aspekty rekrutacyjne:</strong> Należy wspomnieć o czynniku losowym (<em>Jitter</em>) łączonym z rosnącym opóźnieniem (<em>Exponential Backoff</em>), aby uchronić usługę przed zmasowanym atakiem (<em>thundering herd problem</em>).</li></ul></li><li><strong>Zbyt duża liczba zapytań (Too many requests)</strong> ➔ <code>Rate limiting</code><ul><li><strong>Mechanizm:</strong> System zabezpiecza się przed nadmiarem zapytań, limitując przepustowość.</li><li><strong>Aspekty rekrutacyjne:</strong> Chroni to węzły API Gateway przed nadużyciami; przydatna jest znajomość algorytmów takich jak <em>Token Bucket</em> czy <em>Leaky Bucket</em>.</li></ul></li><li><strong>Awaria pojedynczej usługi (One service failing)</strong> ➔ <code>Circuit breaker</code><ul><li><strong>Mechanizm:</strong> Uszkodzenia jednego komponentu izoluje się przed kaskadowym rozprzestrzenianiem, stosując wzorzec wyłącznika obwodu.</li><li><strong>Aspekty rekrutacyjne:</strong> Zaprezentuj zrozumienie filozofii <em>fail-fast</em> chroniącej pule wątków (np. w mikroserwisach <span class=\"missing-link\" title=\"Brak notatki w datasource\">Spring Boot</span>) oraz omów stany: zamknięty, otwarty, półotwarty (np. biblioteka Resilience4j).</li></ul></li><li><strong>Zduplikowane zapytania (Duplicate requests)</strong> ➔ <code>Idempotency keys</code><ul><li><strong>Mechanizm:</strong> Aby uniknąć podwójnego przetworzenia operacji, zabezpiecza się je stosując klucze idempotencyjności.</li><li><strong>Aspekty rekrutacyjne:</strong> Fundament systemów zdarzeniowych, gwarantujący, że zduplikowana wiadomość nie zepsuje spójności stanów (krytyczne w finansach).</li></ul></li><li><strong>Brak wglądu w awarie (Can't see what broke)</strong> ➔ <code>Logs, metrics, tracing</code><ul><li><strong>Mechanizm:</strong> Trudności z diagnozą źródła problemu rozwiązuje wdrożenie logów, metryk i rozproszonego śledzenia.</li><li><strong>Aspekty rekrutacyjne:</strong> Łączenie pełnotekstowych dzienników (np. <span class=\"missing-link\" title=\"Brak notatki w datasource\">Elasticsearch</span>), wizualizacji na pulpitach (np. <span class=\"missing-link\" title=\"Brak notatki w datasource\">Grafana</span>) oraz propagacji identyfikatorów <code>Trace ID</code> pomiędzy mikroserwisami.</li></ul></li></ul>"},"about":{"title":"About me","category":"","date":"","tags":[],"minutes":1,"lead":"[KRÓTKI OPIS — kim jesteś i o czym jest ten blog]","html":"<h2>Czym jest ten blog</h2>\n<p>MBS. Knowledge Hub Blog to publiczna część mojego notatnika technicznego. Struktura kategorii po lewej stronie odwzorowuje katalogi w lokalnym Knowledge Hubie.</p>\n<h2>Kontakt</h2>\n<p>[ADRES E-MAIL / LINKEDIN / GITHUB]</p>"}}};
